(window.PARENT_DIGEST = window.PARENT_DIGEST || {})[7] = {"grade":7,"subjects":[{"id":"toan","name":"Toán","b":[{"t":"Toán 7, tập 1","c":[{"t":"Chương I. Số hữu tỉ","l":[{"t":"Bài 1. Tập hợp các số hữu tỉ","sum":["Số hữu tỉ là số viết được dưới dạng phân số a/b, với a, b là số nguyên và b khác 0. Tập hợp các số hữu tỉ kí hiệu là Q.","Khái niệm: Số hữu tỉ là số viết được dưới dạng phân số a/b, với a, b là số nguyên và b khác 0.","Số nguyên, số thập phân hữu hạn và hỗn số đều là số hữu tỉ: Ví dụ: 3 = 3/1; -1,2 = -6/5;","Mỗi số hữu tỉ m đều có một số đối là -m: Số đối của -m là m, và số 0 là số đối của chính nó.","Trên trục số, để biểu diễn a/b…: Trên trục số, để biểu diễn a/b, ta chia đoạn đơn vị thành b phần bằng nhau rồi lấy a phần đó (có dấu).","Hai số đối nhau được biểu diễn…: Hai số đối nhau được biểu diễn bởi hai điểm nằm về hai phía khác nhau của điểm O và cách O cùng một khoảng."],"e":["Hay nhầm: Đây chính là số đã cho. Số đối phải có dấu ngược lại.","Hay nhầm: Bạn đã lấy nghịch đảo, không phải số đối. Số đối chỉ đổi dấu, giữ nguyên tử và mẫu.","Hay nhầm: Bạn vừa lấy nghịch đảo vừa đổi dấu. Số đối chỉ đổi dấu.","Hay nhầm: Bạn chỉ lấy phần nguyên làm tử số. Phải nhân phần nguyên với mẫu rồi cộng phần tử.","Hay nhầm: Bạn đã cộng 2 + 3 thay vì 2 × 3 + 1. Hãy nhân phần nguyên với mẫu trước.","Hay nhầm: Bạn đã quên cộng phần tử 1 vào tử số."],"q":{"n":11,"lv":{"Biết":5,"Hiểu":3,"Vận dụng":3}}},{"t":"Bài 2. Cộng, trừ, nhân, chia số hữu tỉ","req":["Mã YCCĐ: cần đối chiếu Thông tư 32/2018"],"sum":["Số hữu tỉ là số viết được dưới dạng a/b với a, b là số nguyên và b khác 0.","Khái niệm: Số hữu tỉ là số viết được dưới dạng a/b với a, b là số nguyên và b khác 0.","Muốn cộng hoặc trừ hai số hữu…: Muốn cộng hoặc trừ hai số hữu tỉ, ta đưa về cùng mẫu dương, rồi cộng hoặc trừ các tử số."],"e":["Hay nhầm: Bạn đã cộng cả mẫu số. Khi cùng mẫu, mẫu giữ nguyên, chỉ cộng tử số.","Hay nhầm: Kết quả 2/6 chưa rút gọn và không đúng mẫu. Khi cùng mẫu 3, mẫu vẫn là 3.","Hay nhầm: Bạn đã nhân mẫu số. Khi cộng phân số cùng mẫu thì mẫu không đổi.","Hay nhầm: Bạn trừ hai số nhưng không quy đồng hai mẫu khác nhau. Hãy quy đồng về mẫu 10 trước.","Hay nhầm: Đây là kết quả khi trừ tử số và mẫu số riêng lẻ, cách đó không đúng với phép trừ phân số.","Hay nhầm: Kết quả này không khớp với phép trừ đã quy đồng về mẫu chung."],"q":{"n":10,"lv":{"Biết":4,"Hiểu":3,"Vận dụng":3}}},{"t":"Bài 3. Luỹ thừa với số mũ tự nhiên của một số hữu tỉ","m":[{"t":"Tính lũy thừa của số hữu tỉ","w":"Đề yêu cầu tính, rút gọn hoặc so sánh các lũy thừa của số hữu tỉ.","s":["Nhận dạng các công thức: xᵐ·xⁿ = xᵐ⁺ⁿ; xᵐ : xⁿ = xᵐ⁻ⁿ; (xᵐ)ⁿ = xᵐⁿ; (x·y)ⁿ = xⁿ·yⁿ; (x/y)ⁿ = xⁿ/yⁿ.","Đưa các lũy thừa về cùng cơ số hoặc cùng số mũ nếu được.","Áp dụng công thức, tính số mũ rồi tính giá trị.","Kiểm tra dấu: lũy thừa mũ chẵn của số âm là số dương, mũ lẻ là số âm."],"n":["Chỉ cộng trừ số mũ khi các lũy thừa có cùng cơ số.","(−x)² = x² nhưng −x² là số âm: cẩn thận với dấu ngoặc.","Lũy thừa của phân số: nâng cả tử và mẫu lên lũy thừa đó."]}],"sum":["Luỹ thừa bậc n của số hữu tỉ x là tích của n thừa số x: xⁿ = x · x · … · x (n thừa số), với n là số tự nhiên lớn hơn 1.","Luỹ thừa bậc n của số hữu tỉ x là tích của n thừa số x: Xⁿ = x · x · … · x (n thừa số), với n là số tự nhiên lớn hơn 1.","Quy ước: X⁰ = 1 (x ≠ 0) và x¹ = x.","Khi tính luỹ thừa của một phân số, ta lũy thừa cả tử và mẫu: Khi nhân hai luỹ thừa cùng cơ số, giữ nguyên cơ số và cộng hai số mũ."],"d":["Tính lũy thừa của số hữu tỉ"],"e":["Hay nhầm: Bạn đã để kết quả âm. Số mũ chẵn cho kết quả dương.","Hay nhầm: Bạn chỉ nhân ba thừa số. Luỹ thừa bậc 4 có bốn thừa số.","Hay nhầm: Bạn chỉ nhân ba thừa số và để kết quả dương. Hãy đếm lại số thừa số.","Hay nhầm: Đây là quy ước sai. Mọi số khác 0 lũy thừa 0 đều bằng 1, không phải 0.","Hay nhầm: Bạn lấy cơ số làm kết quả. Với số mũ 0, kết quả luôn là 1.","Hay nhầm: Bạn đã nhầm dấu. Luỹ thừa bậc 0 luôn bằng 1, không âm."],"q":{"n":15,"lv":{"Biết":6,"Hiểu":4,"Vận dụng":5}}},{"t":"Bài 4. Thứ tự thực hiện các phép tính. Quy tắc chuyển vế","m":[{"t":"Tìm x trong tập số hữu tỉ","w":"Đề cho phương trình dạng x + a = b, a − x = b, k·x + a = b với số hữu tỉ.","s":["Thu gọn từng vế bằng cách thực hiện các phép tính và bỏ ngoặc.","Chuyển vế: chuyển số hạng sang vế kia thì đổi dấu, đưa các số hạng chứa x về một vế.","Thu gọn về dạng k·x = c rồi x = c : k.","Thử lại và viết kết quả dạng phân số tối giản."],"n":["Chuyển vế phải đổi dấu số hạng; nhân hoặc chia hai vế cho cùng một số khác 0 thì giữ nguyên đẳng thức.","Với a − x = b thì x = a − b, đừng viết x = b − a.","Quy đồng mẫu trước khi cộng trừ các phân số."]}],"sum":["Biểu thức có phép cộng và phép trừ, hoặc chỉ có phép nhân và phép chia: thực hiện từ trái sang phải.","Biểu thức có phép cộng và phép trừ, hoặc chỉ có phép nhân và phép chia: Thực hiện từ trái sang phải.","Biểu thức không có dấu ngoặc: Thực hiện luỹ thừa, rồi nhân và chia, cuối cùng cộng và trừ.","Biểu thức có dấu ngoặc: Thực hiện trong ngoặc tròn ( ) trước, rồi đến ngoặc vuông [ ], rồi đến ngoặc nhọn { }.","Quy tắc chuyển vế: Khi chuyển một số hạng từ vế này sang vế kia của đẳng thức, ta đổi dấu số hạng đó (dấu + thành -, dấu - thành +)."],"d":["Tìm x trong tập số hữu tỉ"],"e":["Hay nhầm: Bạn chưa nhân 1/2 với 4 trước khi trừ. Phép nhân được thực hiện trước phép trừ.","Hay nhầm: Bạn đã trừ trước khi nhân, hoặc bỏ qua 1/3. Phép nhân được thực hiện trước phép trừ.","Hay nhầm: Bạn đã quy đồng sai. 2 - 1/3 = 5/3, không phải 11/6.","Hay nhầm: Bạn đã trừ trước khi chia. Phép chia được thực hiện trước phép trừ.","Hay nhầm: Bạn đã đổi dấu sai. Kết quả chia là 3/4, nên 3/4 - 3/4 = 0.","Hay nhầm: Bạn chưa thực hiện phép trừ với kết quả của phép chia."],"q":{"n":15,"lv":{"Biết":3,"Hiểu":7,"Vận dụng":5}}},{"t":"Ôn tập Chương I (20 câu tự luận)"}]},{"t":"Chương II. Số thực","l":[{"t":"Bài 5. Số thập phân hữu hạn. Số thập phân vô hạn tuần hoàn","sum":["Số thập phân hữu hạn là số có hữu hạn chữ số sau dấu phẩy, ví dụ 0,25 = 1/4.","Khái niệm: Số thập phân hữu hạn là số có hữu hạn chữ số sau dấu phẩy, ví dụ 0,25 = 1/4.","Số thập phân vô hạn tuần hoàn…: Số thập phân vô hạn tuần hoàn có phần thập phân lặp lại mãi một nhóm chữ số, gọi là chu kì.","Làm tròn đến một hàng: Giữ các chữ số đến hàng đó.","Khi làm tròn, sai số không vượt…: Khi làm tròn, sai số không vượt quá nửa đơn vị của hàng làm tròn đến."],"e":["Hay nhầm: 0,34 không bằng 3/4. Muốn đổi 3/4 thành số thập phân, hãy chia 3 cho 4 để được 0,75.","Hay nhầm: 0,8 bằng 4/5, không phải 3/4.","Hay nhầm: 0,57 không bằng 3/4. Hãy chia 3 cho 4 để được 0,75.","Hay nhầm: 6 = 2 · 3 có ước nguyên tố 3, nên 1/6 là số thập phân vô hạn tuần hoàn.","Hay nhầm: 9 = 3² có ước nguyên tố 3, nên 2/9 là số thập phân vô hạn tuần hoàn.","Hay nhầm: 12 = 2² · 3 có ước nguyên tố 3, nên 5/12 là số thập phân vô hạn tuần hoàn."],"q":{"n":13,"lv":{"Biết":6,"Hiểu":4,"Vận dụng":3}}},{"t":"Bài 6. Số vô tỉ. Căn bậc hai số học","sum":["Số vô tỉ là số không viết được dưới dạng a/b (a, b ∈ Z, b ≠ 0). Số vô tỉ là số thập phân vô hạn không tuần hoàn.","Khái niệm: Số vô tỉ là số không viết được dưới dạng a/b (a, b ∈ Z, b ≠ 0).","Căn bậc hai số học của số…: Căn bậc hai số học của số a không âm là số x không âm sao cho x² = a.","Nếu a là bình phương của một…: Nếu a là bình phương của một số hữu tỉ không âm thì √a là số hữu tỉ.","Căn bậc hai số học không bao giờ âm: Căn bậc hai của số âm không tồn tại trong tập số thực."],"e":["Hay nhầm: −9 cũng là căn bậc hai của 81 nhưng không phải căn bậc hai số học, vì căn bậc hai số học luôn không âm.","Hay nhầm: 81 là bình phương của 9, không phải căn bậc hai của 81.","Hay nhầm: 8,1 sai vì (8,1)² = 65,61 khác 81.","Hay nhầm: Căn bậc hai số học không âm nên không thể bằng −4.","Hay nhầm: 16 là a², chưa phải căn bậc hai của a².","Hay nhầm: −16 là số âm nên không thể là căn bậc hai số học."],"q":{"n":12,"lv":{"Biết":5,"Hiểu":4,"Vận dụng":3}}},{"t":"Bài 7. Tập hợp các số thực","sum":["Tập số thực R gồm các số hữu tỉ và các số vô tỉ: R = Q ∪ I. Mỗi số thực được biểu diễn bởi đúng một điểm trên trục số thực.","Tập số thực R gồm các số hữu tỉ và các số vô tỉ: R = Q ∪ I.","Mỗi số thực a có một số đối là −a: Số đối của số dương là số âm, số đối của số âm là số dương, số đối của 0 là 0.","So sánh số thực: Số âm nhỏ hơn 0, 0 nhỏ hơn số dương.","Khi so sánh hai số âm, số…: Khi so sánh hai số âm, số có giá trị tuyệt đối lớn hơn thì nhỏ hơn."],"e":["Hay nhầm: −2,5 chính là số đã cho, không phải số đối của nó.","Hay nhầm: 1/2 không liên quan đến −2,5.","Hay nhầm: Số đối của −2,5 là 2,5, không phải −1/2.","Hay nhầm: −1/2 = −0,5 nhỏ hơn −2/5 = −0,4.","Hay nhầm: −2/3 ≈ −0,67 có giá trị tuyệt đối lớn hơn −2/5 nên nhỏ hơn −2/5.","Hay nhầm: −3/4 = −0,75 là số nhỏ nhất trong bốn số, không phải lớn nhất."],"q":{"n":12,"lv":{"Biết":5,"Hiểu":4,"Vận dụng":3}}},{"t":"Ôn tập Chương II (20 câu tự luận)"}]},{"t":"Chương III. Góc và đường thẳng song song","l":[{"t":"Bài 8. Hai góc đối đỉnh. Hai góc kề bù. Tia phân giác","sum":["Hai góc kề bù có chung một cạnh, hai cạnh còn lại là hai tia đối nhau. Tổng số đo hai góc kề bù bằng 180°.","Khái niệm: Hai góc kề bù có chung một cạnh, hai cạnh còn lại là hai tia đối nhau.","Hai góc đối đỉnh: Mỗi cạnh của góc này là tia đối của một cạnh của góc kia.","Tia phân giác của một góc là…: Tia phân giác của một góc là tia nằm giữa hai cạnh của góc và tạo với hai cạnh hai góc bằng nhau.","Lỗi thường gặp: Nhầm hai góc kề bù với hai góc kề nhau (kề bù bắt buộc có tổng 180°); cho rằng hai góc bằng nhau thì là đối đỉnh."],"e":["Hay nhầm: 70° là số đo của góc đã cho. Hai góc kề bù phải có tổng 180°, nên 70° + 70° = 140° không đúng.","Hay nhầm: 180° là tổng của hai góc kề bù, không phải số đo của một góc.","Hay nhầm: 20° không thỏa mãn: 70° + 20° = 90°, không phải 180°.","Hay nhầm: 84° là số đo cả góc xOy, không phải góc xOz. Tia phân giác chia góc thành hai phần bằng nhau.","Hay nhầm: 168° là 2 · 84°, đây là phép nhân sai; tia phân giác phải chia đôi góc.","Hay nhầm: 21° là 84° chia 4, không phải chia 2."],"q":{"n":11,"lv":{"Biết":5,"Hiểu":3,"Vận dụng":3}}},{"t":"Bài 9. Hai đường thẳng song song. Dấu hiệu nhận biết","m":[{"t":"Tính số đo góc khi có hai đường thẳng song song","w":"Đề cho hai đường thẳng song song a // b bị cắt bởi đường thẳng c và cho một số đo góc, hỏi góc khác.","s":["Nhận dạng các cặp góc tạo bởi đường cắt c: so le trong, đồng vị, trong cùng phía.","Dùng tính chất khi a // b: so le trong bằng nhau, đồng vị bằng nhau, trong cùng phía bù nhau (tổng 180°).","Kết hợp thêm hai góc kề bù (tổng 180°) hoặc đối đỉnh (bằng nhau) để chuyển sang góc cần tìm.","Tính, kiểm tra lại bằng một cặp góc khác."],"n":["Chỉ dùng các tính chất trên khi đã biết a // b.","Trong cùng phía thì bù nhau chứ không bằng nhau.","Hai góc kề bù có tổng 180°, hai góc đối đỉnh thì bằng nhau."]}],"sum":["Khi đường thẳng c cắt hai đường thẳng a và b, ta có các cặp góc: góc so le trong, góc đồng vị và góc trong cùng phía.","Khi đường thẳng c cắt hai đường thẳng a và b, ta có các cặp góc: Góc so le trong, góc đồng vị và góc trong cùng phía.","Dấu hiệu nhận biết: Nếu có một cặp góc so le trong bằng nhau, hoặc một cặp góc đồng vị bằng nhau, hoặc một cặp góc trong cùng phía bù nhau thì a ∥ b.","Hai đường thẳng cùng vuông góc với…: Hai đường thẳng cùng vuông góc với đường thẳng thứ ba thì song song với nhau.","Lỗi thường gặp: Nhầm góc so le trong với góc trong cùng phía khi đọc hình."],"d":["Tính số đo góc khi có hai đường thẳng song song"],"e":["Hay nhầm: 115° là số đo góc bù với 65°. Góc so le trong thì bằng nhau, không bù nhau.","Hay nhầm: 25° là 90° − 65°, không liên quan đến cặp góc so le trong.","Hay nhầm: 75° không phải số đo góc so le trong với 65° khi a ∥ b.","Lưu ý: Chỉ dùng các tính chất trên khi đã biết a // b.","Lưu ý: Trong cùng phía thì bù nhau chứ không bằng nhau.","Lưu ý: Hai góc kề bù có tổng 180°, hai góc đối đỉnh thì bằng nhau."],"q":{"n":14,"lv":{"Biết":4,"Hiểu":6,"Vận dụng":4}}},{"t":"Bài 10. Tiên đề Euclid. Tính chất của hai đường thẳng song song","sum":["Tiên đề Euclid: qua một điểm nằm ngoài một đường thẳng, chỉ vẽ được đúng một đường thẳng song song với đường thẳng đó.","Tiên đề Euclid: Qua một điểm nằm ngoài một đường thẳng, chỉ vẽ được đúng một đường thẳng song song với đường thẳng đó.","Tính chất: Nếu a ∥ b thì hai góc so le trong bằng nhau, hai góc đồng vị bằng nhau, hai góc trong cùng phía bù nhau.","Hệ quả: Nếu một đường thẳng cắt một trong hai đường thẳng song song thì nó cũng cắt đường thẳng còn lại.","Lỗi thường gặp: Áp dụng tính chất của hai đường thẳng song song khi chưa biết chúng đã song song."],"e":["Hay nhầm: Luôn vẽ được một đường thẳng song song với d qua M nằm ngoài d, không phải không có.","Hay nhầm: Tiên đề Euclid khẳng định chỉ có đúng một đường thẳng, không phải hai.","Hay nhầm: Không có ba đường thẳng nào như vậy; tiên đề Euclid chỉ cho phép một đường thẳng.","Hay nhầm: 70° là số đo góc bù với 110°. Góc đồng vị thì bằng nhau, không bù nhau.","Hay nhầm: 180° là tổng hai góc kề bù, không phải số đo góc đồng vị.","Hay nhầm: 55° là nửa của 110°, không có tính chất nào như vậy."],"q":{"n":10,"lv":{"Biết":4,"Hiểu":4,"Vận dụng":2}}},{"t":"Bài 11. Định lí. Chứng minh định lí","sum":["Định lí là một khẳng định được suy ra từ những khẳng định đã biết. Định lí thường được phát biểu dưới dạng: Nếu … thì ….","Khái niệm: Định lí là một khẳng định được suy ra từ những khẳng định đã biết.","Phần sau từ “nếu” là giả thiết…: Phần sau từ “nếu” là giả thiết (GT), phần sau từ “thì” là kết luận (KL).","Ví dụ: Nếu một đường thẳng vuông góc với một trong hai đường thẳng song song thì nó cũng vuông góc với đường thẳng còn lại.","Các tính chất thường dùng trong chứng minh: Góc so le trong, góc đồng vị, góc trong cùng phía và tiên đề Euclid."],"e":["Hay nhầm: 45° không xuất hiện trong giả thiết hay kết luận của định lí.","Hay nhầm: 180° là góc bẹt, không phải góc vuông.","Hay nhầm: 0° nghĩa là hai đường thẳng trùng nhau, không đúng với giả thiết c ⊥ a."],"q":{"n":9,"lv":{"Biết":3,"Hiểu":4,"Vận dụng":2}}},{"t":"Ôn tập Chương III (20 câu tự luận)"}]},{"t":"Chương IV. Tam giác bằng nhau","l":[{"t":"Bài 12. Tổng các góc trong một tam giác","m":[{"t":"Tính số đo góc trong tam giác","w":"Đề cho hai góc của tam giác (hoặc tam giác cân, vuông, góc ngoài) và yêu cầu tính góc còn lại.","s":["Xác định các góc đã biết và góc cần tìm; chú ý tam giác vuông (một góc 90°) hoặc cân (hai góc đáy bằng nhau).","Áp dụng tổng ba góc của một tam giác bằng 180°.","Với góc ngoài: góc ngoài bằng tổng hai góc trong không kề với nó.","Tính, kiểm tra tổng ba góc và ghi kết quả có đơn vị độ."],"n":["Tam giác vuông: hai góc nhọn phụ nhau (tổng 90°).","Tam giác cân: góc ở đỉnh + 2·góc đáy = 180°.","Góc ngoài lớn hơn mỗi góc trong không kề với nó."]}],"sum":["Tổng ba góc trong một tam giác bằng 180°. Chứng minh: qua một đỉnh kẻ đường thẳng song song với cạnh đối diện, rồi dùng tính chất góc so le trong.","Tổng ba góc trong một tam giác bằng 180°: Chứng minh: qua một đỉnh kẻ đường thẳng song song với cạnh đối diện, rồi dùng tính chất góc so le trong.","Góc ngoài tại một đỉnh của tam…: Góc ngoài tại một đỉnh của tam giác bằng tổng hai góc trong không kề với đỉnh đó.","Tam giác nhọn có ba góc nhọn: Tam giác vuông có một góc vuông; trong tam giác vuông, hai góc nhọn phụ nhau (tổng 90°), cạnh đối diện góc vuông là cạnh huyền.","Lỗi thường gặp: Quên rằng trong tam giác vuông hai góc nhọn có tổng 90°, không phải 180°; cộng nhầm góc ngoài với góc kề trong thay vì tổng hai góc trong không kề."],"d":["Tính số đo góc trong tam giác"],"e":["Hay nhầm: 35° là góc B, không phải góc C.","Hay nhầm: 145° là 180° − 35°, nhưng hai góc nhọn trong tam giác vuông có tổng 90°, không phải 180°.","Hay nhầm: 90° là góc vuông A, không phải góc C.","Hay nhầm: 130° là góc ngoài tại A, không phải góc C.","Hay nhầm: 50° là góc B, không phải góc C.","Hay nhầm: 180° là tổng ba góc của tam giác, không phải góc C."],"q":{"n":15,"lv":{"Biết":5,"Hiểu":5,"Vận dụng":5}}},{"t":"Bài 13. Hai tam giác bằng nhau. Trường hợp c.c.c","sum":["ΔABC = ΔA'B'C' khi ba cạnh và ba góc tương ứng bằng nhau. Kí hiệu đỉnh phải viết đúng thứ tự tương ứng: A với A', B với B', C với C'.","ΔABC = ΔA'B'C' khi ba cạnh và ba góc tương ứng bằng nhau: Kí hiệu đỉnh phải viết đúng thứ tự tương ứng: A với A', B với B', C với C'.","Trường hợp c.c.c: nếu ba cạnh của…: Trường hợp c.c.c: nếu ba cạnh của tam giác này bằng ba cạnh của tam giác kia thì hai tam giác đó bằng nhau.","Lỗi thường gặp: Viết kí hiệu bằng nhau với các đỉnh không đúng thứ tự tương ứng, ví dụ viết ΔABC = ΔDFE khi A ↔ D, B ↔ E, C ↔ F."],"e":["Hay nhầm: 110° là 180° − 70°, không phải góc tương ứng với A.","Hay nhầm: 20° là 90° − 70°, không liên quan đến góc tương ứng.","Hay nhầm: 35° là nửa của 70°, không phải góc tương ứng."],"q":{"n":10,"lv":{"Biết":4,"Hiểu":3,"Vận dụng":3}}},{"t":"Bài 14. Trường hợp bằng nhau thứ hai và thứ ba của tam giác","sum":["Góc xen giữa hai cạnh là góc nằm giữa hai cạnh đó. Ví dụ góc A là góc xen giữa AB và AC.","Góc xen giữa hai cạnh là góc nằm giữa hai cạnh đó: Ví dụ góc A là góc xen giữa AB và AC.","Trường hợp c.g.c: nếu hai cạnh và…: Trường hợp c.g.c: nếu hai cạnh và góc xen giữa của tam giác này bằng hai cạnh và góc xen giữa của tam giác kia thì hai tam giác bằng nhau.","Trường hợp g.c.g: nếu một cạnh và…: Trường hợp g.c.g: nếu một cạnh và hai góc kề cạnh đó của tam giác này bằng một cạnh và hai góc kề cạnh đó của tam giác kia thì hai tam giác bằng nhau.","Lỗi thường gặp: Dùng góc không xen giữa hai cạnh đã cho để áp dụng c.g.c; dùng hai cạnh và một góc không xen giữa, đây không phải trường hợp bằng nhau."],"e":["Hay nhầm: 40° là góc B, không phải góc F.","Hay nhầm: 110° là 40° + 70°, không phải góc tương ứng với C.","Hay nhầm: 60° không liên quan đến dữ kiện đã cho."],"q":{"n":9,"lv":{"Biết":3,"Hiểu":4,"Vận dụng":2}}},{"t":"Bài 15. Các trường hợp bằng nhau của tam giác vuông","sum":["Ngoài ba trường hợp c.c.c, c.g.c, g.c.g, hai tam giác vuông còn bằng nhau trong các trường hợp riêng: hai cạnh góc vuông tương ứng bằng nhau; một cạnh góc vuông và góc nhọn kề cạnh đó bằng nhau;…","Khái niệm: Ngoài ba trường hợp c.c.c, c.g.c, g.c.g, hai tam giác vuông còn bằng nhau trong các trường hợp riêng: hai cạnh góc vuông tương ứng bằng nhau; một…","Ứng dụng: Giải thích hai cột cao bằng nhau có bóng bằng nhau; chứng minh hai thang tựa vào tường bằng nhau.","Lỗi thường gặp: Dùng hai góc nhọn bằng nhau để kết luận hai tam giác vuông bằng nhau."],"e":["Hay nhầm: 30° là góc E, không phải góc F.","Hay nhầm: 120° là 90° + 30°, không thể là góc nhọn của tam giác vuông.","Hay nhầm: 150° lớn hơn 90°, không thể là góc nhọn còn lại.","Hay nhầm: 90° là góc vuông, không phải góc nhọn.","Hay nhầm: 30° không thỏa mãn: hai góc nhọn bằng nhau và có tổng 90°, nên mỗi góc là 45°.","Hay nhầm: 60° cũng không thỏa mãn vì hai góc nhọn bằng nhau nên mỗi góc là 45°."],"q":{"n":10,"lv":{"Biết":3,"Hiểu":4,"Vận dụng":3}}},{"t":"Bài 16. Tam giác cân. Đường trung trực của đoạn thẳng","sum":["Tam giác cân có hai cạnh bằng nhau; hai cạnh này là cạnh bên, cạnh còn lại là cạnh đáy. Góc giữa hai cạnh bên là góc ở đỉnh; hai góc còn lại là góc ở đáy.","Khái niệm: Tam giác cân có hai cạnh bằng nhau; hai cạnh này là cạnh bên, cạnh còn lại là cạnh đáy.","Tam giác đều có ba cạnh bằng…: Tam giác đều có ba cạnh bằng nhau và ba góc bằng nhau, mỗi góc bằng 60°.","Đường trung trực của một đoạn thẳng…: Đường trung trực của một đoạn thẳng là đường thẳng vuông góc với đoạn thẳng đó tại trung điểm của nó.","Điểm nằm trên đường trung trực của…: Điểm nằm trên đường trung trực của một đoạn thẳng thì cách đều hai mút của đoạn thẳng.","Lỗi thường gặp: Quên rằng đường trung trực phải vừa vuông góc vừa đi qua trung điểm; nhầm tam giác cân với tam giác đều."],"e":["Hay nhầm: 45° là góc của tam giác vuông cân, không phải tam giác đều.","Hay nhầm: 90° là góc vuông; tam giác đều không có góc vuông.","Hay nhầm: 120° là góc tù; tam giác đều chỉ có ba góc nhọn bằng nhau.","Hay nhầm: 65° là góc ở đáy, không phải góc ở đỉnh A.","Hay nhầm: 130° là 180° − 50°, đây là tổng hai góc ở đáy, không phải góc A.","Hay nhầm: 25° là kết quả của phép chia sai, không đúng với công thức góc ở đỉnh."],"q":{"n":11,"lv":{"Biết":4,"Hiểu":4,"Vận dụng":3}}},{"t":"Ôn tập Chương IV (20 câu tự luận)"}]},{"t":"Chương V. Thu thập và biểu diễn dữ liệu","l":[{"t":"Bài 17. Thu thập và phân loại dữ liệu","sum":["Thu thập dữ liệu là lập kế hoạch và tiến hành khảo sát để có số liệu về đối tượng quan tâm, bằng phỏng vấn hoặc bảng hỏi.","Khái niệm: Thu thập dữ liệu là lập kế hoạch và tiến hành khảo sát để có số liệu về đối tượng quan tâm, bằng phỏng vấn hoặc bảng hỏi.","Tính đại diện: Dữ liệu thu được phải phản ánh đúng đối tượng khảo sát.","Dữ liệu là số (định lượng) như cân nặng, số giờ: Dữ liệu không là số (định tính) gồm loại không sắp thứ tự được (tên tỉnh) và loại sắp thứ tự được (mức đánh giá: Rất tốt, Tốt, Trung bình, Kém).","Lỗi thường gặp: Cho rằng dữ liệu được mã số (ví dụ số hiệu tuyến xe buýt) luôn là dữ liệu số; mã số chỉ là nhãn."],"q":{"n":9,"lv":{"Biết":3,"Hiểu":4,"Vận dụng":2}}},{"t":"Bài 18. Biểu đồ hình quạt tròn","sum":["Biểu đồ hình quạt tròn dùng để so sánh các phần trong toàn bộ dữ liệu. Hình tròn biểu diễn toàn bộ dữ liệu (100%), mỗi hình quạt biểu diễn tỉ lệ của một phần, tổng tỉ lệ các hình quạt bằng 100%.","Khái niệm: Biểu đồ hình quạt tròn dùng để so sánh các phần trong toàn bộ dữ liệu.","Từ tỉ lệ phần trăm có thể tính số lượng: Ví dụ 60% của 200 học sinh là 0,6 × 200 = 120 học sinh.","Lỗi thường gặp: Nhầm tỉ lệ phần trăm của một hình quạt với số đo góc của nó (hai đại lượng khác nhau nhưng cùng biểu diễn một phần); tổng các tỉ lệ không bằng 100%…"],"e":["Hay nhầm: 360° là tổng số đo góc ở tâm của hình tròn, không phải tổng tỉ lệ phần trăm.","Hay nhầm: 180° là nửa hình tròn, tương ứng với 50%, không phải tổng.","Hay nhầm: 50% là nửa dữ liệu, không phải tổng toàn bộ.","Hay nhầm: 15 là tỉ lệ phần trăm, chưa nhân với 200 để ra số học sinh.","Hay nhầm: 54 là số đo góc ở tâm, không phải số học sinh.","Hay nhầm: 108 là 2 · 54, không liên quan đến cách đổi góc sang tỉ lệ."],"q":{"n":11,"lv":{"Biết":4,"Hiểu":4,"Vận dụng":3}}},{"t":"Bài 19. Biểu đồ đoạn thẳng","sum":["Biểu đồ đoạn thẳng: trục ngang biểu diễn thời gian, trục đứng biểu diễn đại lượng đang quan tâm.","Biểu đồ đoạn thẳng: Trục ngang biểu diễn thời gian, trục đứng biểu diễn đại lượng đang quan tâm.","Biểu đồ đoạn thẳng cho thấy xu…: Biểu đồ đoạn thẳng cho thấy xu thế tăng, giảm hoặc ổn định của đại lượng theo thời gian.","Vẽ biểu đồ: Vẽ trục ngang và trục đứng, chọn đơn vị phù hợp với giá trị lớn nhất","Lưu ý về trục đứng: Độ dốc phụ thuộc vào thang đo trên trục đứng."],"e":["Hay nhầm: 18 là tổng mức giảm cả ba ngày, chưa chia cho 3.","Hay nhầm: 14 là 42 : 3, đây là phép tính sai, không phải mức giảm.","Hay nhầm: 3 là 18 : 6, không phải mức giảm mỗi ngày."],"q":{"n":11,"lv":{"Biết":3,"Hiểu":5,"Vận dụng":3}}},{"t":"Ôn tập Chương V (20 câu tự luận)"}]}]},{"t":"Toán 7, tập 2","c":[{"t":"Chương VI. Tỉ lệ thức và đại lượng tỉ lệ","l":[{"t":"Bài 20. Tỉ lệ thức","m":[{"t":"Tìm số hạng chưa biết của tỉ lệ thức","w":"Đề cho tỉ lệ thức a/b = c/d có một số hạng là x và yêu cầu tìm x.","s":["Viết tỉ lệ thức dưới dạng a/b = c/d (hoặc a : b = c : d).","Áp dụng tính chất của tỉ lệ thức: a·d = b·c.","Suy ra số hạng cần tìm bằng tích hai số nằm trên đường chéo đã biết chia cho số còn lại.","Thử lại bằng cách tính a·d và b·c."],"n":["Hai số ở cùng một đường chéo là hai số nhân với nhau (ngoại tỉ và trung tỉ).","Nếu x nằm trong biểu thức như x + 1, tìm cả biểu thức rồi mới tìm x.","Tỉ lệ thức a : b = c : d và a/b = c/d là một."]}],"sum":["Tỉ lệ thức là đẳng thức của hai tỉ số: a/b = c/d (với b, d khác 0).","Tỉ lệ thức là đẳng thức của hai tỉ số: A/b = c/d (với b, d khác 0).","Từ một tỉ lệ thức có thể…: Từ một tỉ lệ thức có thể suy ra các tỉ lệ thức khác bằng cách đổi chỗ các số hạng (tương tự với tích trong và tích ngoài)."],"d":["Tìm số hạng chưa biết của tỉ lệ thức"],"e":["Lưu ý: Hai số ở cùng một đường chéo là hai số nhân với nhau (ngoại tỉ và trung tỉ).","Lưu ý: Nếu x nằm trong biểu thức như x + 1, tìm cả biểu thức rồi mới tìm x.","Lưu ý: Tỉ lệ thức a : b = c : d và a/b = c/d là một."],"q":{"n":12,"lv":{"Biết":3,"Hiểu":5,"Vận dụng":4}}},{"t":"Bài 21. Tính chất của dãy tỉ số bằng nhau","m":[{"t":"Tìm các số khi biết tổng (hiệu) và tỉ số","w":"Đề cho hai (hoặc ba) số tỉ lệ với các số cho trước và biết tổng, hiệu hoặc chu vi.","s":["Viết dãy tỉ số bằng nhau: x/a = y/b (hoặc x : y : z = a : b : c).","Áp dụng tính chất: x/a = y/b = (x + y)/(a + b) = (x − y)/(a − b).","Tính giá trị chung k của dãy tỉ số, rồi x = k·a, y = k·b.","Kiểm tra lại tổng hoặc hiệu và trả lời."],"n":["Chỉ dùng (x − y)/(a − b) khi a khác b.","Bài hình học: dùng chu vi hoặc nửa chu vi để lập tổng.","Dãy ba tỉ số vẫn dùng tổng ba tử chia tổng ba mẫu."]}],"sum":["Từ dãy tỉ số bằng nhau a/b = c/d, ta có: a/b = c/d = (a + c)/(b + d) = (a − c)/(b − d) (với b + d và b − d khác 0).","Khái niệm: Từ dãy tỉ số bằng nhau a/b = c/d, ta có: a/b = c/d = (a + c)/(b + d) = (a − c)/(b − d) (với b + d và b − d khác 0).","Khi giải bài toán chia tỉ lệ…: Khi giải bài toán chia tỉ lệ, đặt tỉ số chung bằng k rồi tính từng đại lượng theo k."],"d":["Tìm các số khi biết tổng (hiệu) và tỉ số"],"e":["Lưu ý: Chỉ dùng (x − y)/(a − b) khi a khác b.","Lưu ý: Bài hình học: dùng chu vi hoặc nửa chu vi để lập tổng.","Lưu ý: Dãy ba tỉ số vẫn dùng tổng ba tử chia tổng ba mẫu."],"q":{"n":12,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":5}}},{"t":"Bài 22. Đại lượng tỉ lệ thuận","m":[{"t":"Bài toán về đại lượng tỉ lệ thuận","w":"Đề cho hai đại lượng cùng tăng hoặc cùng giảm theo tỉ lệ (quãng đường – thời gian, tiền – số lượng) hoặc chia một số theo tỉ lệ.","s":["Xác định hai đại lượng có tỉ lệ thuận không và viết y = k·x.","Tìm hệ số tỉ lệ k = y/x từ một cặp giá trị đã biết.","Tính đại lượng còn lại: y = k·x, hoặc dùng y₁/x₁ = y₂/x₂.","Bài chia theo tỉ lệ: dùng dãy tỉ số bằng nhau với tổng đã cho; kiểm tra rồi trả lời."],"n":["Tỉ lệ thuận: đại lượng này tăng bao nhiêu lần thì đại lượng kia tăng bấy nhiêu lần.","Hệ số k phải tính từ đúng cặp giá trị tương ứng.","Đơn giá, vận tốc cho trước chính là hệ số tỉ lệ."]}],"sum":["Hai đại lượng y và x tỉ lệ thuận với nhau nếu y = k · x với k là hằng số khác 0, gọi là hệ số tỉ lệ.","Khái niệm: Hai đại lượng y và x tỉ lệ thuận với nhau nếu y = k · x với k là hằng số khác 0, gọi là hệ số tỉ lệ.","Nếu y tỉ lệ thuận với x…: Nếu y tỉ lệ thuận với x thì tỉ số giữa hai giá trị bất kì của y bằng tỉ số giữa hai giá trị tương ứng của x: y1/y2 = x1/x2."],"d":["Bài toán về đại lượng tỉ lệ thuận"],"e":["Lưu ý: Tỉ lệ thuận: đại lượng này tăng bao nhiêu lần thì đại lượng kia tăng bấy nhiêu lần.","Lưu ý: Hệ số k phải tính từ đúng cặp giá trị tương ứng.","Lưu ý: Đơn giá, vận tốc cho trước chính là hệ số tỉ lệ."],"q":{"n":12,"lv":{"Biết":4,"Hiểu":4,"Vận dụng":4}}},{"t":"Bài 23. Đại lượng tỉ lệ nghịch","m":[{"t":"Bài toán về đại lượng tỉ lệ nghịch","w":"Đề cho hai đại lượng mà đại lượng này tăng thì đại lượng kia giảm theo tỉ lệ (số người – thời gian, vận tốc – thời gian).","s":["Xác định hai đại lượng tỉ lệ nghịch: x·y = a (a là hằng số).","Tìm hệ số tỉ lệ a = x₁·y₁ từ cặp giá trị đã biết.","Tính đại lượng cần tìm: y₂ = a / x₂ (hoặc x₁·y₁ = x₂·y₂).","Kiểm tra chiều biến đổi (x tăng thì y phải giảm) và trả lời."],"n":["Tỉ lệ nghịch: tích hai đại lượng không đổi, khác với tỉ lệ thuận (thương không đổi).","Công việc không đổi, năng suất mỗi người như nhau thì số người và thời gian tỉ lệ nghịch.","Quãng đường không đổi thì vận tốc và thời gian tỉ lệ nghịch."]}],"sum":["Hai đại lượng x và y tỉ lệ nghịch với nhau nếu x · y = a với a là hằng số khác 0.","Khái niệm: Hai đại lượng x và y tỉ lệ nghịch với nhau nếu x · y = a với a là hằng số khác 0.","Với đại lượng tỉ lệ nghịch: Nếu x tăng bao nhiêu lần thì y giảm bấy nhiêu lần."],"d":["Bài toán về đại lượng tỉ lệ nghịch"],"e":["Lưu ý: Tỉ lệ nghịch: tích hai đại lượng không đổi, khác với tỉ lệ thuận (thương không đổi).","Lưu ý: Công việc không đổi, năng suất mỗi người như nhau thì số người và thời gian tỉ lệ nghịch.","Lưu ý: Quãng đường không đổi thì vận tốc và thời gian tỉ lệ nghịch."],"q":{"n":12,"lv":{"Biết":4,"Hiểu":4,"Vận dụng":4}}},{"t":"Ôn tập Chương VI (20 câu tự luận)"}]},{"t":"Chương VII. Biểu thức đại số và đa thức một biến","l":[{"t":"Bài 24. Biểu thức đại số","sum":["Biểu thức đại số là biểu thức gồm các số, các chữ đại diện cho số, và các phép toán cộng, trừ, nhân, chia, lũy thừa.","Khái niệm: Biểu thức đại số là biểu thức gồm các số, các chữ đại diện cho số, và các phép toán cộng, trừ, nhân, chia, lũy thừa.","Giá trị của biểu thức đại số…: Giá trị của biểu thức đại số tại những giá trị cụ thể của chữ là kết quả nhận được khi thay các giá trị đó vào biểu thức rồi thực hiện phép tính."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 25. Đa thức một biến","m":[{"t":"Tính giá trị và tìm nghiệm của đa thức một biến","w":"Đề hỏi giá trị của đa thức tại một số, xem một số có phải nghiệm không, hoặc tìm nghiệm.","s":["Sắp xếp đa thức theo lũy thừa giảm dần và thu gọn.","Tính giá trị tại x = a: thay a vào mọi vị trí của biến (số âm đặt trong ngoặc) rồi tính.","a là nghiệm của P(x) khi P(a) = 0.","Tìm nghiệm: giải P(x) = 0 (đặt nhân tử chung hoặc phân tích thành tích) rồi liệt kê mọi nghiệm."],"n":["Nghiệm của đa thức là giá trị của biến làm đa thức bằng 0.","Một đa thức có thể có nhiều nghiệm hoặc không có nghiệm.","Tính lũy thừa trước khi nhân, cộng."]}],"sum":["Đa thức một biến là tổng của các đơn thức của cùng một biến x, có dạng a_n x^n + ... + a_1 x + a_0.","Khái niệm: Đa thức một biến là tổng của các đơn thức của cùng một biến x, có dạng a_n x^n + ... + a_1 x + a_0.","Bậc của đa thức một biến khác…: Bậc của đa thức một biến khác 0 là số mũ lớn nhất của biến có hệ số khác 0."],"d":["Tính giá trị và tìm nghiệm của đa thức một biến"],"e":["Lưu ý: Nghiệm của đa thức là giá trị của biến làm đa thức bằng 0.","Lưu ý: Một đa thức có thể có nhiều nghiệm hoặc không có nghiệm.","Lưu ý: Tính lũy thừa trước khi nhân, cộng."],"q":{"n":12,"lv":{"Biết":3,"Hiểu":5,"Vận dụng":4}}},{"t":"Bài 26. Phép cộng và phép trừ đa thức một biến","m":[{"t":"Cộng, trừ đa thức một biến","w":"Đề cho hai đa thức P(x), Q(x) và yêu cầu tính P(x) + Q(x), P(x) − Q(x), hoặc tính hệ số, giá trị.","s":["Sắp xếp mỗi đa thức theo lũy thừa giảm dần của biến.","Cộng: nhóm các hạng tử cùng bậc. Trừ: đổi dấu mọi hạng tử của đa thức trừ rồi cộng.","Thu gọn các hạng tử đồng dạng, viết kết quả theo lũy thừa giảm dần.","Nếu cần giá trị tại x = a thì thay vào đa thức đã thu gọn (hoặc thay riêng từng đa thức rồi cộng trừ)."],"n":["Khi trừ đa thức, phải đổi dấu tất cả hạng tử trong ngoặc phía sau dấu trừ.","Chỉ cộng trừ các hạng tử cùng bậc (đồng dạng).","Hạng tử thiếu bậc coi hệ số bằng 0."]}],"sum":["Để cộng (trừ) hai đa thức một biến, ta nhóm các hạng tử cùng bậc rồi cộng (trừ) các hệ số tương ứng.","Khái niệm: Để cộng (trừ) hai đa thức một biến, ta nhóm các hạng tử cùng bậc rồi cộng (trừ) các hệ số tương ứng.","Có thể tính giá trị của tổng…: Có thể tính giá trị của tổng (hiệu) bằng cách tính giá trị từng đa thức rồi cộng (trừ) các kết quả."],"d":["Cộng, trừ đa thức một biến"],"e":["Lưu ý: Khi trừ đa thức, phải đổi dấu tất cả hạng tử trong ngoặc phía sau dấu trừ.","Lưu ý: Chỉ cộng trừ các hạng tử cùng bậc (đồng dạng).","Lưu ý: Hạng tử thiếu bậc coi hệ số bằng 0."],"q":{"n":12,"lv":{"Biết":3,"Hiểu":5,"Vận dụng":4}}},{"t":"Bài 27. Phép nhân đa thức một biến","sum":["Để nhân hai đa thức một biến, ta nhân mỗi hạng tử của đa thức này với mỗi hạng tử của đa thức kia rồi thu gọn các hạng tử cùng bậc.","Khái niệm: Để nhân hai đa thức một biến, ta nhân mỗi hạng tử của đa thức này với mỗi hạng tử của đa thức kia rồi thu gọn các hạng tử cùng bậc.","Bậc của tích hai đa thức bằng…: Bậc của tích hai đa thức bằng tổng bậc của hai đa thức đó (khi các đa thức khác 0)."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 28. Phép chia đa thức một biến","sum":["Chia đơn thức cho đơn thức: với b ≠ 0 và m ≥ n, ta có axᵐ : bxⁿ = (a : b)xᵐ⁻ⁿ.","Chia đơn thức cho đơn thức: Với b ≠ 0 và m ≥ n, ta có axᵐ : bxⁿ = (a : b)xᵐ⁻ⁿ.","Chia đa thức cho đơn thức: Chia từng hạng tử của đa thức cho đơn thức rồi cộng các kết quả.","Chia đa thức A cho đa thức B (B ≠ 0): Đặt tính chia tương tự chia số tự nhiên, được thương Q và dư R sao cho A = B · Q + R, trong đó R = 0 hoặc bậc của R nhỏ hơn bậc của B."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}},{"t":"Ôn tập Chương VII (20 câu tự luận)"}]},{"t":"Chương VIII. Làm quen với biến cố và xác suất của biến cố","l":[{"t":"Bài 29. Làm quen với biến cố","sum":["Biến cố là một sự việc, hiện tượng có thể xảy ra hoặc không xảy ra.","Khái niệm: Biến cố là một sự việc, hiện tượng có thể xảy ra hoặc không xảy ra.","Biến cố chắc chắn là biến cố biết trước được luôn xảy ra: Biến cố không thể là biến cố biết trước được không bao giờ xảy ra."],"e":["Hay nhầm: Biến cố không thể là biến cố không bao giờ xảy ra; ở đây nó luôn xảy ra.","Hay nhầm: Ta biết trước biến cố này luôn xảy ra nên không phải biến cố ngẫu nhiên.","Hay nhầm: Biến cố chắc chắn phải luôn xảy ra; ở đây nó không bao giờ xảy ra.","Hay nhầm: Ta biết trước biến cố này không xảy ra nên không phải biến cố ngẫu nhiên.","Hay nhầm: Biến cố không xảy ra khi gieo được mặt 2, 4 hoặc 6, nên không luôn xảy ra.","Hay nhầm: Biến cố xảy ra khi gieo được mặt 1, 3 hoặc 5, nên không phải không bao giờ xảy ra."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 30. Làm quen với xác suất của biến cố","m":[{"t":"Tính xác suất của biến cố","w":"Đề cho một phép thử (gieo xúc xắc, rút thẻ, lấy bóng) và hỏi xác suất của một biến cố.","s":["Liệt kê (hoặc đếm) tất cả kết quả có thể của phép thử; các kết quả này đồng khả năng.","Đếm số kết quả thuận lợi cho biến cố cần tính.","Xác suất = số kết quả thuận lợi / tổng số kết quả có thể.","Rút gọn phân số; xác suất luôn nằm giữa 0 và 1."],"n":["Chỉ dùng công thức khi các kết quả đồng khả năng.","Biến cố chắc chắn có xác suất 1, biến cố không thể có xác suất 0.","Đếm đủ kết quả thuận lợi, đừng bỏ sót hoặc đếm hai lần."]}],"sum":["Xác suất của một biến cố là một số đo khả năng xảy ra của biến cố đó. Xác suất nhận giá trị từ 0 đến 1.","Khái niệm: Xác suất của một biến cố là một số đo khả năng xảy ra của biến cố đó.","Nếu có k biến cố đồng khả…: Nếu có k biến cố đồng khả năng và luôn xảy ra một và chỉ một biến cố trong k biến cố đó thì xác suất của mỗi biến cố đều bằng 1/k.","Ví dụ: Gieo một con xúc xắc cân đối, sáu biến cố \"xuất hiện mặt 1 chấm\", \"xuất hiện mặt 2 chấm\", …, \"xuất hiện mặt 6 chấm\" đồng khả năng và luôn xảy ra…"],"d":["Tính xác suất của biến cố"],"e":["Hay nhầm: 3/2 > 1 nên không thể là xác suất.","Hay nhầm: −1/4 < 0 nên không thể là xác suất.","Hay nhầm: 5/4 > 1 nên không thể là xác suất.","Lưu ý: Chỉ dùng công thức khi các kết quả đồng khả năng.","Lưu ý: Biến cố chắc chắn có xác suất 1, biến cố không thể có xác suất 0.","Lưu ý: Đếm đủ kết quả thuận lợi, đừng bỏ sót hoặc đếm hai lần."],"q":{"n":12,"lv":{"Biết":3,"Hiểu":5,"Vận dụng":4}}},{"t":"Ôn tập Chương VIII (20 câu tự luận)"}]},{"t":"Chương IX. Quan hệ giữa các yếu tố trong một tam giác","l":[{"t":"Bài 31. Quan hệ giữa góc và cạnh đối diện trong một tam giác","sum":["Trong một tam giác, góc đối diện với cạnh lớn hơn là góc lớn hơn. Ngược lại, cạnh đối diện với góc lớn hơn là cạnh lớn hơn.","Khái niệm: Trong một tam giác, góc đối diện với cạnh lớn hơn là góc lớn hơn.","Hai cạnh bằng nhau thì hai góc…: Hai cạnh bằng nhau thì hai góc đối diện bằng nhau (tam giác cân) và ngược lại.","Trong tam giác vuông, góc vuông là…: Trong tam giác vuông, góc vuông là góc lớn nhất nên cạnh huyền (đối diện góc vuông) là cạnh lớn nhất."],"e":["Hay nhầm: Góc B đối diện cạnh CA = 6 cm, không phải cạnh lớn nhất.","Hay nhầm: Góc C đối diện cạnh AB = 5 cm, là cạnh nhỏ nhất, nên góc C là góc nhỏ nhất.","Hay nhầm: CA đối diện góc B = 60°, không phải góc lớn nhất.","Hay nhầm: AB đối diện góc C = 40°, là góc nhỏ nhất, nên AB là cạnh nhỏ nhất.","Hay nhầm: AB đối diện góc C, là góc nhọn nên nhỏ hơn góc A.","Hay nhầm: AC đối diện góc B, là góc nhọn nên nhỏ hơn góc A."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 32. Quan hệ giữa đường vuông góc và đường xiên","sum":["Cho điểm A không nằm trên đường thẳng d. Kẻ AH vuông góc với d (H thuộc d): đoạn AH gọi là đường vuông góc kẻ từ A đến d, H là chân đường vuông góc.","Cho điểm A không nằm trên đường thẳng d: Kẻ AH vuông góc với d (H thuộc d): đoạn AH gọi là đường vuông góc kẻ từ A đến d, H là chân đường vuông góc.","Định lí: Trong các đường xiên và đường vuông góc kẻ từ một điểm nằm ngoài một đường thẳng đến đường thẳng đó, đường vuông góc là đường ngắn nhất.","Giải thích: Tam giác AHB vuông tại H nên góc AHB = 90° là góc lớn nhất; cạnh đối diện AB vì thế lớn hơn AH."],"e":["Hay nhầm: AB là đường xiên nên AB > AH.","Hay nhầm: AC là đường xiên nên AC > AH.","Hay nhầm: AB = 5 cm = AH thì B trùng H, khi đó AB không còn là đường xiên.","Hay nhầm: 4 cm < 5 cm, đường xiên không thể ngắn hơn đường vuông góc.","Hay nhầm: 3 cm < 5 cm, đường xiên không thể ngắn hơn đường vuông góc.","Hay nhầm: Đường vuông góc AB không thể dài hơn đường xiên BC."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 33. Quan hệ giữa ba cạnh của một tam giác","m":[{"t":"Tìm độ dài cạnh thứ ba của tam giác","w":"Đề cho độ dài hai cạnh và hỏi cạnh thứ ba (có thể nguyên, lớn nhất, nhỏ nhất, tam giác cân).","s":["Viết bất đẳng thức tam giác: hiệu hai cạnh < cạnh thứ ba < tổng hai cạnh.","Tính khoảng giá trị của cạnh thứ ba từ hai cạnh đã cho.","Chọn giá trị thỏa điều kiện thêm của đề (số nguyên, tam giác cân, lớn nhất, nhỏ nhất).","Kiểm tra lại bằng bất đẳng thức tam giác cho cả ba cạnh."],"n":["Cạnh thứ ba phải lớn hơn hiệu và nhỏ hơn tổng hai cạnh, không được bằng.","Tam giác cân có hai cạnh bằng nhau: thử từng trường hợp rồi loại trường hợp vi phạm bất đẳng thức.","Ba độ dài tạo thành tam giác khi tổng hai cạnh nhỏ bất kì lớn hơn cạnh lớn nhất."]}],"sum":["Trong một tam giác, tổng độ dài hai cạnh bất kì luôn lớn hơn độ dài cạnh còn lại (bất đẳng thức tam giác).","Khái niệm: Trong một tam giác, tổng độ dài hai cạnh bất kì luôn lớn hơn độ dài cạnh còn lại (bất đẳng thức tam giác).","Để kiểm tra ba độ dài có…: Để kiểm tra ba độ dài có phải ba cạnh của một tam giác không, chỉ cần kiểm tra độ dài lớn nhất có nhỏ hơn tổng hai độ dài còn lại không."],"d":["Tìm độ dài cạnh thứ ba của tam giác"],"e":["Hay nhầm: 1 + 2 = 3, không lớn hơn 3.","Hay nhầm: 7 < 5 + 6 = 11 nên đây là ba cạnh của một tam giác.","Hay nhầm: 5 < 3 + 3 = 6 nên đây là ba cạnh của một tam giác.","Hay nhầm: 9 < 4 + 6 = 10 nên đây là ba cạnh của một tam giác.","Hay nhầm: 2 + 3 = 5 < 6 nên không tạo thành tam giác.","Hay nhầm: 1 + 2 = 3 không lớn hơn 3 nên không tạo thành tam giác."],"q":{"n":12,"lv":{"Biết":2,"Vận dụng":4,"Hiểu":6}}},{"t":"Bài 34. Sự đồng quy của ba đường trung tuyến, ba đường phân giác trong một tam giác","sum":["Ba đường trung tuyến của tam giác đồng quy tại một điểm gọi là trọng tâm G. Trọng tâm cách mỗi đỉnh một khoảng bằng 2/3 đường trung tuyến đi qua đỉnh đó.","Khái niệm: Ba đường trung tuyến của tam giác đồng quy tại một điểm gọi là trọng tâm G.","Ba đường phân giác của tam giác…: Ba đường phân giác của tam giác đồng quy tại một điểm cách đều ba cạnh của tam giác."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 35. Sự đồng quy của ba đường trung trực, ba đường cao trong một tam giác","sum":["Ba đường trung trực của một tam giác cùng đi qua một điểm. Điểm này cách đều ba đỉnh của tam giác.","Ba đường trung trực của một tam giác cùng đi qua một điểm: Điểm này cách đều ba đỉnh của tam giác.","Đường cao của tam giác là đoạn…: Đường cao của tam giác là đoạn vuông góc kẻ từ một đỉnh đến đường thẳng chứa cạnh đối diện.","Với tam giác vuông tại A, hai…: Với tam giác vuông tại A, hai đường cao kẻ từ B và từ C chính là BA và CA, nên trực tâm trùng với đỉnh góc vuông A."],"e":["Hay nhầm: Trọng tâm là giao điểm của ba đường trung tuyến.","Hay nhầm: Giao điểm ba đường phân giác cách đều ba cạnh, không phải giao điểm ba đường cao.","Hay nhầm: Điểm cách đều ba cạnh là giao điểm ba đường phân giác.","Hay nhầm: Tính chất chia trung tuyến theo tỉ số 2 : 1 là của trọng tâm.","Hay nhầm: Đường cao kẻ từ C là CA; đường thẳng này không đi qua B.","Hay nhầm: Đường cao kẻ từ B là BA; đường thẳng này không đi qua C."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}},{"t":"Ôn tập Chương IX (20 câu tự luận)"}]},{"t":"Chương X. Một số hình khối trong thực tiễn","l":[{"t":"Bài 36. Hình hộp chữ nhật và hình lập phương","sum":["Hình hộp chữ nhật có 6 mặt là hình chữ nhật, 12 cạnh và 8 đỉnh. Hình lập phương có 6 mặt là hình vuông bằng nhau.","Khái niệm: Hình hộp chữ nhật có 6 mặt là hình chữ nhật, 12 cạnh và 8 đỉnh.","Diện tích toàn phần bằng diện tích…: Diện tích toàn phần bằng diện tích xung quanh cộng diện tích hai đáy."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 37. Hình lăng trụ đứng tam giác và hình lăng trụ đứng tứ giác","sum":["Hình lăng trụ đứng có hai đáy là hai đa giác bằng nhau và song song; các mặt bên là hình chữ nhật và vuông góc với hai đáy.","Khái niệm: Hình lăng trụ đứng có hai đáy là hai đa giác bằng nhau và song song; các mặt bên là hình chữ nhật và vuông góc với hai đáy."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}},{"t":"Ôn tập Chương X (20 câu tự luận)"}]}]},{"t":"Hướng dẫn giải bài ôn tập","c":[{"t":"Chương I","l":[{"t":"Hướng dẫn giải · Ôn tập Chương I"}]},{"t":"Chương II","l":[{"t":"Hướng dẫn giải · Ôn tập Chương II"}]},{"t":"Chương III","l":[{"t":"Hướng dẫn giải · Ôn tập Chương III"}]},{"t":"Chương IV","l":[{"t":"Hướng dẫn giải · Ôn tập Chương IV"}]},{"t":"Chương V","l":[{"t":"Hướng dẫn giải · Ôn tập Chương V"}]},{"t":"Chương VI","l":[{"t":"Hướng dẫn giải · Ôn tập Chương VI"}]},{"t":"Chương VII","l":[{"t":"Hướng dẫn giải · Ôn tập Chương VII"}]},{"t":"Chương VIII","l":[{"t":"Hướng dẫn giải · Ôn tập Chương VIII"}]},{"t":"Chương IX","l":[{"t":"Hướng dẫn giải · Ôn tập Chương IX"}]},{"t":"Chương X","l":[{"t":"Hướng dẫn giải · Ôn tập Chương X"}]}]},{"t":"Bài tập nâng cao","c":[{"t":"Chương I. Số hữu tỉ","l":[{"t":"Bài tập nâng cao · Chương I. Số hữu tỉ (10 câu)","q":{"n":10,"lv":{"Nâng cao":10}}}]},{"t":"Chương II. Số thực","l":[{"t":"Bài tập nâng cao · Chương II. Số thực (9 câu)","e":["Hay nhầm: Mẫu 12 = 2²·3 có ước nguyên tố 3.","Hay nhầm: Mẫu 15 = 3·5 có ước nguyên tố 3.","Hay nhầm: Mẫu 18 = 2·3² có ước nguyên tố 3."],"q":{"n":9,"lv":{"Nâng cao":9}}}]},{"t":"Chương III. Góc và đường thẳng song song","l":[{"t":"Bài tập nâng cao · Chương III. Góc và đường thẳng song song (9 câu)","e":["Hay nhầm: Nhiều ví dụ đúng không chứng minh được mệnh đề tổng quát.","Hay nhầm: Hình vẽ không thay thế được lập luận."],"q":{"n":9,"lv":{"Nâng cao":9}}}]},{"t":"Chương IV. Tam giác bằng nhau","l":[{"t":"Bài tập nâng cao · Chương IV. Tam giác bằng nhau (12 câu)","e":["Hay nhầm: Khi đó chưa đủ kết luận (không phải trường hợp c.g.c).","Hay nhầm: Hai góc nhọn bằng nhau chưa đủ vì chưa có cạnh nào bằng nhau.","Hay nhầm: Đó là điều kiện đồng dạng ở lớp 8."],"q":{"n":12,"lv":{"Nâng cao":12}}}]},{"t":"Chương V. Thu thập và biểu diễn dữ liệu","l":[{"t":"Bài tập nâng cao · Chương V. Thu thập và biểu diễn dữ liệu (5 câu)","q":{"n":5,"lv":{"Nâng cao":5}}}]},{"t":"Chương VI. Tỉ lệ thức và đại lượng tỉ lệ","l":[{"t":"Bài tập nâng cao · Chương VI. Tỉ lệ thức và đại lượng tỉ lệ (12 câu)","q":{"n":12,"lv":{"Nâng cao":12}}}]},{"t":"Chương VII. Biểu thức đại số và đa thức một biến","l":[{"t":"Bài tập nâng cao · Chương VII. Biểu thức đại số và đa thức một biến (11 câu)","q":{"n":11,"lv":{"Nâng cao":11}}}]},{"t":"Chương VIII. Làm quen với biến cố và xác suất của biến cố","l":[{"t":"Bài tập nâng cao · Chương VIII. Làm quen với biến cố và xác suất của biến cố (5 câu)","e":["Hay nhầm: Không có mặt nào có số chấm lớn hơn 6.","Hay nhầm: Biến cố ngẫu nhiên là biến cố có thể xảy ra hoặc không.","Hay nhầm: Biến cố này không bao giờ xảy ra."],"q":{"n":5,"lv":{"Nâng cao":5}}}]},{"t":"Chương IX. Quan hệ giữa các yếu tố trong một tam giác","l":[{"t":"Bài tập nâng cao · Chương IX. Quan hệ giữa các yếu tố trong một tam giác (10 câu)","e":["Hay nhầm: Cạnh đối diện góc lớn nhất (BC đối diện Â) phải dài nhất.","Hay nhầm: AB đối diện Ĉ = 60° nên dài hơn AC (đối diện B̂ = 50°).","Hay nhầm: BC đối diện góc lớn nhất nên phải dài nhất.","Hay nhầm: d là đường thẳng, không có trung điểm.","Hay nhầm: Đường xiên luôn dài hơn đường vuông góc.","Hay nhầm: Chỉ có một đoạn vuông góc."],"q":{"n":10,"lv":{"Nâng cao":10}}}]},{"t":"Chương X. Một số hình khối trong thực tiễn","l":[{"t":"Bài tập nâng cao · Chương X. Một số hình khối trong thực tiễn (4 câu)","q":{"n":4,"lv":{"Nâng cao":4}}}]}]}]},{"id":"ly","name":"Vật lí","b":[{"t":"Vật lí 7","c":[{"t":"Mở đầu","l":[{"t":"Bài 1. Phương pháp và kĩ năng học tập môn Khoa học tự nhiên","req":["Trình bày được phương pháp tìm hiểu tự nhiên.","Thực hiện được các kĩ năng tiến trình: quan sát, phân loại, liên kết, đo, dự báo.","Sử dụng được một số dụng cụ đo trong môn Khoa học tự nhiên 7."],"sum":["Phương pháp tìm hiểu tự nhiên là cách tìm hiểu sự vật, hiện tượng trong tự nhiên bằng các dẫn chứng khoa học.","Khái niệm: Phương pháp tìm hiểu tự nhiên là cách tìm hiểu sự vật, hiện tượng trong tự nhiên bằng các dẫn chứng khoa học.","Nếu kết quả thí nghiệm không phù…: Nếu kết quả thí nghiệm không phù hợp với dự đoán, cần quay lại bước đưa ra dự đoán.","Kĩ năng quan sát là dùng một…: Kĩ năng quan sát là dùng một hoặc nhiều giác quan để thu thập thông tin về đặc điểm, kích thước, hình dạng của sự vật.","Kĩ năng phân loại là nhóm các…: Kĩ năng phân loại là nhóm các đối tượng, khái niệm hoặc sự kiện thành các danh mục, theo đặc điểm được chọn.","Kĩ năng liên kết là dùng số…: Kĩ năng liên kết là dùng số liệu quan sát, kết quả phân tích để xác định mối quan hệ giữa các sự vật và hiện tượng."],"e":["Hay nhầm: Lập kế hoạch là bước 3, chỉ làm sau khi đã có dự đoán.","Hay nhầm: Viết báo cáo là bước 5, làm sau khi đã thực hiện xong kế hoạch.","Hay nhầm: Đưa ra dự đoán là bước 2, làm sau khi đã đề xuất vấn đề.","Hay nhầm: Dự báo là đề xuất điều sẽ xảy ra dựa trên quan sát và suy luận, không phải thu thập thông tin trực tiếp.","Hay nhầm: Liên kết là xác định mối quan hệ giữa các số liệu đã có.","Hay nhầm: Phân loại là nhóm các đối tượng theo đặc điểm được chọn."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương III. Tốc độ","l":[{"t":"Bài 8. Tốc độ chuyển động","req":["Nêu được ý nghĩa vật lí của tốc độ.","Tính được tốc độ theo quãng đường đi được và thời gian đi quãng đường đó.","Đổi được đơn vị tốc độ giữa m/s và km/h."],"m":[{"t":"Bài toán tốc độ, quãng đường, thời gian","w":"Đề cho hai trong ba đại lượng v, s, t và hỏi đại lượng còn lại; hoặc đổi đơn vị tốc độ; hoặc tốc độ trung bình.","s":["Liệt kê dữ kiện và đại lượng cần tìm, đổi về đơn vị thống nhất (km, h hoặc m, s).","Chọn công thức: v = s/t; s = v·t; t = s/v.","Tốc độ trung bình = tổng quãng đường : tổng thời gian.","Thay số, tính, ghi đơn vị; đổi km/h ↔ m/s bằng 1 m/s = 3,6 km/h."],"n":["Tốc độ trung bình không phải trung bình cộng của các tốc độ.","Đổi phút ra giờ: 30 phút = 0,5 h.","Từ m/s sang km/h nhân 3,6; từ km/h sang m/s chia 3,6."]}],"sum":["Tốc độ là đại lượng cho biết chuyển động nhanh hay chậm. Để so sánh, ta xét quãng đường vật đi được trong cùng một đơn vị thời gian.","Tốc độ là đại lượng cho biết chuyển động nhanh hay chậm: Để so sánh, ta xét quãng đường vật đi được trong cùng một đơn vị thời gian.","Trong đó v là tốc độ, s…: Trong đó v là tốc độ, s là quãng đường đi được, t là thời gian đi hết quãng đường đó.","Các đơn vị tốc độ thường dùng…: Các đơn vị tốc độ thường dùng là mét trên giây (m/s) và kilômét trên giờ (km/h).","Trong thực tế, tốc độ của một vật thường thay đổi: Khi đó v = s / t là tốc độ trung bình trên quãng đường s."],"d":["Bài toán tốc độ, quãng đường, thời gian"],"e":["Hay nhầm: Nhân s với t cho ra một đại lượng khác, không phải tốc độ. Tốc độ là thương của s chia cho t.","Hay nhầm: Đảo ngược s và t cho ra nghịch đảo của tốc độ. Tốc độ là s chia cho t.","Hay nhầm: Cộng s và t không có ý nghĩa vật lí về tốc độ. Tốc độ là s chia cho t.","Hay nhầm: 1 m/s lớn hơn 1 km/h. Một mét trên giây tương đương 3,6 km trên giờ.","Hay nhầm: Phép đổi đã bị đảo chiều. Đúng là nhân với 3,6, không chia.","Hay nhầm: Phép đổi bị nhân nhầm với 10. Đúng là 1 m/s = 3,6 km/h."],"q":{"n":12,"lv":{"Biết":4,"Hiểu":4,"Vận dụng":4}}},{"t":"Bài 9. Đo tốc độ","req":["Mô tả được sơ lược cách đo tốc độ bằng đồng hồ bấm giây và cổng quang điện trong dụng cụ thực hành ở nhà trường.","Mô tả được thiết bị \"bắn tốc độ\" trong kiểm tra tốc độ các phương tiện giao thông."],"sum":["Để đo tốc độ chuyển động cần đo độ dài quãng đường s và thời gian t. Dụng cụ đo tốc độ của các phương tiện giao thông như ô tô, xe máy được gọi là tốc kế.","Khái niệm: Để đo tốc độ chuyển động cần đo độ dài quãng đường s và thời gian t.","Đo tốc độ bằng đồng hồ bấm giây: Đánh dấu vạch xuất phát và vạch đích, đo quãng đường s, bấm giây đo thời gian t từ lúc vật bắt đầu chuyển động đến khi tới vạch đích.","Đo tốc độ bằng đồng hồ đo thời gian hiện số và cổng quang điện: Cách làm tương tự, nhưng thời gian được đo tự động khi vật đi qua cổng quang điện thứ nhất và thứ hai.","Thiết bị bắn tốc độ đơn giản…: Thiết bị bắn tốc độ đơn giản dùng một camera ghi lại thời điểm ô tô đi qua hai vạch mốc cách nhau vài mét."],"e":["Hay nhầm: Nhiệt kế dùng để đo nhiệt độ.","Hay nhầm: Áp kế dùng để đo áp suất.","Hay nhầm: Cách này ít dùng hơn trong phòng thực hành.","Hay nhầm: Không có dụng cụ nào đo đồng thời s và t như vậy trong bài này.","Hay nhầm: Tốc độ cần cả quãng đường lẫn thời gian nên không thể bỏ qua s.","Hay nhầm: Chỉ đo 1 lần thì kết quả dễ sai số."],"q":{"n":8,"lv":{"Biết":5,"Hiểu":2,"Vận dụng":1}}},{"t":"Bài 10. Đồ thị quãng đường – thời gian","req":["Vẽ được đồ thị quãng đường – thời gian cho chuyển động thẳng.","Từ đồ thị quãng đường – thời gian cho trước, tìm được quãng đường vật đi (hoặc tốc độ hay thời gian chuyển động của vật)."],"m":[{"t":"Đọc đồ thị quãng đường – thời gian","w":"Đề cho đồ thị s–t và yêu cầu tính tốc độ, so sánh chuyển động, xác định thời điểm gặp nhau.","s":["Đọc trục: trục ngang là thời gian t, trục dọc là quãng đường s; chú ý đơn vị và tỉ lệ chia.","Chọn hai điểm rõ ràng trên đồ thị, đọc (t₁, s₁) và (t₂, s₂).","Tốc độ v = (s₂ − s₁)/(t₂ − t₁).","Đường dốc hơn thì tốc độ lớn hơn; đoạn nằm ngang là vật đứng yên."],"n":["Đoạn đồ thị nằm ngang ứng với vật đứng yên (s không đổi).","Hai đồ thị cắt nhau tại thời điểm hai vật gặp nhau.","Đọc đúng giá trị mỗi ô lưới trước khi tính."]}],"sum":["Để vẽ đồ thị quãng đường – thời gian, trước hết lập bảng ghi quãng đường đi được theo thời gian.","Khái niệm: Để vẽ đồ thị quãng đường – thời gian, trước hết lập bảng ghi quãng đường đi được theo thời gian.","Trên hai trục vuông góc Os (trục…: Trên hai trục vuông góc Os (trục tung, biểu diễn quãng đường) và Ot (trục hoành, biểu diễn thời gian), xác định các điểm (thời gian, quãng đường)…","Đồ thị của chuyển động có tốc…: Đồ thị của chuyển động có tốc độ không đổi là một đường thẳng nghiêng.","Khi đồ thị là đường thẳng song…: Khi đồ thị là đường thẳng song song với trục thời gian, quãng đường không thay đổi nghĩa là vật đứng yên."],"d":["Đọc đồ thị quãng đường – thời gian"],"e":["Hay nhầm: Đường tròn không biểu diễn chuyển động có tốc độ không đổi.","Hay nhầm: Parabol không phải dạng đồ thị của chuyển động thẳng đều.","Hay nhầm: Đường trùng trục hoành nghĩa là quãng đường bằng 0 mãi, không phải chuyển động.","Hay nhầm: Thời gian được biểu diễn trên trục nằm ngang Ot.","Hay nhầm: Khối lượng không có trên đồ thị này.","Hay nhầm: Nhiệt độ không có trên đồ thị này."],"q":{"n":12,"lv":{"Biết":4,"Hiểu":4,"Vận dụng":4}}},{"t":"Bài 11. Thảo luận về ảnh hưởng của tốc độ trong an toàn giao thông","req":["Dựa vào tranh ảnh (hoặc học liệu điện tử) thảo luận để nêu được ảnh hưởng của tốc độ trong an toàn giao thông."],"sum":["Tốc độ tối đa cho phép của xe cơ giới được quy định khác nhau theo loại xe và loại đường. Ví dụ: trên đường bộ không có giải phân cách cứng ngoài khu vực đông dân cư, xe con và xe tải nhẹ có tốc độ…","Khái niệm: Tốc độ tối đa cho phép của xe cơ giới được quy định khác nhau theo loại xe và loại đường.","Trên đường cao tốc, tốc độ tối…: Trên đường cao tốc, tốc độ tối đa là 120 km/h khi trời không mưa và 100 km/h khi có mưa.","Khoảng cách an toàn tối thiểu giữa…: Khoảng cách an toàn tối thiểu giữa hai xe tăng khi tốc độ tăng.","Vi phạm tốc độ làm người điều…: Vi phạm tốc độ làm người điều khiển không đủ thời gian phanh và tránh va chạm, dễ gây tai nạn giao thông, ảnh hưởng đến sức khoẻ và tính mạng của…"],"e":["Hay nhầm: 70 km/h là tốc độ tối đa của xe trên 3,5 tấn (trừ ô tô buýt).","Hay nhầm: 60 km/h là tốc độ tối đa của ô tô buýt.","Hay nhầm: 50 km/h là mức ghi trong bảng cho nhóm xe khác, không phải xe con.","Hay nhầm: 120 km/h là tốc độ tối đa khi trời không mưa.","Hay nhầm: 80 km/h không phải giới hạn trên đường cao tốc.","Hay nhầm: 60 km/h không phải giới hạn trên đường cao tốc."],"q":{"n":8,"lv":{"Biết":4,"Hiểu":2,"Vận dụng":2}}}]},{"t":"Chương IV. Âm thanh","l":[{"t":"Bài 12. Sóng âm","req":["Thực hiện thí nghiệm tạo sóng âm (như gảy đàn, gõ vào thanh kim loại,...) để chứng tỏ được sóng âm có thể truyền được trong chất rắn, lỏng, khí.","Giải thích được sự truyền sóng âm trong không khí."],"sum":["Chuyển động qua lại quanh một vị trí cân bằng gọi là dao động. Ví dụ: thanh thép đàn hồi khi kéo xuống rồi thả ra dao động quanh vị trí cân bằng.","Khái niệm: Chuyển động qua lại quanh một vị trí cân bằng gọi là dao động.","Sóng là sự lan truyền dao động trong môi trường: Ví dụ: dao động của thanh thép làm mặt nước dao động, tạo thành sóng nước hình tròn.","Nguồn âm là vật phát ra âm và luôn dao động: Ví dụ: mặt trống, dây đàn, cây sáo, âm thoa.","Sóng âm là sự lan truyền dao…: Sóng âm là sự lan truyền dao động của nguồn âm trong môi trường.","Ví dụ: Khi áp tai xuống đất có thể nghe được tiếng vó ngựa từ xa, vì âm truyền trong chất rắn tốt hơn trong không khí."],"e":["Hay nhầm: Sóng là sự lan truyền dao động trong môi trường, không phải chính chuyển động qua lại.","Hay nhầm: Âm thanh là kết quả khi sóng âm truyền đến tai.","Hay nhầm: Vận tốc là đại lượng cho biết nhanh chậm của chuyển động.","Hay nhầm: Nước không lan truyền như vậy khi có sóng âm.","Hay nhầm: Ánh sáng không phải sóng âm.","Hay nhầm: Dòng điện không phải sóng âm."],"q":{"n":8,"lv":{"Biết":4,"Hiểu":2,"Vận dụng":2}}},{"t":"Bài 13. Độ to và độ cao của âm","req":["Từ hình ảnh hoặc đồ thị xác định được biên độ và tần số sóng âm.","Nêu được đơn vị của tần số là héc (kí hiệu là Hz).","Nêu được sự liên quan của độ to của âm với biên độ âm."],"sum":["Biên độ dao động là khoảng cách từ vị trí cân bằng đến vị trí xa nhất của dao động. Biên độ của sóng âm có liên quan đến độ to của âm: biên độ lớn thì âm to, biên độ nhỏ thì âm nhỏ.","Khái niệm: Biên độ dao động là khoảng cách từ vị trí cân bằng đến vị trí xa nhất của dao động.","Tần số là số dao động vật thực hiện được trong 1 giây: Đơn vị của tần số là héc, kí hiệu Hz.","Tai người nghe được âm có tần…: Tai người nghe được âm có tần số từ 20 Hz đến 20 000 Hz.","Tần số của sóng âm càng lớn…: Tần số của sóng âm càng lớn thì âm nghe càng cao (bổng); tần số càng nhỏ thì âm càng thấp (trầm)."],"e":["Hay nhầm: m/s là đơn vị của tốc độ.","Hay nhầm: dB là đơn vị đo độ to của âm.","Hay nhầm: Quãng đường không phải tần số.","Hay nhầm: Khoảng cách đó là biên độ dao động.","Hay nhầm: Độ to của âm liên quan đến biên độ, không phải tần số.","Hay nhầm: Khoảng này quá hẹp, không phải dải nghe được của tai người."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 14. Phản xạ âm, chống ô nhiễm tiếng ồn","req":["Lấy được ví dụ về vật phản xạ âm tốt, vật phản xạ âm kém.","Giải thích được một số hiện tượng đơn giản thường gặp trong thực tế về sóng âm; đề xuất được phương án đơn giản để hạn chế tiếng ồn ảnh hưởng đến sức khoẻ."],"sum":["Âm được dội lại khi gặp một mặt chắn gọi là âm phản xạ. Hiện tượng này gọi là phản xạ âm.","Âm được dội lại khi gặp một mặt chắn gọi là âm phản xạ: Hiện tượng này gọi là phản xạ âm.","Khi âm phản xạ đến tai chậm…: Khi âm phản xạ đến tai chậm hơn âm truyền trực tiếp một khoảng thời gian lớn hơn 1/15 giây thì âm phản xạ được gọi là tiếng vang.","Vật liệu cứng, có bề mặt nhẵn thì phản xạ âm tốt: Vật liệu mềm, xốp hoặc có bề mặt sần sùi thì phản xạ âm kém.","Các biện pháp làm giảm tiếng ồn ảnh hưởng đến sức khoẻ: Hạn chế nguồn gây ra tiếng ồn; phân tán tiếng ồn trên đường truyền; ngăn cản bớt sự lan truyền của tiếng ồn đến tai.","Dơi phát ra sóng siêu âm có…: Dơi phát ra sóng siêu âm có tần số từ 50 000 Hz đến 70 000 Hz; khi sóng gặp vật cản thì phản xạ trở lại, giúp dơi nhận ra vật cản."],"e":["Hay nhầm: Âm trực tiếp là âm truyền thẳng từ nguồn đến tai, không bị dội lại.","Hay nhầm: Âm vẫn truyền được; nó chỉ bị dội lại khi gặp mặt chắn.","Hay nhầm: Ánh sáng không phải là âm phản xạ.","Hay nhầm: 1 giây là khoảng thời gian quá lớn so với điều kiện tiếng vang.","Hay nhầm: 1 phút là khoảng thời gian rất lớn, không phải điều kiện tiếng vang.","Hay nhầm: Nếu chậm 0 giây thì âm không tách biệt, không tạo tiếng vang."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương V. Ánh sáng","l":[{"t":"Bài 15. Năng lượng ánh sáng. Tia sáng, vùng tối","req":["Thực hiện thí nghiệm thu được năng lượng ánh sáng; từ đó, nêu được ánh sáng là một dạng của năng lượng.","Thực hiện được thí nghiệm tạo ra mô hình tia sáng bằng một chùm sáng hẹp song song.","Vẽ được hình biểu diễn vùng tối do nguồn sáng rộng và vùng tối do nguồn sáng hẹp."],"sum":["Ánh sáng là một dạng của năng lượng. Ví dụ: pin quang điện nhận năng lượng ánh sáng của đèn và chuyển thành điện năng, làm lệch kim điện kế.","Ánh sáng là một dạng của năng lượng: Ví dụ: pin quang điện nhận năng lượng ánh sáng của đèn và chuyển thành điện năng, làm lệch kim điện kế.","Ánh sáng phát ra từ nguồn sáng…: Ánh sáng phát ra từ nguồn sáng và truyền trong không gian thành chùm sáng.","Ánh sáng truyền theo đường thẳng: Quy ước biểu diễn đường truyền của ánh sáng bằng một đường thẳng có mũi tên chỉ chiều truyền, gọi là tia sáng.","Vùng tối do nguồn sáng hẹp: Phía sau vật cản có vùng hoàn toàn không nhận được ánh sáng, ranh giới với vùng sáng rõ rệt.","Nhật thực xảy ra khi Mặt Trăng…: Nhật thực xảy ra khi Mặt Trăng nằm giữa Mặt Trời và Trái Đất, tạo vùng tối trên Trái Đất."],"e":["Hay nhầm: Ánh sáng không phải là khối lượng.","Hay nhầm: Ánh sáng không phải là điện tích.","Hay nhầm: Nhiệt độ là đại lượng khác, không phải dạng của ánh sáng.","Hay nhầm: Ánh sáng truyền theo đường thẳng nên không biểu diễn bằng đường cong.","Hay nhầm: Đường tròn không biểu diễn đường truyền của ánh sáng.","Hay nhầm: Phải có mũi tên để chỉ chiều truyền."],"q":{"n":8,"lv":{"Biết":5,"Hiểu":1,"Vận dụng":2}}},{"t":"Bài 16. Sự phản xạ ánh sáng","req":["Vẽ được hình biểu diễn và nêu được các khái niệm: tia sáng tới, tia sáng phản xạ, pháp tuyến, góc tới, góc phản xạ, mặt phẳng tới.","Thực hiện được thí nghiệm rút ra định luật và phát biểu được nội dung của định luật phản xạ ánh sáng.","Phân biệt được phản xạ và phản xạ khuếch tán."],"m":[{"t":"Vẽ tia phản xạ và tính góc phản xạ","w":"Đề cho tia tới và gương, yêu cầu vẽ tia phản xạ hoặc tính góc tới, góc phản xạ.","s":["Vẽ pháp tuyến tại điểm tới (đường vuông góc với mặt gương).","Xác định góc tới i: góc giữa tia tới và pháp tuyến (không phải với mặt gương).","Áp dụng định luật: góc phản xạ i′ = góc tới i, tia phản xạ và tia tới nằm hai bên pháp tuyến cùng một mặt phẳng.","Nếu đề cho góc giữa tia tới và mặt gương thì góc tới = 90° − góc đó."],"n":["Góc tới và góc phản xạ đều tính từ pháp tuyến.","Tia tới vuông góc mặt gương thì góc tới 0°, tia phản xạ trùng tia tới.","Góc tạo bởi tia tới và tia phản xạ bằng 2i."]}],"sum":["Khi chiếu một chùm sáng vào gương, chùm sáng bị hắt trở lại theo hướng khác. Hiện tượng đó gọi là phản xạ ánh sáng.","Khái niệm: Khi chiếu một chùm sáng vào gương, chùm sáng bị hắt trở lại theo hướng khác.","Các khái niệm: Gương phẳng là mặt phản xạ; tia sáng tới (SI) là tia chiếu vào gương; tia sáng phản xạ (IR) là tia bị gương hắt trở lại;","Góc tới là góc tạo bởi tia…: Góc tới là góc tạo bởi tia sáng tới và pháp tuyến tại điểm tới; góc phản xạ là góc tạo bởi tia sáng phản xạ và pháp tuyến tại điểm tới.","Định luật phản xạ ánh sáng: Tia sáng phản xạ nằm trong mặt phẳng tới; góc phản xạ bằng góc tới (i' = i).","Phản xạ khuếch tán là hiện tượng…: Phản xạ khuếch tán là hiện tượng các tia sáng song song truyền đến bề mặt không nhẵn, bị phản xạ theo mọi hướng."],"d":["Vẽ tia phản xạ và tính góc phản xạ"],"e":["Hay nhầm: Khúc xạ là hiện tượng ánh sáng đổi phương khi đi qua hai môi trường khác nhau.","Hay nhầm: Khuếch tán là phản xạ theo mọi hướng từ bề mặt không nhẵn.","Hay nhầm: Tán sắc là tách ánh sáng thành các màu.","Hay nhầm: Đường song song với gương không phải pháp tuyến.","Hay nhầm: Tia sáng tới là tia chiếu vào gương, không phải pháp tuyến.","Hay nhầm: Tia phản xạ là tia bị hắt trở lại, không phải pháp tuyến."],"q":{"n":12,"lv":{"Biết":5,"Hiểu":3,"Vận dụng":4}}},{"t":"Bài 17. Ảnh của vật qua gương phẳng","req":["Vẽ được hình biểu diễn và nêu được tính chất ảnh của vật qua gương phẳng.","Dựng được ảnh của một vật qua gương phẳng.","Vận dụng được định luật phản xạ trong một số trường hợp đơn giản."],"sum":["Hình của vật nhìn thấy trong gương phẳng được gọi là ảnh của vật qua gương phẳng. Ảnh này là ảnh ảo, không hứng được trên màn chắn.","Khái niệm: Hình của vật nhìn thấy trong gương phẳng được gọi là ảnh của vật qua gương phẳng.","Tính chất ảnh của vật qua gương phẳng: Ảnh ảo; khoảng cách từ ảnh đến gương bằng khoảng cách từ vật đến gương;","Ảnh S' của một điểm S được…: Ảnh S' của một điểm S được tạo bởi gương phẳng là giao điểm của các tia phản xạ kéo dài.","Ví dụ: Chữ AMBULANCE trên xe cứu thương được viết ngược để khi nhìn qua gương chiếu hậu, ảnh của chữ được đọc đúng."],"e":["Hay nhầm: Ảnh thật hứng được trên màn chắn, ảnh qua gương phẳng thì không.","Hay nhầm: Ảnh qua gương phẳng chỉ là ảnh ảo.","Hay nhầm: Gương phẳng luôn cho ảnh của vật.","Hay nhầm: Ảnh ảo không hứng được trên màn chắn.","Hay nhầm: Gương phẳng không cong; ảnh vẫn là ảnh ảo.","Hay nhầm: Màu sắc không ảnh hưởng đến việc hứng ảnh."],"q":{"n":8,"lv":{"Biết":4,"Hiểu":2,"Vận dụng":2}}}]},{"t":"Chương VI. Từ","l":[{"t":"Bài 18. Nam châm","req":["Tiến hành thí nghiệm để nêu được: tác dụng của nam châm đến các vật liệu khác nhau; sự định hướng của thanh nam châm (kim nam châm).","Xác định được cực Bắc và cực Nam của một thanh nam châm."],"sum":["Nam châm là vật có tính chất từ, hút được một số vật liệu như sắt, cobalt, nickel. Các nam châm có nhiều hình dạng: nam châm thẳng, nam châm hình chữ U, nam châm viên.","Khái niệm: Nam châm là vật có tính chất từ, hút được một số vật liệu như sắt, cobalt, nickel.","Khi để tự do, thanh nam châm…: Khi để tự do, thanh nam châm treo cân bằng hoặc kim nam châm đặt trên mũi nhọn luôn chỉ hướng Bắc – Nam.","Tương tác giữa hai nam châm: Hai từ cực khác tên hút nhau, hai từ cực cùng tên đẩy nhau.","Kim nam châm (nam châm thử) đặt…: Kim nam châm (nam châm thử) đặt gần nam châm sẽ chịu tác dụng của nam châm làm cho kim nằm theo một hướng xác định."],"e":["Hay nhầm: Điện trở là linh kiện điện, không phải vật hút sắt.","Hay nhầm: Tụ điện là linh kiện tích điện, không phải nam châm.","Hay nhầm: Vật dẫn điện không có tính chất hút sắt.","Hay nhầm: S, màu xanh là kí hiệu của cực Nam.","Hay nhầm: Màu xanh là màu của cực Nam, không phải cực Bắc.","Hay nhầm: Cực Nam kí hiệu S và sơn màu xanh."],"q":{"n":8,"lv":{"Biết":4,"Hiểu":2,"Vận dụng":2}}},{"t":"Bài 19. Từ trường","req":["Nêu được vùng không gian bao quanh một nam châm (hoặc dây dẫn mang dòng điện), mà vật liệu có tính chất từ đặt trong nó chịu tác dụng lực từ, được gọi là từ trường.","Nêu được khái niệm từ phổ và tạo được từ phổ bằng mạt sắt và nam châm.","Nêu được khái niệm đường sức từ và vẽ được đường sức từ quanh một nam châm."],"sum":["Vùng không gian bao quanh nam châm hoặc dây dẫn mang dòng điện, mà vật liệu có tính chất từ đặt trong nó chịu tác dụng lực từ, được gọi là từ trường.","Khái niệm: Vùng không gian bao quanh nam châm hoặc dây dẫn mang dòng điện, mà vật liệu có tính chất từ đặt trong nó chịu tác dụng lực từ, được gọi là từ trường.","Từ phổ là hình ảnh các đường mạt sắt xung quanh nam châm: Vùng nào các đường mạt sắt xếp dày thì từ trường ở đó mạnh, vùng nào xếp thưa thì từ trường yếu.","Đường sức từ là đường mô tả…: Đường sức từ là đường mô tả từ trường; chiều đường sức từ được quy ước là chiều đi từ cực Nam đến cực Bắc xuyên dọc kim nam châm đặt cân bằng trên…","Trái Đất là một nam châm khổng lồ: Cực Bắc địa từ nằm gần cực Nam địa lí, cực Nam địa từ nằm gần cực Bắc địa lí, nên hai cực này không trùng nhau.","La bàn là dụng cụ dùng để xác định hướng: Kim nam châm của la bàn luôn chỉ hướng Bắc khi la bàn nằm ngang, từ đó xác định được các hướng địa lí."],"e":["Hay nhầm: Điện trường là khái niệm khác, không phải vùng quanh nam châm.","Hay nhầm: Trọng trường là trường hấp dẫn của Trái Đất, không phải từ trường.","Hay nhầm: Âm thanh không phải là một trường.","Hay nhầm: Điện phổ không phải khái niệm trong bài.","Hay nhầm: Quang phổ liên quan đến ánh sáng, không phải mạt sắt.","Hay nhầm: Âm phổ không phải hình ảnh mạt sắt quanh nam châm."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 20. Chế tạo nam châm điện đơn giản","req":["Chế tạo được nam châm điện đơn giản và làm thay đổi được từ trường của nó bằng thay đổi dòng điện."],"sum":["Dòng điện chạy trong dây dẫn thẳng hoặc trong cuộn dây đều sinh ra từ trường. Người ta ứng dụng tính chất này để chế tạo nam châm điện.","Khái niệm: Dòng điện chạy trong dây dẫn thẳng hoặc trong cuộn dây đều sinh ra từ trường.","Cấu tạo nam châm điện: Một ống dây dẫn quấn quanh lõi là thỏi sắt non; hai đầu cuộn dây được nối với hai cực nguồn điện qua khoá K.","Có thể làm thay đổi từ trường…: Có thể làm thay đổi từ trường của nam châm điện bằng cách thay đổi cường độ dòng điện (ví dụ tăng số pin) và đổi chiều dòng điện (đổi cực nguồn…","Nam châm điện được dùng trong cần…: Nam châm điện được dùng trong cần cẩu dọn rác kim loại, động cơ điện và máy phát điện."],"e":["Hay nhầm: Cọ xát không tạo ra nam châm điện.","Hay nhầm: Đun nóng làm nam châm yếu đi, không tạo nam châm điện.","Hay nhầm: Nhúng nước không tạo nam châm điện.","Hay nhầm: Nhựa không có tính chất từ, không dùng làm lõi.","Hay nhầm: Gỗ không có tính chất từ, không dùng làm lõi.","Hay nhầm: Đồng không có tính chất từ như sắt non."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}}]}]},{"t":"Bài tập nâng cao","c":[{"t":"Chương III. Tốc độ","l":[{"t":"Bài tập nâng cao · Chương III. Tốc độ (12 câu)","e":["Hay nhầm: Số lần đo không thay đổi quãng đường.","Hay nhầm: Việc đo không ảnh hưởng chuyển động.","Hay nhầm: Mỗi lần đo có sai số ngẫu nhiên, trung bình làm giảm sai số.","Hay nhầm: Chuyển động đều ứng với đoạn thẳng xiên.","Hay nhầm: Không suy ra từ đoạn nằm ngang.","Hay nhầm: Khi đó quãng đường sẽ giảm."],"q":{"n":12,"lv":{"Nâng cao":12}}}]},{"t":"Chương IV. Âm thanh","l":[{"t":"Bài tập nâng cao · Chương IV. Âm thanh (9 câu)","e":["Hay nhầm: Tần số lớn hơn làm âm cao hơn, không làm âm to hơn.","Hay nhầm: Tần số nhỏ hơn làm âm trầm hơn.","Hay nhầm: Biên độ nhỏ làm âm nhỏ đi.","Hay nhầm: Vật cứng, nhẵn phản xạ âm tốt.","Hay nhầm: Phản xạ âm tốt, hấp thụ kém.","Hay nhầm: Phản xạ âm tốt, hấp thụ kém."],"q":{"n":9,"lv":{"Nâng cao":9}}}]},{"t":"Chương V. Ánh sáng","l":[{"t":"Bài tập nâng cao · Chương V. Ánh sáng (9 câu)","e":["Hay nhầm: Hai hiện tượng xảy ra cùng lúc.","Hay nhầm: Nguyên nhân là do tốc độ truyền.","Hay nhầm: Nguyên nhân chính là tốc độ truyền khác nhau.","Hay nhầm: Với nguồn sáng rộng còn có vùng nửa tối.","Hay nhầm: Vật chắn sáng cản ánh sáng nên có vùng tối.","Hay nhầm: Đó là góc giữa hai tia, bằng hai lần góc tới."],"q":{"n":9,"lv":{"Nâng cao":9}}}]},{"t":"Chương VI. Từ","l":[{"t":"Bài tập nâng cao · Chương VI. Từ (7 câu)","e":["Hay nhầm: Hai cực khác tên mới hút nhau.","Hay nhầm: Chỉ nam châm mới tương tác hút hoặc đẩy như vậy.","Hay nhầm: Cực cùng tên đẩy nhau nên là cực Bắc.","Hay nhầm: Các đường sức cong khép kín.","Hay nhầm: Đường sức từ có chiều quy ước.","Hay nhầm: Kim chỉ Bắc – Nam do tác dụng của từ trường Trái Đất."],"q":{"n":7,"lv":{"Nâng cao":7}}}]}]}]},{"id":"hoa","name":"Hoá học","b":[{"t":"Hoá học 7","c":[{"t":"Mở đầu","l":[{"t":"Bài 1. Phương pháp và kĩ năng học tập môn Khoa học tự nhiên","req":["Trình bày được phương pháp tìm hiểu tự nhiên.","Thực hiện được các kĩ năng tiến trình: quan sát, phân loại, liên kết, đo, dự báo.","Sử dụng được một số dụng cụ đo trong môn Khoa học tự nhiên 7."],"sum":["Phương pháp tìm hiểu tự nhiên là cách tìm hiểu sự vật, hiện tượng trong tự nhiên bằng các dẫn chứng khoa học.","Khái niệm: Phương pháp tìm hiểu tự nhiên là cách tìm hiểu sự vật, hiện tượng trong tự nhiên bằng các dẫn chứng khoa học.","Nếu kết quả thí nghiệm không phù…: Nếu kết quả thí nghiệm không phù hợp với dự đoán, cần quay lại bước đưa ra dự đoán.","Kĩ năng quan sát là dùng một…: Kĩ năng quan sát là dùng một hoặc nhiều giác quan để thu thập thông tin về đặc điểm, kích thước, hình dạng của sự vật.","Kĩ năng phân loại là nhóm các…: Kĩ năng phân loại là nhóm các đối tượng, khái niệm hoặc sự kiện thành các danh mục, theo đặc điểm được chọn.","Kĩ năng liên kết là dùng số…: Kĩ năng liên kết là dùng số liệu quan sát, kết quả phân tích để xác định mối quan hệ giữa các sự vật và hiện tượng."],"e":["Hay nhầm: Lập kế hoạch là bước 3, chỉ làm sau khi đã có dự đoán.","Hay nhầm: Viết báo cáo là bước 5, làm sau khi đã thực hiện xong kế hoạch.","Hay nhầm: Đưa ra dự đoán là bước 2, làm sau khi đã đề xuất vấn đề.","Hay nhầm: Dự báo là đề xuất điều sẽ xảy ra dựa trên quan sát và suy luận, không phải thu thập thông tin trực tiếp.","Hay nhầm: Liên kết là xác định mối quan hệ giữa các số liệu đã có.","Hay nhầm: Phân loại là nhóm các đối tượng theo đặc điểm được chọn."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương I. Nguyên tử. Sơ lược về bảng tuần hoàn các nguyên tố hoá học","l":[{"t":"Bài 2. Nguyên tử","req":["Trình bày được mô hình nguyên tử của Rutherford – Bohr.","Nêu được khối lượng của một nguyên tử theo đơn vị amu."],"m":[{"t":"Xác định số hạt trong nguyên tử","w":"Đề cho số hạt p, n, e (hoặc tổng số hạt, hiệu số) và hỏi số mỗi loại, điện tích hạt nhân, số lớp electron.","s":["Nhớ: nguyên tử trung hòa nên số p = số e = Z.","Gọi số p = số e = Z, số n = N; lập phương trình từ dữ kiện đề (tổng số hạt = 2Z + N).","Giải hệ để tìm Z và N.","Xác định điện tích hạt nhân, số khối (Z + N), sắp xếp electron vào các lớp (2, 8, ...)."],"n":["Số khối A = p + n, không tính electron (khối lượng electron rất nhỏ).","Hạt không mang điện là neutron.","Lớp 1 chứa tối đa 2 electron; lớp 2 tối đa 8."]}],"sum":["Theo mô hình Rutherford – Bohr, nguyên tử có hạt nhân mang điện tích dương ở tâm, các electron mang điện tích âm chuyển động xung quanh hạt nhân theo từng lớp.","Khái niệm: Theo mô hình Rutherford – Bohr, nguyên tử có hạt nhân mang điện tích dương ở tâm, các electron mang điện tích âm chuyển động xung quanh hạt nhân…","Lớp electron thứ nhất chứa tối đa 2 electron: Các lớp khác chứa tối đa 8 electron hoặc nhiều hơn.","Hạt nhân nguyên tử gồm hạt proton…: Hạt nhân nguyên tử gồm hạt proton mang điện tích +1 và hạt neutron không mang điện.","Vỏ nguyên tử gồm các electron mang…: Vỏ nguyên tử gồm các electron mang điện tích −1, sắp xếp thành từng lớp theo thứ tự từ trong ra ngoài.","Nguyên tử trung hoà về điện, nên…: Nguyên tử trung hoà về điện, nên số proton bằng số electron."],"d":["Xác định số hạt trong nguyên tử"],"e":["Hay nhầm: Electron mang điện tích âm và nằm ở vỏ nguyên tử.","Hay nhầm: Nguyên tử trung hoà về điện, không phải là hạt mang điện tích.","Hay nhầm: Proton mang điện tích dương.","Hay nhầm: Electron mang điện tích âm và nằm ở vỏ nguyên tử.","Hay nhầm: Hạt nhân là phần chứa proton và neutron, không phải một loại hạt.","Hay nhầm: Lớp thứ nhất chứa tối đa 2 electron, không phải 1."],"q":{"n":12,"lv":{"Biết":3,"Hiểu":5,"Vận dụng":4}}},{"t":"Bài 3. Nguyên tố hoá học","req":["Phát biểu được khái niệm về nguyên tố hoá học và kí hiệu nguyên tố hoá học.","Viết được kí hiệu hoá học và đọc được tên của 20 nguyên tố đầu tiên."],"sum":["Nguyên tố hoá học là tập hợp các nguyên tử có cùng số proton trong hạt nhân. Số proton là số hiệu nguyên tử, kí hiệu Z.","Khái niệm: Nguyên tố hoá học là tập hợp các nguyên tử có cùng số proton trong hạt nhân.","Hiện nay người ta đã biết 118 nguyên tố hoá học: Các nguyên tử cùng nguyên tố có thể có số neutron khác nhau.","Tên gọi của nguyên tố được quy…: Tên gọi của nguyên tố được quy định thống nhất trên thế giới theo IUPAC.","Kí hiệu hoá học gồm một hoặc…: Kí hiệu hoá học gồm một hoặc hai chữ cái lấy từ tên gọi của nguyên tố.","Một số nguyên tố có kí hiệu…: Một số nguyên tố có kí hiệu lấy từ tên Latin, không theo tên IUPAC."],"e":["Hay nhầm: Số neutron có thể khác nhau giữa các nguyên tử cùng nguyên tố.","Hay nhầm: Số electron có thể thay đổi, không xác định nguyên tố.","Hay nhầm: Khối lượng có thể khác nhau giữa các đồng vị của cùng nguyên tố.","Hay nhầm: Cả hai chữ cái đều in hoa là không đúng quy định.","Hay nhầm: Chữ đầu phải viết in hoa.","Hay nhầm: Chữ đầu phải in hoa, chữ sau viết thường."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 4. Sơ lược về bảng tuần hoàn các nguyên tố hoá học","req":["Nêu được các nguyên tắc xây dựng bảng tuần hoàn các nguyên tố hoá học.","Mô tả được cấu tạo bảng tuần hoàn gồm ô, nhóm, chu kì.","Sử dụng được bảng tuần hoàn để chỉ ra các nhóm nguyên tố kim loại, phi kim, khí hiếm."],"sum":["Bảng tuần hoàn các nguyên tố hoá học được xây dựng theo ba nguyên tắc: các nguyên tố được xếp theo chiều tăng dần của điện tích hạt nhân; các nguyên tố trong cùng một hàng có cùng số lớp electron;…","Bảng tuần hoàn các nguyên tố hoá học được xây dựng theo ba nguyên tắc: Các nguyên tố được xếp theo chiều tăng dần của điện tích hạt nhân; các nguyên tố trong cùng một hàng có cùng số lớp electron; các nguyên tố trong…","Mỗi ô nguyên tố cho biết kí…: Mỗi ô nguyên tố cho biết kí hiệu hoá học, tên nguyên tố, số hiệu nguyên tử và khối lượng nguyên tử.","Chu kì là dãy các nguyên tố…: Chu kì là dãy các nguyên tố có nguyên tử cùng số lớp electron, sắp xếp theo chiều điện tích hạt nhân tăng dần từ trái sang phải.","Chu kì 1, 2, 3 là chu kì nhỏ: Chu kì 4, 5, 6, 7 là chu kì lớn.","Nhóm là cột trong bảng: Có 8 nhóm A, đánh số từ IA đến VIIIA, và 8 nhóm B, đánh số từ IB đến VIIIB."],"e":["Hay nhầm: Số neutron có thể khác nhau giữa các nguyên tử cùng nguyên tố, nên không dùng để xếp.","Hay nhầm: Khối lượng là đại lượng Mendeleev dùng ban đầu, nhưng bảng hiện nay xếp theo điện tích hạt nhân.","Hay nhầm: Số nhóm là kết quả của việc xếp bảng, không phải nguyên tắc xếp.","Hay nhầm: Nhóm IA chứa kim loại kiềm và hydrogen.","Hay nhầm: Nhóm VIIA chứa halogen, không phải khí hiếm.","Hay nhầm: Nhóm IIA chứa kim loại kiềm thổ."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương II. Phân tử • Liên kết hoá học","l":[{"t":"Bài 5. Phân tử – Đơn chất – Hợp chất","req":["Nêu được khái niệm đơn chất, hợp chất và phân tử.","Đưa ra được một số ví dụ về đơn chất và hợp chất.","Tính được khối lượng phân tử theo đơn vị amu."],"sum":["Đơn chất là chất được tạo nên từ một nguyên tố hoá học. Ví dụ: đồng, oxygen, helium là đơn chất.","Đơn chất là chất được tạo nên từ một nguyên tố hoá học: Ví dụ: đồng, oxygen, helium là đơn chất.","Hợp chất là chất được tạo nên…: Hợp chất là chất được tạo nên từ hai nguyên tố hoá học trở lên.","Phân tử là hạt đại diện cho…: Phân tử là hạt đại diện cho chất, gồm một số nguyên tử liên kết với nhau và thể hiện đầy đủ tính chất hoá học của chất.","Khối lượng phân tử của một chất…: Khối lượng phân tử của một chất bằng tổng khối lượng các nguyên tử trong phân tử chất đó, tính theo đơn vị amu.","Một nguyên tố thường chỉ tạo nên…: Một nguyên tố thường chỉ tạo nên một dạng đơn chất, nhưng carbon có thể tạo nên các dạng như than chì và kim cương."],"e":["Hay nhầm: Chất được tạo nên từ hai nguyên tố trở lên là hợp chất.","Hay nhầm: Hợp chất được tạo nên từ các nguyên tố, không phải từ các hợp chất.","Hay nhầm: Phân tử là hạt cấu tạo nên chất, không phải nguồn gốc của đơn chất.","Hay nhầm: Chất chỉ từ một nguyên tố là đơn chất.","Hay nhầm: Hợp chất có thể chứa phi kim, không chỉ kim loại.","Hay nhầm: Khí hiếm chỉ là một nhóm nguyên tố, không quyết định hợp chất."],"q":{"n":8,"lv":{"Biết":2,"Hiểu":4,"Vận dụng":2}}},{"t":"Bài 6. Giới thiệu về liên kết hoá học","req":["Nêu được mô hình sắp xếp các electron trong vỏ nguyên tử của một số nguyên tố khí hiếm.","Nêu được sự hình thành liên kết cộng hoá trị theo nguyên tắc dùng chung electron.","Nêu được sự hình thành liên kết ion theo nguyên tắc cho và nhận electron."],"sum":["Nguyên tử khí hiếm có lớp electron ngoài cùng bền vững: 8 electron (He có 2 electron).","Nguyên tử khí hiếm có lớp electron ngoài cùng bền vững: 8 electron (He có 2 electron).","Nguyên tử các nguyên tố khác có…: Nguyên tử các nguyên tố khác có xu hướng đạt lớp electron ngoài cùng giống khí hiếm bằng cách nhường, nhận hoặc dùng chung electron.","Liên kết ion được hình thành do…: Liên kết ion được hình thành do lực hút tĩnh điện giữa các ion mang điện tích trái dấu.","Liên kết cộng hoá trị được hình…: Liên kết cộng hoá trị được hình thành do một hoặc nhiều cặp electron dùng chung giữa hai nguyên tử.","Hydrogen và oxygen (đơn chất) chỉ có liên kết cộng hoá trị: Các hợp chất cộng hoá trị thường có nhiệt độ nóng chảy và nhiệt độ sôi thấp, có thể ở thể khí, lỏng hoặc rắn."],"e":["Hay nhầm: 1 electron là đặc điểm của kim loại nhóm I, chưa phải cấu hình bền.","Hay nhầm: 7 electron là số electron lớp ngoài cùng của halogen, chưa bền.","Hay nhầm: 4 electron là số electron của nguyên tử C, chưa bền.","Hay nhầm: Góp chung electron là nguyên tắc của liên kết cộng hoá trị.","Hay nhầm: Proton nằm trong hạt nhân và không tham gia trực tiếp vào liên kết hoá học.","Hay nhầm: Neutron không tham gia trực tiếp vào việc hình thành liên kết hoá học."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 7. Hoá trị và công thức hoá học","req":["Trình bày được khái niệm về hoá trị (cho chất cộng hoá trị), cách viết công thức hoá học.","Viết được công thức hoá học của một số đơn chất và hợp chất đơn giản, thông dụng.","Nêu được mối liên hệ giữa hoá trị của nguyên tố với công thức hoá học của hợp chất."],"m":[{"t":"Lập công thức hóa học và tính phần trăm khối lượng","w":"Đề cho hóa trị của hai nguyên tố hoặc nhóm, yêu cầu lập công thức; hoặc cho công thức, yêu cầu tính phân tử khối, % nguyên tố.","s":["Viết công thức dạng chung AₓBᵧ.","Quy tắc hóa trị: x·(hóa trị A) = y·(hóa trị B).","Lập tỉ lệ x/y tối giản, chọn x, y nguyên nhỏ nhất rồi viết công thức.","Tính phân tử khối; % A = (khối lượng A trong phân tử/phân tử khối)·100%."],"n":["Hóa trị của H là I, O là II; kim loại như Na (I), Mg (II), Al (III).","Rút gọn tỉ lệ x/y về số nguyên tối giản.","Chỉ số 1 không ghi."]}],"sum":["Công thức hoá học của chất là cách biểu diễn chất bằng kí hiệu hoá học của nguyên tố kèm chỉ số ở chân bên phải.","Khái niệm: Công thức hoá học của chất là cách biểu diễn chất bằng kí hiệu hoá học của nguyên tố kèm chỉ số ở chân bên phải.","Công thức hoá học của đơn chất…: Công thức hoá học của đơn chất kim loại, khí hiếm và một số phi kim (có 1 nguyên tử) là kí hiệu hoá học của nguyên tố.","Ý nghĩa của công thức hoá học: Cho biết các nguyên tố tạo nên chất, số nguyên tử (hoặc tỉ lệ số nguyên tử) của các nguyên tố trong phân tử và khối lượng phân tử của chất.","Hoá trị là con số biểu thị…: Hoá trị là con số biểu thị khả năng liên kết của nguyên tử nguyên tố này với nguyên tử nguyên tố khác."],"d":["Lập công thức hóa học và tính phần trăm khối lượng"],"e":["Hay nhầm: Kí hiệu hoá học chỉ viết chữ cái đầu in hoa, chữ sau viết thường.","Hay nhầm: Co là kí hiệu của cobalt, không phải đồng.","Hay nhầm: C là kí hiệu của carbon, không phải đồng.","Hay nhầm: Hoá trị được ghi bằng số La Mã phía trên kí hiệu, không phải chỉ số dưới.","Hay nhầm: Khối lượng nguyên tử không được ghi trong công thức hoá học.","Hay nhầm: Số electron lớp ngoài cùng không thể hiện trong công thức hoá học."],"q":{"n":12,"lv":{"Biết":2,"Hiểu":6,"Vận dụng":4}}}]}]},{"t":"Bài tập nâng cao","c":[{"t":"Chương I. Nguyên tử. Sơ lược về bảng tuần hoàn các nguyên tố hoá học","l":[{"t":"Bài tập nâng cao · Chương I. Nguyên tử. Sơ lược về bảng tuần hoàn các nguyên tố hoá học (9 câu)","e":["Hay nhầm: Số hiệu nguyên tử là số proton."],"q":{"n":9,"lv":{"Nâng cao":9}}}]},{"t":"Chương II. Phân tử • Liên kết hoá học","l":[{"t":"Bài tập nâng cao · Chương II. Phân tử • Liên kết hoá học (10 câu)","e":["Hay nhầm: Chỉ gồm một nguyên tố oxygen nên là đơn chất.","Hay nhầm: Chỉ gồm một nguyên tố nitrogen nên là đơn chất.","Hay nhầm: Chỉ gồm một nguyên tố sắt nên là đơn chất.","Hay nhầm: Liên kết ion thường xảy ra giữa kim loại điển hình và phi kim điển hình.","Hay nhầm: Không có liên kết kim loại giữa H và Cl.","Hay nhầm: Đây không phải loại liên kết đang xét."],"q":{"n":10,"lv":{"Nâng cao":10}}}]}]}]},{"id":"sinh","name":"Sinh học","b":[{"t":"Sinh học 7","c":[{"t":"Mở đầu","l":[{"t":"Bài 1. Phương pháp và kĩ năng học tập môn Khoa học tự nhiên","req":["Trình bày được phương pháp tìm hiểu tự nhiên.","Thực hiện được các kĩ năng tiến trình: quan sát, phân loại, liên kết, đo, dự báo.","Sử dụng được một số dụng cụ đo trong môn Khoa học tự nhiên 7."],"sum":["Phương pháp tìm hiểu tự nhiên là cách tìm hiểu sự vật, hiện tượng trong tự nhiên bằng các dẫn chứng khoa học.","Khái niệm: Phương pháp tìm hiểu tự nhiên là cách tìm hiểu sự vật, hiện tượng trong tự nhiên bằng các dẫn chứng khoa học.","Nếu kết quả thí nghiệm không phù…: Nếu kết quả thí nghiệm không phù hợp với dự đoán, cần quay lại bước đưa ra dự đoán.","Kĩ năng quan sát là dùng một…: Kĩ năng quan sát là dùng một hoặc nhiều giác quan để thu thập thông tin về đặc điểm, kích thước, hình dạng của sự vật.","Kĩ năng phân loại là nhóm các…: Kĩ năng phân loại là nhóm các đối tượng, khái niệm hoặc sự kiện thành các danh mục, theo đặc điểm được chọn.","Kĩ năng liên kết là dùng số…: Kĩ năng liên kết là dùng số liệu quan sát, kết quả phân tích để xác định mối quan hệ giữa các sự vật và hiện tượng."],"e":["Hay nhầm: Lập kế hoạch là bước 3, chỉ làm sau khi đã có dự đoán.","Hay nhầm: Viết báo cáo là bước 5, làm sau khi đã thực hiện xong kế hoạch.","Hay nhầm: Đưa ra dự đoán là bước 2, làm sau khi đã đề xuất vấn đề.","Hay nhầm: Dự báo là đề xuất điều sẽ xảy ra dựa trên quan sát và suy luận, không phải thu thập thông tin trực tiếp.","Hay nhầm: Liên kết là xác định mối quan hệ giữa các số liệu đã có.","Hay nhầm: Phân loại là nhóm các đối tượng theo đặc điểm được chọn."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương VII. Trao đổi chất và chuyển hoá năng lượng ở sinh vật","l":[{"t":"Bài 21. Khái quát về trao đổi chất và chuyển hoá năng lượng","req":["Phát biểu được khái niệm trao đổi chất và chuyển hoá năng lượng.","Nêu được vai trò của trao đổi chất và chuyển hoá năng lượng trong cơ thể."],"sum":["Trao đổi chất là quá trình sinh vật lấy các chất từ môi trường, biến đổi chúng thành các chất cần thiết cho cơ thể và tạo năng lượng cung cấp cho các hoạt động sống, đồng thời thải các chất thải trả…","Khái niệm: Trao đổi chất là quá trình sinh vật lấy các chất từ môi trường, biến đổi chúng thành các chất cần thiết cho cơ thể và tạo năng lượng cung cấp cho…","Chuyển hoá năng lượng là sự biến…: Chuyển hoá năng lượng là sự biến đổi năng lượng từ dạng này sang dạng khác.","Trao đổi chất và chuyển hoá năng…: Trao đổi chất và chuyển hoá năng lượng luôn gắn liền với nhau.","Trao đổi chất và chuyển hoá năng…: Trao đổi chất và chuyển hoá năng lượng giúp sinh vật tồn tại, sinh trưởng, phát triển, sinh sản, cảm ứng và vận động."],"e":["Hay nhầm: Sinh sản là quá trình tạo ra cơ thể mới, không phải trao đổi chất.","Hay nhầm: Cảm ứng là phản ứng với kích thích, không phải trao đổi chất.","Hay nhầm: Vận động là di chuyển, không phải định nghĩa trao đổi chất.","Hay nhầm: Chất thải không phải là chuyển hoá năng lượng.","Hay nhầm: Sinh con là sinh sản, không phải chuyển hoá năng lượng.","Hay nhầm: Di chuyển là vận động, không phải chuyển hoá năng lượng."],"q":{"n":8,"lv":{"Biết":4,"Hiểu":2,"Vận dụng":2}}},{"t":"Bài 22. Quang hợp ở thực vật","req":["Nêu được khái niệm, nguyên liệu, sản phẩm của quang hợp.","Viết được phương trình quang hợp.","Nêu được mối quan hệ giữa trao đổi chất và chuyển hoá năng lượng trong quang hợp."],"sum":["Quang hợp là quá trình lá cây sử dụng nước và khí carbon dioxide nhờ năng lượng ánh sáng để tổng hợp chất hữu cơ và giải phóng oxygen.","Khái niệm: Quang hợp là quá trình lá cây sử dụng nước và khí carbon dioxide nhờ năng lượng ánh sáng để tổng hợp chất hữu cơ và giải phóng oxygen.","Các phân tử glucose tạo thành trong…: Các phân tử glucose tạo thành trong quang hợp liên kết với nhau hình thành tinh bột, là chất dự trữ đặc trưng ở thực vật.","Trong quang hợp, trao đổi chất và…: Trong quang hợp, trao đổi chất và chuyển hoá năng lượng diễn ra đồng thời: quang năng chuyển hoá thành hoá năng dự trữ trong các hợp chất hữu cơ.","Lá là cơ quan chủ yếu thực hiện quang hợp: Phiến lá có diện tích bề mặt lớn; lớp biểu bì có khí khổng để carbon dioxide đi vào và oxygen đi ra; lục lạp chứa diệp lục để hấp thụ ánh sáng; gân…"],"e":["Hay nhầm: Khí nitrogen không được tổng hợp trong quang hợp.","Hay nhầm: Nước là nguyên liệu, không phải sản phẩm của quang hợp.","Hay nhầm: Muối khoáng được hấp thụ từ đất, không phải sản phẩm quang hợp.","Hay nhầm: Ti thể là nơi hô hấp tế bào.","Hay nhầm: Nhân chứa vật chất di truyền, không thực hiện quang hợp.","Hay nhầm: Ribosome tổng hợp protein, không thực hiện quang hợp."],"q":{"n":8,"lv":{"Biết":4,"Hiểu":2,"Vận dụng":2}}},{"t":"Bài 23. Một số yếu tố ảnh hưởng đến quang hợp","req":["Vận dụng hiểu biết về quang hợp để giải thích được ý nghĩa thực tiễn của việc trồng và bảo vệ cây xanh.","Nêu được một số yếu tố chủ yếu ảnh hưởng đến quang hợp."],"sum":["Khi cường độ ánh sáng tăng thì hiệu quả quang hợp tăng; ánh sáng quá mạnh làm lá bị đốt nóng và giảm hiệu quả quang hợp.","Khi cường độ ánh sáng tăng thì hiệu quả quang hợp tăng: Ánh sáng quá mạnh làm lá bị đốt nóng và giảm hiệu quả quang hợp.","Nước vừa là nguyên liệu của quang…: Nước vừa là nguyên liệu của quang hợp, vừa tham gia vào việc đóng, mở khí khổng.","Thông thường, hiệu quả quang hợp tăng…: Thông thường, hiệu quả quang hợp tăng khi nồng độ khí carbon dioxide ngoài môi trường tăng.","Nhiệt độ thuận lợi nhất cho hầu…: Nhiệt độ thuận lợi nhất cho hầu hết các loài cây quang hợp là từ 25 °C đến 35 °C.","Vận dụng: Trồng cây đúng thời vụ và đảm bảo mật độ phù hợp để cây nhận đủ ánh sáng, nước và khí carbon dioxide; hạn chế nhiệt độ quá cao khi nắng nóng bằng…"],"e":["Hay nhầm: Bóng râm là nơi sống của cây ưa bóng.","Hay nhầm: Trong bóng tối cây không quang hợp được.","Hay nhầm: Dưới nước sâu là môi trường không phù hợp với cây ưa sáng.","Hay nhầm: Nước là nguyên liệu, không phải sản phẩm quang hợp.","Hay nhầm: Nước không làm tăng nhiệt độ lá một cách có lợi cho quang hợp.","Hay nhầm: Nước không làm mất diệp lục."],"q":{"n":8,"lv":{"Biết":4,"Hiểu":2,"Vận dụng":2}}},{"t":"Bài 24. Thực hành: Chứng minh quang hợp ở cây xanh","req":["Tiến hành được thí nghiệm chứng minh quang hợp ở cây xanh."],"sum":["Thí nghiệm 1 chứng minh tinh bột được tạo thành trong quang hợp: đặt cây trong bóng tối 2 ngày để tiêu hết tinh bột; che một phần lá bằng giấy đen rồi đưa ra ánh sáng 4–6 giờ; ngắt lá, đun trong cồn…","Thí nghiệm 1 chứng minh tinh bột được tạo thành trong quang hợp: Đặt cây trong bóng tối 2 ngày để tiêu hết tinh bột; che một phần lá bằng giấy đen rồi đưa ra ánh sáng 4–6 giờ; ngắt lá, đun trong cồn 90° để tẩy…","Kết quả: Phần lá không che bị nhuộm màu xanh tím, phần lá bị che không đổi màu.","Thí nghiệm 2 chứng minh quang hợp giải phóng khí oxygen: Cành rong đuôi chó đặt trong cốc có ánh sáng, khí oxygen thu được làm que đóm còn tàn đỏ bùng cháy.","Lưu ý an toàn: Cẩn thận khi làm thí nghiệm với dụng cụ thuỷ tinh và lửa; cồn 90° dễ cháy."],"e":["Hay nhầm: Bóng tối không làm tăng diệp lục.","Hay nhầm: Bóng tối không làm tăng oxygen.","Hay nhầm: Bóng tối không làm lá đổi màu.","Hay nhầm: Nước muối không dùng để thử tinh bột.","Hay nhầm: Giấm không dùng để thử tinh bột.","Hay nhầm: Cồn không phải thuốc thử tinh bột."],"q":{"n":8,"lv":{"Biết":4,"Hiểu":2,"Vận dụng":2}}},{"t":"Bài 25. Hô hấp tế bào","req":["Mô tả được một cách tổng quát quá trình hô hấp tế bào (ở thực vật và ở động vật).","Nêu được khái niệm hô hấp tế bào; viết được phương trình hô hấp dạng chữ.","Thể hiện được hai chiều tổng hợp và phân giải chất hữu cơ ở tế bào."],"sum":["Hô hấp tế bào là quá trình các chất hữu cơ (chủ yếu là glucose) được phân giải thành khí carbon dioxide và nước, đồng thời tạo ra năng lượng ATP cung cấp cho các hoạt động của tế bào.","Khái niệm: Hô hấp tế bào là quá trình các chất hữu cơ (chủ yếu là glucose) được phân giải thành khí carbon dioxide và nước, đồng thời tạo ra năng lượng ATP…","Quá trình tổng hợp và phân giải…: Quá trình tổng hợp và phân giải chất hữu cơ có biểu hiện trái ngược nhau nhưng phụ thuộc lẫn nhau: tổng hợp chất hữu cơ tạo nguyên liệu cho hô hấp,…","Hô hấp tế bào khác với đốt cháy nhiên liệu: Năng lượng được giải phóng từ từ qua nhiều giai đoạn và phần lớn được tích luỹ dưới dạng hoá năng, hiệu suất sinh năng lượng cao hơn (khoảng 40%)."],"e":["Hay nhầm: Lục lạp là nơi quang hợp, không phải hô hấp.","Hay nhầm: Nhân chứa vật chất di truyền, không thực hiện hô hấp.","Hay nhầm: Ribosome tổng hợp protein.","Hay nhầm: Glucose và oxygen là nguyên liệu của hô hấp tế bào.","Hay nhầm: Tinh bột và nitrogen không phải sản phẩm của hô hấp.","Hay nhầm: Diệp lục và ánh sáng liên quan đến quang hợp."],"q":{"n":8,"lv":{"Biết":4,"Hiểu":2,"Vận dụng":2}}},{"t":"Bài 26. Một số yếu tố ảnh hưởng đến hô hấp tế bào","req":["Nêu được một số yếu tố chủ yếu ảnh hưởng đến hô hấp tế bào.","Vận dụng hiểu biết về hô hấp tế bào để giải thích một số hiện tượng trong thực tiễn."],"sum":["Nước là dung môi và môi trường cho các phản ứng hô hấp xảy ra, nên nước liên quan trực tiếp đến hô hấp của tế bào.","Khái niệm: Nước là dung môi và môi trường cho các phản ứng hô hấp xảy ra, nên nước liên quan trực tiếp đến hô hấp của tế bào.","Oxygen là nguyên liệu của hô hấp…: Oxygen là nguyên liệu của hô hấp tế bào nên có ảnh hưởng trực tiếp đến hô hấp.","Nồng độ khí carbon dioxide ngoài môi…: Nồng độ khí carbon dioxide ngoài môi trường từ 3% đến 5% đã gây ức chế hô hấp;","Nhiệt độ quá cao hoặc quá thấp…: Nhiệt độ quá cao hoặc quá thấp đều ảnh hưởng đến hô hấp tế bào.","Để bảo quản nông sản sau thu…: Để bảo quản nông sản sau thu hoạch, cần đưa cường độ hô hấp về mức tối thiểu bằng cách phơi/sấy khô (hạt còn độ ẩm khoảng 13% đến 16%), bảo quản…"],"e":["Hay nhầm: Ánh sáng ảnh hưởng đến quang hợp, không phải dung môi hô hấp.","Hay nhầm: Âm thanh không ảnh hưởng đến hô hấp tế bào.","Hay nhầm: Trọng lực không ảnh hưởng trực tiếp đến hô hấp tế bào.","Hay nhầm: Oxygen là nguyên liệu, không phải sản phẩm.","Hay nhầm: Oxygen không trực tiếp làm tăng nhiệt độ.","Hay nhầm: 20% là nồng độ oxygen trong không khí bình thường."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 27. Thực hành: Hô hấp ở thực vật","req":["Tiến hành được thí nghiệm về hô hấp tế bào ở thực vật thông qua sự nảy mầm của hạt."],"sum":["Hạt đậu xanh, đậu đỏ... được ngâm trong nước ấm khoảng 40 °C trong 2 giờ để hạt hút nước và nảy mầm nhanh.","Hạt đậu xanh, đậu đỏ: Được ngâm trong nước ấm khoảng 40 °C trong 2 giờ để hạt hút nước và nảy mầm nhanh.","Thí nghiệm: Đặt đĩa có hạt nảy mầm cùng cốc nước vôi trong vào chuông A;","Giải thích: Hạt nảy mầm hô hấp mạnh, thải ra khí carbon dioxide làm nước vôi trong bị vẩn đục (CO₂ tác dụng với nước vôi tạo kết tủa).","Kết luận: Hạt đang nảy mầm hô hấp và thải khí carbon dioxide."],"e":["Hay nhầm: Ngâm nước ấm không làm hạt hỏng.","Hay nhầm: Mục đích là nảy mầm, không phải tăng khối lượng khô.","Hay nhầm: Nước vôi trong không phát hiện oxygen.","Hay nhầm: Nước vôi không làm nóng hạt.","Hay nhầm: Nước vôi không dùng để làm ẩm không khí.","Hay nhầm: Nước vôi trong chuông B vẫn trong; chuông A bị vẩn đục."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 28. Trao đổi khí ở sinh vật","req":["Sử dụng hình ảnh để mô tả được quá trình trao đổi khí qua tế bào khí khổng ở lá.","Dựa vào hình vẽ, mô tả được cấu tạo khí khổng và nêu được chức năng của khí khổng.","Dựa vào sơ đồ khái quát, mô tả được đường đi của khí qua các cơ quan của hệ hô hấp ở động vật (ví dụ ở người)."],"sum":["Trao đổi khí là quá trình sinh vật lấy O₂ hoặc CO₂ từ môi trường vào cơ thể, đồng thời thải ra môi trường khí CO₂ hoặc O₂.","Khái niệm: Trao đổi khí là quá trình sinh vật lấy O₂ hoặc CO₂ từ môi trường vào cơ thể, đồng thời thải ra môi trường khí CO₂ hoặc O₂.","Ở thực vật, khí khổng là nơi trao đổi khí chủ yếu: Mỗi khí khổng gồm hai tế bào hình hạt đậu; khi quang hợp, khí khổng mở cho CO₂ vào lá và O₂ ra ngoài; khi hô hấp, quá trình này diễn ra ngược lại.","Ở động vật, trao đổi khí diễn…: Ở động vật, trao đổi khí diễn ra qua cơ quan trao đổi khí như da, hệ thống ống khí, mang hoặc phổi.","Ở người, không khí đi qua mũi…: Ở người, không khí đi qua mũi, hầu, khí quản, phế quản để vào phổi."],"e":["Hay nhầm: Trao đổi khí không chỉ là thải nước.","Hay nhầm: Hấp thụ ánh sáng là quang hợp, không phải trao đổi khí.","Hay nhầm: Tạo muối không phải trao đổi khí.","Hay nhầm: Rễ hấp thụ nước và muối khoáng, không trao đổi khí chủ yếu.","Hay nhầm: Thân gỗ không phải nơi trao đổi khí chủ yếu.","Hay nhầm: Hoa không phải bộ phận trao đổi khí chủ yếu."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 29. Vai trò của nước và chất dinh dưỡng đối với sinh vật","req":["Dựa vào sơ đồ (hoặc mô hình), nêu được thành phần hoá học, cấu trúc và tính chất của nước.","Nêu được vai trò của nước và các chất dinh dưỡng đối với cơ thể sinh vật."],"sum":["Mỗi phân tử nước được tạo thành từ một nguyên tử oxygen liên kết với hai nguyên tử hydrogen bằng liên kết cộng hoá trị.","Khái niệm: Mỗi phân tử nước được tạo thành từ một nguyên tử oxygen liên kết với hai nguyên tử hydrogen bằng liên kết cộng hoá trị.","Nước là thành phần chủ yếu cấu…: Nước là thành phần chủ yếu cấu tạo nên tế bào và cơ thể sinh vật.","Chất dinh dưỡng cung cấp nguyên liệu…: Chất dinh dưỡng cung cấp nguyên liệu và năng lượng cho các quá trình sống.","Ở động vật, chất dinh dưỡng gồm…: Ở động vật, chất dinh dưỡng gồm protein, carbohydrate, lipid (cần với lượng lớn), vitamin và chất khoáng (cần ít nhưng không thể thiếu)."],"e":["Hay nhầm: Công thức nước không có hai nguyên tử oxygen.","Hay nhầm: Nước không chứa nitrogen.","Hay nhầm: 10% quá thấp so với tỉ lệ nước trong cơ thể người.","Hay nhầm: 30% không đúng với tỉ lệ nước ở người.","Hay nhầm: 95% là tỉ lệ nước ở sứa biển, không phải người.","Hay nhầm: Nitrogen không tạo ra ánh sáng."],"q":{"n":8,"lv":{"Biết":4,"Hiểu":2,"Vận dụng":2}}},{"t":"Bài 30. Trao đổi nước và chất dinh dưỡng ở thực vật","req":["Dựa vào sơ đồ đơn giản mô tả được con đường hấp thụ, vận chuyển nước và chất khoáng từ môi trường ngoài vào miền lông hút, vào rễ, lên thân và lá cây.","Dựa vào sơ đồ, hình ảnh phân biệt được sự vận chuyển các chất trong mạch gỗ từ rễ lên lá cây và từ lá xuống các cơ quan trong mạch rây.","Nêu được vai trò của thoát hơi nước ở lá và hoạt động đóng, mở khí khổng."],"sum":["Ở đa số thực vật, nước và chất khoáng được hấp thụ qua tế bào lông hút ở rễ, sau đó vận chuyển theo mạch gỗ lên thân, lá.","Khái niệm: Ở đa số thực vật, nước và chất khoáng được hấp thụ qua tế bào lông hút ở rễ, sau đó vận chuyển theo mạch gỗ lên thân, lá.","Mạch gỗ vận chuyển nước và chất…: Mạch gỗ vận chuyển nước và chất khoáng từ rễ lên các bộ phận khác của cây (dòng đi lên).","Thoát hơi nước diễn ra chủ yếu qua khí khổng ở lá: Khi cây đủ nước, tế bào khí khổng trương nước, khí khổng mở rộng nên hơi nước thoát ra nhiều; khi cây thiếu nước, khí khổng khép lại.","Thoát hơi nước là động lực đầu…: Thoát hơi nước là động lực đầu trên của dòng đi lên, giúp vận chuyển nước và chất khoáng từ rễ lên lá; khí khổng mở tạo điều kiện cho CO₂ vào lá và…","Các yếu tố ảnh hưởng đến trao đổi nước và chất dinh dưỡng ở thực vật: Ánh sáng (gây mở khí khổng), nhiệt độ, độ ẩm không khí và độ tơi xốp, thoáng khí của đất."],"e":["Hay nhầm: Lá chủ yếu quang hợp và thoát hơi nước.","Hay nhầm: Hoa không hấp thụ nước và chất khoáng chủ yếu.","Hay nhầm: Quả không phải cơ quan hấp thụ nước chủ yếu.","Hay nhầm: Mạch rây vận chuyển chất hữu cơ.","Hay nhầm: Biểu bì bảo vệ, không vận chuyển.","Hay nhầm: Tế bào lông hút hấp thụ, không vận chuyển."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 31. Trao đổi nước và chất dinh dưỡng ở động vật","req":["Dựa vào sơ đồ khái quát, mô tả được con đường thu nhận và tiêu hoá thức ăn trong ống tiêu hoá ở động vật (đại diện ở người).","Trình bày được con đường trao đổi nước và nhu cầu sử dụng nước ở động vật.","Mô tả được quá trình vận chuyển các chất ở động vật, lấy ví dụ cụ thể hai vòng tuần hoàn ở người."],"sum":["Động vật thu nhận thức ăn chủ yếu qua hoạt động ăn và uống. Thức ăn được biến đổi trong ống tiêu hoá thành các chất đơn giản và được hấp thụ vào máu; các chất cặn bã được thải ra ngoài qua hậu môn.","Động vật thu nhận thức ăn chủ yếu qua hoạt động ăn và uống: Thức ăn được biến đổi trong ống tiêu hoá thành các chất đơn giản và được hấp thụ vào máu; các chất cặn bã được thải ra ngoài qua hậu môn.","Ở người, nước được hấp thụ chủ…: Ở người, nước được hấp thụ chủ yếu qua thức ăn và nước uống; ruột già là nơi hấp thụ nhiều nước nhất.","Ở người, các chất được vận chuyển theo hai vòng tuần hoàn: Vòng tuần hoàn nhỏ đưa máu từ tim đến phổi để nhận O₂ và thải CO₂; vòng tuần hoàn lớn đưa máu giàu O₂ và chất dinh dưỡng đi nuôi cơ thể.","Khuyến nghị: Để bổ sung nước, cần uống đủ nước mỗi ngày; cơ thể trẻ em cần 40 mL nước cho mỗi 1 kg thể trọng.","Vệ sinh ăn uống: Ăn chín, uống sôi, rửa tay trước khi ăn, sử dụng thực phẩm rõ nguồn gốc để hạn chế vi khuẩn, nấm và giun sán gây hại cho hệ tiêu hoá."],"e":["Hay nhầm: Dạ dày hấp thụ ít nước hơn ruột già.","Hay nhầm: Miệng không hấp thụ nhiều nước.","Hay nhầm: Thực quản chỉ là đường dẫn thức ăn.","Hay nhầm: Phổi là nơi trao đổi khí.","Hay nhầm: Tim bơm máu, không tạo nước tiểu.","Hay nhầm: Não không thuộc vòng tuần hoàn nhỏ."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 32. Thực hành: Chứng minh thân vận chuyển nước và lá thoát hơi nước","req":["Tiến hành được thí nghiệm chứng minh thân vận chuyển nước và lá thoát hơi nước."],"sum":["Cây cần tây có phần thân rất ngắn, phần cuống lá dài, nên nước và chất khoáng được vận chuyển qua thân rất nhanh để vào mạch gỗ ở cuống lá và thoát ra ngoài qua lá.","Khái niệm: Cây cần tây có phần thân rất ngắn, phần cuống lá dài, nên nước và chất khoáng được vận chuyển qua thân rất nhanh để vào mạch gỗ ở cuống lá và thoát…","Thí nghiệm 1: Cắt ngang cuống lá cần tây gần gốc rồi cắm vào cốc nước pha màu (xanh hoặc đỏ).","Thí nghiệm 2: Cắt ngang phần cuống lá có màu rồi quan sát dưới kính lúp; màu nhuộm xuất hiện ở các bó mạch dẫn, chứng tỏ mạch gỗ vận chuyển nước.","Thí nghiệm 3: Dùng túi nylon trong suốt bao kín lá (hoặc cành) cây trồng trong chậu đất ẩm.","Lưu ý an toàn khi dùng dao…: Lưu ý an toàn khi dùng dao mổ và kính lúp; chọn cây có thân thấp, nhiều lá để thí nghiệm rõ."],"e":["Hay nhầm: Thí nghiệm không đo ánh sáng.","Hay nhầm: Thí nghiệm không liên quan đến âm thanh.","Hay nhầm: Nhiệt không phải đối tượng chính.","Hay nhầm: Cắt ngang không làm cây cao lên.","Hay nhầm: Cắt ngang không làm cây ra hoa.","Hay nhầm: Cắt ngang không làm cây quang hợp nhiều hơn."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương VIII. Cảm ứng ở sinh vật","l":[{"t":"Bài 33. Cảm ứng ở sinh vật và tập tính ở động vật","req":["Phát biểu được khái niệm cảm ứng ở sinh vật. Lấy được ví dụ về các hiện tượng cảm ứng ở sinh vật (ở thực vật và động vật).","Phát biểu được khái niệm tập tính ở động vật. Lấy được ví dụ minh hoạ.","Nêu được vai trò của cảm ứng đối với sinh vật và tập tính đối với động vật."],"sum":["Cảm ứng là phản ứng của sinh vật đối với các kích thích đến từ môi trường. Ví dụ: cây phản ứng với ánh sáng chiếu từ một phía bằng cách ngọn cây hướng về phía có ánh sáng; rễ cây hướng về nguồn…","Khái niệm: Cảm ứng là phản ứng của sinh vật đối với các kích thích đến từ môi trường.","Cảm ứng giúp sinh vật thích ứng…: Cảm ứng giúp sinh vật thích ứng với những thay đổi của môi trường để tồn tại và phát triển.","Tập tính là một chuỗi những phản…: Tập tính là một chuỗi những phản ứng trả lời các kích thích đến từ môi trường bên trong hoặc bên ngoài cơ thể, đảm bảo cho động vật tồn tại và phát…","Tập tính bẩm sinh là loại tập…: Tập tính bẩm sinh là loại tập tính sinh ra đã có, đặc trưng cho loài.","Tập tính thường gặp ở động vật: Tập tính kiếm ăn, tập tính bảo vệ lãnh thổ, tập tính sinh sản, tập tính chăm sóc con non, tập tính di cư."],"e":["Hay nhầm: Sinh con cái là sinh sản, không phải cảm ứng.","Hay nhầm: Trao đổi khí là quá trình khác.","Hay nhầm: Hấp thụ nước là quá trình trao đổi nước.","Hay nhầm: Cây không có tập tính như động vật.","Hay nhầm: Lá cụp không phải sinh sản.","Hay nhầm: Lá cụp không phải trao đổi khí."],"q":{"n":8,"lv":{"Biết":4,"Hiểu":2,"Vận dụng":2}}},{"t":"Bài 34. Vận dụng hiện tượng cảm ứng ở sinh vật vào thực tiễn","req":["Vận dụng được các kiến thức cảm ứng vào giải thích một số hiện tượng trong thực tiễn (trong học tập, chăn nuôi, trồng trọt)."],"sum":["Con người đã ứng dụng tính hướng sáng, hướng nước, hướng chất dinh dưỡng ở các loài thực vật để có chế độ chiếu sáng, tưới nước, bón phân, làm giàn phù hợp với mỗi loài, giúp cây sinh trưởng và phát…","Khái niệm: Con người đã ứng dụng tính hướng sáng, hướng nước, hướng chất dinh dưỡng ở các loài thực vật để có chế độ chiếu sáng, tưới nước, bón phân, làm giàn…","Ví dụ: Người ta làm trụ cho cây hồ tiêu dựa trên hiện tượng cảm ứng hướng tiếp xúc, giúp cây leo sinh trưởng nhanh và cho năng suất cao.","Con người cũng lợi dụng tập tính…: Con người cũng lợi dụng tập tính của các loài động vật gây hại cho cây trồng như bướm, bọ xít, châu chấu, chuột để tìm cách xua đuổi và tiêu diệt…","Trong chăn nuôi, con người huấn luyện…: Trong chăn nuôi, con người huấn luyện vật nuôi có các tập tính tốt như ăn, ngủ đúng giờ, đi vệ sinh đúng chỗ, nghe hiệu lệnh.","Các thói quen tốt hay xấu ở…: Các thói quen tốt hay xấu ở người đều là tập tính học được, được hình thành do lặp đi lặp lại nhiều lần trong quá trình sống."],"e":["Hay nhầm: Hướng sáng là phản ứng với ánh sáng, không dùng để làm trụ leo.","Hay nhầm: Hướng nước là phản ứng với nước.","Hay nhầm: Không có hiện tượng cảm ứng hướng đất trong bài.","Hay nhầm: Không liên quan đến sinh sản.","Hay nhầm: Không liên quan đến di cư.","Hay nhầm: Không liên quan đến hướng sáng."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 35. Thực hành: Cảm ứng ở sinh vật","req":["Trình bày được cách làm thí nghiệm chứng minh tính cảm ứng ở thực vật (ví dụ hướng sáng, hướng nước, hướng tiếp xúc).","Quan sát, ghi chép và trình bày được kết quả quan sát một số tập tính của động vật."],"sum":["Thí nghiệm chứng minh tính hướng nước của cây: gieo hạt đỗ vào 2 chậu, khi cây có 3 đến 5 lá, đặt chậu nước có lỗ thủng nhỏ vào một chậu sao cho nước ngấm vào đất mà không ngập úng.","Thí nghiệm chứng minh tính hướng nước của cây: Gieo hạt đỗ vào 2 chậu, khi cây có 3 đến 5 lá, đặt chậu nước có lỗ thủng nhỏ vào một chậu sao cho nước ngấm vào đất mà không ngập úng.","Thí nghiệm chứng minh tính hướng sáng của cây: Úp hộp carton (một hộp có khoét lỗ phía bên cạnh) lên chậu cây; sau 3 đến 5 ngày, nhấc hộp ra và quan sát hướng của thân cây.","Quan sát tính hướng tiếp xúc: Quan sát tranh ảnh, video về tính hướng tiếp xúc của cây mướp hoặc cây bầu, bí.","Lưu ý: Ghi kết quả quan sát vào phiếu theo mẫu và so sánh với chậu đối chứng."],"e":["Hay nhầm: Chậu nước không làm cây nóng lên.","Hay nhầm: Chậu nước không làm cây ngừng sinh trưởng.","Hay nhầm: Chậu nước làm đất ẩm, không làm đất khô.","Hay nhầm: Hộp khoét lỗ không làm tối hoàn toàn.","Hay nhầm: Hộp không dùng để giữ ẩm đất.","Hay nhầm: Thân cây không hướng về phía tối."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương IX. Sinh trưởng và phát triển ở sinh vật","l":[{"t":"Bài 36. Khái quát về sinh trưởng và phát triển ở sinh vật","req":["Phát biểu được khái niệm sinh trưởng và phát triển ở sinh vật.","Nêu được mối quan hệ giữa sinh trưởng và phát triển.","Chỉ ra được mô phân sinh trên sơ đồ cắt ngang thân cây hai lá mầm và trình bày được chức năng của mô phân sinh làm cây lớn lên."],"sum":["Sinh trưởng là sự tăng về kích thước và khối lượng của cơ thể do sự tăng lên về số lượng và kích thước tế bào, nhờ đó cơ thể lớn lên.","Khái niệm: Sinh trưởng là sự tăng về kích thước và khối lượng của cơ thể do sự tăng lên về số lượng và kích thước tế bào, nhờ đó cơ thể lớn lên.","Phát triển bao gồm sinh trưởng, phân…: Phát triển bao gồm sinh trưởng, phân hoá tế bào, phát sinh hình thái cơ quan và cơ thể.","Các giai đoạn sinh trưởng và phát…: Các giai đoạn sinh trưởng và phát triển diễn ra đan xen với nhau.","Thực vật sinh trưởng nhờ mô phân sinh: Mô phân sinh đỉnh ở đỉnh rễ và đỉnh chồi giúp thân, cành và rễ tăng lên về chiều dài.","Thực vật một lá mầm có mô…: Thực vật một lá mầm có mô phân sinh lóng giúp chiều cao cây tăng lên nhanh; cây hai lá mầm lâu năm có mô phân sinh thứ cấp giúp đường kính thân tăng…"],"e":["Hay nhầm: Số lượng loài không phải là sinh trưởng cá thể.","Hay nhầm: Màu sắc không là định nghĩa sinh trưởng.","Hay nhầm: Nhiệt độ không là định nghĩa sinh trưởng.","Hay nhầm: Phát triển không chỉ là sinh trưởng.","Hay nhầm: Sinh sản không phải toàn bộ phát triển.","Hay nhầm: Hô hấp không phải phát triển."],"q":{"n":8,"lv":{"Biết":4,"Hiểu":2,"Vận dụng":2}}},{"t":"Bài 37. Ứng dụng sinh trưởng và phát triển ở sinh vật vào thực tiễn","req":["Nêu được các nhân tố chủ yếu ảnh hưởng đến sinh trưởng và phát triển ở sinh vật (nhân tố nhiệt độ, ánh sáng, nước, chất dinh dưỡng).","Trình bày được một số ứng dụng sinh trưởng và phát triển trong thực tiễn (ví dụ: điều hoà sinh trưởng và phát triển ở sinh vật bằng sử dụng chất kích thích hoặc điều khiển yếu tố môi trường).","Vận dụng được những hiểu biết về sinh trưởng và phát triển của sinh vật để giải thích một số hiện tượng thực tiễn (ví dụ: tiêu diệt muỗi ở giai đoạn ấu trùng, phòng trừ sâu bệnh, chăn nuôi)."],"sum":["Sinh trưởng và phát triển ở sinh vật chịu tác động của các nhân tố như nhiệt độ, ánh sáng, nước, chất dinh dưỡng và một số chất kích thích hoặc ức chế do cơ thể tiết ra.","Khái niệm: Sinh trưởng và phát triển ở sinh vật chịu tác động của các nhân tố như nhiệt độ, ánh sáng, nước, chất dinh dưỡng và một số chất kích thích hoặc ức…","Nhiệt độ: Mỗi loài sinh trưởng tốt trong khoảng nhiệt độ thích hợp.","Ánh sáng ảnh hưởng đến sinh trưởng…: Ánh sáng ảnh hưởng đến sinh trưởng, phát triển và thời gian ra hoa của thực vật;","Nước và chất dinh dưỡng: Nước là nguyên liệu của quang hợp và tham gia trao đổi chất; thiếu nitrogen và các nguyên tố khoáng làm sinh trưởng bị ức chế, còn thừa chất dinh…","Con người điều khiển sinh trưởng và…: Con người điều khiển sinh trưởng và phát triển bằng các biện pháp như chiếu sáng nhân tạo, bón phân, tưới nước hợp lí, ủ rơm chống rét; và bằng…"],"e":["Hay nhầm: Nhiệt độ quá cao làm chậm sinh trưởng và phát triển.","Hay nhầm: Thiếu nước làm sinh trưởng bị ảnh hưởng.","Hay nhầm: Thiếu ánh sáng ảnh hưởng đến thực vật.","Hay nhầm: Vitamin C không được tổng hợp nhờ ánh sáng mặt trời.","Hay nhầm: Glucose được tổng hợp trong quang hợp, không phải ở động vật nhờ ánh sáng trực tiếp.","Hay nhầm: Nước không được tổng hợp nhờ ánh sáng mặt trời."],"q":{"n":8,"lv":{"Biết":4,"Hiểu":2,"Vận dụng":2}}},{"t":"Bài 38. Thực hành: Quan sát, mô tả sự sinh trưởng và phát triển ở một số sinh vật","req":["Thực hành quan sát và mô tả được sự sinh trưởng, phát triển ở một số thực vật, động vật.","Tiến hành được thí nghiệm chứng minh cây có sự sinh trưởng."],"sum":["Thí nghiệm chứng minh cây có sinh trưởng: ngâm hạt trong nước ấm 35 °C đến 40 °C khoảng 5 đến 10 giờ, rồi gieo vào chậu/khay có đất.","Thí nghiệm chứng minh cây có sinh trưởng: Ngâm hạt trong nước ấm 35 °C đến 40 °C khoảng 5 đến 10 giờ, rồi gieo vào chậu/khay có đất.","Ghi số liệu hằng ngày (trong khoảng 5 đến 7 ngày): Đếm số lá, đo chiều cao cây và kích thước lá.","Quan sát sinh trưởng và phát triển…: Quan sát sinh trưởng và phát triển ở động vật qua tranh ảnh hoặc video (bướm, muỗi, gà...).","Kết luận: Cây sinh trưởng làm tăng chiều cao, số lá và kích thước lá; sinh trưởng gắn liền với phát triển, qua các giai đoạn khác nhau trong vòng đời."],"e":["Hay nhầm: Nước lạnh không giúp hạt nảy mầm nhanh.","Hay nhầm: Nhiệt độ quá cao làm hỏng hạt.","Hay nhầm: Màu đất không cho biết sinh trưởng của cây.","Hay nhầm: Nhiệt độ phòng không trực tiếp chứng minh sinh trưởng.","Hay nhầm: Khối lượng chậu không phải chỉ số sinh trưởng của cây.","Hay nhầm: Gà con và gà trưởng thành là giai đoạn của gà."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương X. Sinh sản ở sinh vật","l":[{"t":"Bài 39. Sinh sản vô tính ở sinh vật","req":["Phát biểu được khái niệm sinh sản ở sinh vật.","Nêu được khái niệm sinh sản vô tính ở sinh vật.","Phân biệt được các hình thức sinh sản sinh dưỡng ở thực vật. Lấy được ví dụ minh hoạ."],"sum":["Sinh sản là một trong những đặc trưng cơ bản của cơ thể sống, là quá trình tạo ra những cá thể mới, đảm bảo sự phát triển liên tục của loài.","Khái niệm: Sinh sản là một trong những đặc trưng cơ bản của cơ thể sống, là quá trình tạo ra những cá thể mới, đảm bảo sự phát triển liên tục của loài.","Sinh sản vô tính là hình thức…: Sinh sản vô tính là hình thức sinh sản không có sự kết hợp của giao tử đực và giao tử cái; cơ thể con được tạo thành từ một phần của cơ thể mẹ.","Sinh sản sinh dưỡng ở thực vật…: Sinh sản sinh dưỡng ở thực vật là hình thức sinh sản trong đó cơ thể mới được hình thành từ cơ quan sinh dưỡng (rễ, thân, lá).","Sinh sản vô tính ở động vật: Nảy chồi (ví dụ thuỷ tức), phân mảnh (giun dẹp, sao biển), trinh sản (rệp cây, ong, kiến).","Ứng dụng sinh sản vô tính: Giâm cành, chiết cành, ghép cây, nuôi cấy tế bào và mô để nhân nhanh giống cây trồng, tạo giống sạch bệnh, khôi phục giống cây quý hiếm."],"e":["Hay nhầm: Đó là đặc điểm của sinh sản hữu tính.","Hay nhầm: Sinh sản vô tính có ở nhiều sinh vật.","Hay nhầm: Sinh sản vô tính tạo ra cá thể mới.","Hay nhầm: Trinh sản gặp ở rệp cây, ong, kiến.","Hay nhầm: Phân mảnh gặp ở giun dẹp và sao biển.","Hay nhầm: Thuỷ tức sinh sản vô tính, không phải hữu tính."],"q":{"n":8,"lv":{"Biết":4,"Hiểu":2,"Vận dụng":2}}},{"t":"Bài 40. Sinh sản hữu tính ở sinh vật","req":["Nêu được khái niệm sinh sản hữu tính ở sinh vật.","Phân biệt được sinh sản hữu tính và sinh sản vô tính.","Mô tả được các bộ phận của hoa lưỡng tính, phân biệt hoa đơn tính và hoa lưỡng tính."],"sum":["Sinh sản hữu tính là hình thức sinh sản tạo ra cơ thể mới qua sự hợp nhất giữa giao tử đực và giao tử cái tạo nên hợp tử; hợp tử phát triển thành cơ thể mới.","Khái niệm: Sinh sản hữu tính là hình thức sinh sản tạo ra cơ thể mới qua sự hợp nhất giữa giao tử đực và giao tử cái tạo nên hợp tử; hợp tử phát triển thành cơ…","Hoa lưỡng tính có cả nhị và…: Hoa lưỡng tính có cả nhị và nhuỵ; hoa đơn tính chỉ mang nhị hoặc nhuỵ.","Sinh sản hữu tính ở thực vật có hoa gồm các giai đoạn: Tạo giao tử, thụ phấn, thụ tinh, hình thành quả và hạt.","Hạt do noãn phát triển thành; quả…: Hạt do noãn phát triển thành; quả do bầu nhuỵ phát triển thành.","Sinh sản hữu tính ở động vật gồm ba giai đoạn: Hình thành giao tử, thụ tinh, phát triển phôi thành cơ thể mới."],"e":["Hay nhầm: Hoa chỉ có nhị là hoa đơn tính đực.","Hay nhầm: Hoa chỉ có nhuỵ là hoa đơn tính cái.","Hay nhầm: Hoa lưỡng tính có đủ nhị và nhuỵ.","Hay nhầm: Bầu nhuỵ chứa noãn mang giao tử cái.","Hay nhầm: Noãn nằm trong bầu nhuỵ, không chứa giao tử đực.","Hay nhầm: Đầu nhuỵ tiếp nhận hạt phấn, không chứa giao tử đực."],"q":{"n":8,"lv":{"Biết":4,"Hiểu":2,"Vận dụng":2}}},{"t":"Bài 41. Một số yếu tố ảnh hưởng và điều hoà, điều khiển sinh sản ở sinh vật","req":["Nêu được một số yếu tố ảnh hưởng đến sinh sản và điều hoà, điều khiển sinh sản ở sinh vật.","Vận dụng được những hiểu biết về sinh sản hữu tính trong thực tiễn đời sống và chăn nuôi (thụ phấn nhân tạo; điều khiển số con, giới tính). Giải thích tại sao phải bảo vệ một số loài côn trùng thụ phấn cho cây."],"sum":["Sinh sản ở sinh vật chịu ảnh hưởng của các yếu tố bên trong như đặc điểm di truyền, hormone, tuổi; và các yếu tố bên ngoài như ánh sáng, độ ẩm, nhiệt độ, chế độ dinh dưỡng.","Khái niệm: Sinh sản ở sinh vật chịu ảnh hưởng của các yếu tố bên trong như đặc điểm di truyền, hormone, tuổi; và các yếu tố bên ngoài như ánh sáng, độ ẩm,…","Ở thực vật, độ ẩm và nhiệt…: Ở thực vật, độ ẩm và nhiệt độ không khí quá cao hay quá thấp đều làm giảm hiệu quả thụ phấn và thụ tinh, làm tăng số lượng hạt lép.","Quá trình sinh sản của sinh vật…: Quá trình sinh sản của sinh vật được điều hoà chủ yếu bởi các hormone.","Trong trồng trọt, con người điều khiển…: Trong trồng trọt, con người điều khiển sinh sản ở thực vật bằng hormone, điều chỉnh nhiệt độ, chiếu sáng, dinh dưỡng; ví dụ thắp đèn chiếu sáng để…","Trong chăn nuôi, con người điều khiển…: Trong chăn nuôi, con người điều khiển số lượng và giới tính đàn con bằng hormone, thụ tinh nhân tạo, cấy phôi."],"e":["Hay nhầm: Insulin là hormone của động vật, không kích thích ra hoa.","Hay nhầm: Adrenalin là hormone động vật, không kích thích ra hoa.","Hay nhầm: Vitamin C không phải hormone kích thích ra hoa.","Hay nhầm: Nhiệt độ bất lợi không làm tăng sinh trứng.","Hay nhầm: Nhiệt độ có ảnh hưởng đến sinh sản.","Hay nhầm: Nhiệt độ không trực tiếp làm tăng khối lượng cơ thể trong bài."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 42. Cơ thể sinh vật là một thể thống nhất","req":["Dựa vào sơ đồ mối quan hệ giữa tế bào với cơ thể sinh vật và môi trường (tế bào – cơ thể – môi trường) và sơ đồ quan hệ giữa các hoạt động sống (trao đổi chất và chuyển hoá năng lượng – sinh trưởng, phát triển – cảm…"],"sum":["Mọi cơ thể sống đều được cấu tạo từ tế bào. Cơ thể lấy các chất dinh dưỡng, nước, chất khoáng và O₂ từ môi trường cung cấp cho tế bào thực hiện quá trình trao đổi chất để lớn lên, sinh sản và cảm…","Mọi cơ thể sống đều được cấu tạo từ tế bào: Cơ thể lấy các chất dinh dưỡng, nước, chất khoáng và O₂ từ môi trường cung cấp cho tế bào thực hiện quá trình trao đổi chất để lớn lên, sinh sản và…","Các hoạt động sống ở cấp độ…: Các hoạt động sống ở cấp độ tế bào là cơ sở cho các hoạt động sống ở cấp độ cơ thể.","Các hoạt động sống như trao đổi…: Các hoạt động sống như trao đổi chất và chuyển hoá năng lượng, sinh trưởng và phát triển, sinh sản và cảm ứng có mối quan hệ qua lại mật thiết với…","Nếu quá trình trao đổi chất và…: Nếu quá trình trao đổi chất và năng lượng gặp trục trặc (ví dụ thiếu năng lượng), các hoạt động sống khác như sinh trưởng, sinh sản và cảm ứng cũng…","Béo phì là bệnh lí do thu…: Béo phì là bệnh lí do thu nhận quá nhiều năng lượng từ thức ăn và đồ uống dẫn đến rối loạn quá trình trao đổi chất của tế bào và cơ thể."],"e":["Hay nhầm: Sinh sản tạo cá thể mới, không cung cấp năng lượng chính.","Hay nhầm: Cảm ứng là phản ứng với kích thích.","Hay nhầm: Vận động là một biểu hiện, không phải nguồn cung cấp năng lượng.","Hay nhầm: Các cơ quan phối hợp với nhau, không độc lập.","Hay nhầm: Cơ thể có nhiều hoạt động sống.","Hay nhầm: Mọi cơ thể sống đều được cấu tạo từ tế bào."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}}]}]}]},{"id":"anh","name":"Tiếng Anh","b":[{"t":"Tiếng Anh 7","c":[{"t":"Chủ điểm 1. Our Communities (Cộng đồng của chúng ta)","l":[{"t":"Unit 1. Hobbies (Sở thích)","req":["Nói và viết được về sở thích bằng thì hiện tại đơn.","Dùng đúng love / like / enjoy + V-ing.","Hiểu và dùng được các từ vựng chủ đề sở thích."],"sum":["Hiện tại đơn: he / she / it + V-s/es; sau does / doesn’t động từ về nguyên mẫu. Like / love / enjoy / hate + V-ing.","Hiện tại đơn: Nói về thói quen, sở thích và sự thật hiển nhiên. Với I, you, we, they động từ giữ nguyên; với he, she, it (và danh từ số ít) thêm -s hoặc -es.","Thêm -s / -es","Yêu thích + V-ing: Love, like, enjoy, hate, don’t mind, prefer thường theo sau bởi V-ing.","V-ing làm chủ ngữ: Cụm V-ing làm chủ ngữ được coi là số ít nên động từ thêm -s."],"e":["Sai: She doesn’t likes jogging. → Đúng: She doesn’t like jogging. (Đã có does / doesn’t thì động từ chính về nguyên mẫu.)","Sai: I enjoy to swim. → Đúng: I enjoy swimming. (Sau enjoy luôn là V-ing, không dùng to V.)","Hay nhầm: Không có trợ động từ nên không dùng V-ing để diễn tả thói quen.","Hay nhầm: Gone là quá khứ phân từ, không dùng ở thì hiện tại đơn.","Hay nhầm: Sau enjoy không dùng động từ nguyên mẫu.","Hay nhầm: Sau enjoy không dùng to V."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Unit 2. Healthy living (Lối sống lành mạnh)","req":["Dùng đúng câu đơn và câu ghép với and, but, or, so.","Nói và viết về thói quen giữ sức khoẻ.","Dùng được từ vựng về sức khoẻ, da và dinh dưỡng."],"sum":["Câu đơn: 1 chủ ngữ + 1 động từ. Câu ghép: 2 câu đơn nối bằng , and / but / or / so.","Câu đơn: Có một chủ ngữ và một động từ chính, diễn tả một ý trọn vẹn.","Câu ghép: Gồm hai câu đơn nối bằng liên từ. Trước liên từ thường có dấu phẩy.","Bỏ dấu phẩy: Khi hai vế cùng chủ ngữ và rất ngắn có thể bỏ dấu phẩy.","Cụm từ sức khỏe"],"e":["Sai: I was tired, I went to bed. → Đúng: I was tired, so I went to bed. (Không dùng dấu phẩy thay cho liên từ.)","Hay nhầm: Câu này có but nối hai vế nên là câu ghép.","Hay nhầm: Câu này có and nối hai vế nên là câu ghép.","Hay nhầm: Câu này có so nối hai vế nên là câu ghép.","Hay nhầm: And dùng cho hai ý cùng chiều.","Hay nhầm: Sunscreen là kem chống nắng."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Unit 3. Community service (Hoạt động cộng đồng)","req":["Dùng đúng thì quá khứ đơn với động từ có quy tắc và bất quy tắc.","Kể lại được một hoạt động cộng đồng đã làm.","Dùng được từ vựng về hoạt động tình nguyện."],"sum":["Quá khứ đơn: V-ed / V2; phủ định, nghi vấn dùng did + V. Với be: was / were.","Quá khứ đơn: Diễn tả hành động đã xảy ra và kết thúc trong quá khứ. Hay đi với last week, yesterday, in 2023, two years ago, last summer.","Thêm -ed","Động từ bất quy tắc","Động từ be: Với be dùng was / were, không dùng did."],"e":["Sai: Did they went to the orphanage? → Đúng: Did they go to the orphanage? (Sau did động từ luôn về nguyên mẫu.)","Hay nhầm: Clean là hiện tại đơn, không hợp với last Sunday.","Hay nhầm: Cleaning cần trợ động từ và không phải quá khứ đơn.","Hay nhầm: Cleans là hiện tại đơn ngôi thứ ba.","Hay nhầm: Go không thêm -ed; quá khứ là went.","Hay nhầm: Go là hiện tại, không hợp với yesterday."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}}]},{"t":"Chủ điểm 2. Our Heritage (Di sản của chúng ta)","l":[{"t":"Unit 4. Music and arts (Âm nhạc và nghệ thuật)","req":["Dùng đúng so sánh bằng as … as và not as … as.","Dùng the same as, like, similar to, different from để so sánh.","Nói về sở thích âm nhạc, nghệ thuật với prefer … to …"],"sum":["So sánh bằng: as + adj/adv + as; phủ định not as … as. Giống: the same as, like, similar to. Khác: different from.","So sánh bằng: Dùng với tính từ hoặc trạng từ.","Giống và khác: Nói về sự giống nhau: the same as, like, similar to. Về sự khác nhau: different from.","Lưu ý: Sau as … as, like, the same as, different from dùng danh từ hoặc đại từ tân ngữ (me, him, her, us, them, mine, yours…).","Nói về sở thích"],"e":["Hay nhầm: More … than là so sánh hơn, không phải so sánh bằng.","Hay nhầm: The same as đi với danh từ, không đi với tính từ popular.","Hay nhầm: Không có cấu trúc so … than.","Hay nhầm: Different không đi với as.","Hay nhầm: Than dùng trong so sánh hơn.","Hay nhầm: Different with không đúng."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Unit 5. Food and drink (Đồ ăn và thức uống)","req":["Phân biệt danh từ đếm được và không đếm được.","Dùng đúng some, any, a lot of, lots of và How much / How many.","Nói và viết được một công thức nấu ăn đơn giản."],"sum":["Đếm được: a / an / many. Không đếm được: much, dùng đơn vị (a bottle of…). some khẳng định, any phủ định / nghi vấn. a lot of / lots of dùng cho cả hai.","Đếm được và không đếm được: Danh từ không đếm được không có dạng số nhiều.","Đơn vị đếm","How many / How much","Some, any, a lot of: Some dùng trong câu khẳng định và lời mời; any trong câu phủ định và câu hỏi. A lot of / lots of dùng cho cả hai loại danh từ."],"e":["Sai: I need a rice. → Đúng: I need some rice. / a bowl of rice. (Không dùng a / an với danh từ không đếm được.)","Hay nhầm: How much dùng với danh từ không đếm được.","Hay nhầm: How một mình không hỏi số lượng.","Hay nhầm: Không có cấu trúc What many.","Hay nhầm: How many dùng với danh từ đếm được.","Hay nhầm: Pancake đếm được: pancakes."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Unit 6. A visit to a school (Đến thăm trường)","req":["Dùng đúng at, on, in chỉ thời gian.","Dùng đúng giới từ chỉ nơi chốn và vị trí.","Giới thiệu được trường học của mình."],"sum":["Thời gian: at giờ, on thứ / ngày, in tháng / năm / mùa / buổi. Nơi chốn: in (trong), on (trên bề mặt), at (địa điểm cụ thể).","Giới từ chỉ thời gian","Giới từ chỉ nơi chốn","Giới từ vị trí khác","Lưu ý: Không dùng giới từ trước this, next, last, every. Có thứ thì dùng on."],"e":["Hay nhầm: In dùng với tháng, năm, buổi.","Hay nhầm: From không đi một mình với giờ bắt đầu trong câu này.","Hay nhầm: In dùng với tháng, năm, mùa.","Hay nhầm: Of không chỉ thời gian ở đây.","Hay nhầm: To không chỉ thời gian ở đây.","Hay nhầm: Gym là phòng tập thể dục."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}}]},{"t":"Chủ điểm 3. Our World (Thế giới của chúng ta)","l":[{"t":"Unit 7. Traffic (Giao thông)","req":["Hỏi và nói về khoảng cách với How far và It is …","Khuyên bảo với should / shouldn’t.","Dùng được từ vựng về giao thông và an toàn đường bộ."],"sum":["Hỏi khoảng cách: How far is it from A to B? – It is …. Lời khuyên: should / shouldn’t + V.","Khoảng cách với It: It ở đây không chỉ vật gì cụ thể.","Should / shouldn’t: Khuyên nên hay không nên làm gì. Dạng giống nhau cho mọi chủ ngữ, không thêm -s, sau đó là V nguyên mẫu.","Cụm giao thông"],"e":["Sai: There is 2 kilometres from my house to school. → Đúng: It is 2 kilometres from my house to school. (Khoảng cách dùng It is, không dùng There is.)","Hay nhầm: How much hỏi số lượng hoặc giá.","Hay nhầm: Shouldn’t là không nên, trái nghĩa.","Hay nhầm: Don’t không dùng để khuyên như vậy.","Hay nhầm: Aren’t không đi với động từ wear.","Hay nhầm: Cyclist là người đi xe đạp."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Unit 8. Films (Điện ảnh)","req":["Dùng đúng although / though và However để diễn tả sự tương phản.","Phân biệt tính từ -ed và -ing.","Nhận xét được về một bộ phim."],"sum":["although / though + mệnh đề: mặc dù (không dùng but). However, đứng đầu câu sau. Tính từ -ing mô tả sự vật, -ed mô tả cảm xúc người.","Although / though: Although có thể đứng đầu câu (có dấu phẩy ở giữa) hoặc giữa câu.","However: Đứng đầu câu thứ hai, sau nó có dấu phẩy.","Tính từ -ing và -ed","Từ nhận xét phim"],"e":["Sai: Although the film was long, but I enjoyed it. → Đúng: Although the film was long, I enjoyed it. (Không dùng but cùng lúc với although.)","Hay nhầm: However không đứng đầu mệnh đề phụ như vậy, và cần dấu chấm trước nó.","Hay nhầm: But không đứng đầu câu kiểu này với dấu phẩy ở giữa hai vế theo cấu trúc bài.","Hay nhầm: Because chỉ nguyên nhân, sai nghĩa.","Hay nhầm: Although cần đi với một mệnh đề trong cùng câu.","Hay nhầm: Though ở đầu câu cũng cần mệnh đề đi kèm trong cùng câu."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Unit 9. Festivals around the world (Các lễ hội trên thế giới)","req":["Đặt và trả lời câu hỏi Yes/No và Wh- ở hiện tại đơn và quá khứ đơn.","Dùng trạng từ tần suất đúng vị trí.","Giới thiệu được một lễ hội."],"sum":["Yes/No: Do / Does / Did / Be + S …? Wh-: Wh- + trợ động từ + S + V?. Who làm chủ ngữ không cần trợ động từ.","Câu hỏi Yes/No: Bắt đầu bằng trợ động từ hoặc be. Trả lời ngắn: Yes, I do. / No, she didn’t. / Yes, it is.","Câu hỏi Wh-: Đặt từ để hỏi trước trợ động từ.","Who và Which: Who làm chủ ngữ thì không cần trợ động từ. Which + danh từ.","Trạng từ tần suất: Đứng trước động từ thường và sau be."],"e":["Sai: Who does make the lanterns? → Đúng: Who makes the lanterns? (Who làm chủ ngữ không cần does.)","Hay nhầm: Does dùng cho he / she / it.","Hay nhầm: Are không đi với động từ like.","Hay nhầm: Did là quá khứ, nhưng trả lời ở hiện tại (do).","Hay nhầm: Sau does động từ không thêm -s.","Hay nhầm: The festival là số ít nên dùng does."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}}]},{"t":"Chủ điểm 4. Visions of the Future (Tầm nhìn tương lai)","l":[{"t":"Unit 10. Energy sources (Các nguồn năng lượng)","req":["Dùng đúng thì hiện tại tiếp diễn và phân biệt với hiện tại đơn.","Nói về các nguồn năng lượng tái tạo và không tái tạo.","Đưa ra cách tiết kiệm năng lượng."],"sum":["Hiện tại tiếp diễn: am / is / are + V-ing, việc đang diễn ra hoặc thay đổi đang xảy ra. Hiện tại đơn: thói quen, sự thật.","Hiện tại tiếp diễn: Diễn tả hành động đang xảy ra ngay lúc nói hoặc quanh thời điểm nói, và những thay đổi đang diễn ra. Dấu hiệu: now, at the moment, at present,…","Thêm -ing","Phân biệt với hiện tại đơn","Từ vựng năng lượng"],"e":["Sai: I am needing more energy. → Đúng: I need more energy. (Động từ trạng thái (know, like, want, need, believe, understand) không dùng tiếp diễn.)","Hay nhầm: Shines là hiện tại đơn, không hợp với Look!.","Hay nhầm: Shine không chia với chủ ngữ the sun.","Hay nhầm: Sự thật hiển nhiên không dùng tiếp diễn.","Hay nhầm: Mặt trời là nguồn tái tạo.","Hay nhầm: Thuỷ điện là nguồn tái tạo."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Unit 11. Travelling in the future (Đi lại trong tương lai)","req":["Dùng đúng thì tương lai đơn với will / won’t.","Dùng đúng đại từ sở hữu.","Dự đoán và nói về phương tiện đi lại trong tương lai."],"sum":["Tương lai đơn: will + V. Đại từ sở hữu: my → mine, your → yours, her → hers, our → ours, their → theirs; không có danh từ theo sau.","Tương lai đơn: Diễn tả dự đoán hoặc quyết định tức thời. Dạng giống nhau cho mọi chủ ngữ. Dấu hiệu: in the future, in 2050, tomorrow, next year, soon, I think…","Đại từ sở hữu: Thay cho tính từ sở hữu + danh từ để tránh lặp từ.","Từ vựng phương tiện"],"e":["Sai: She will flies to school. → Đúng: She will fly to school. (Sau will là V nguyên mẫu. Rút gọn: I’ll, you’ll, he’ll, we’ll, they’ll; will not = won’t.)","Sai: This is mine bike. → Đúng: This is my bike. / This bike is mine. (Sau đại từ sở hữu không có danh từ.)","Hay nhầm: My cần có danh từ đi sau.","Hay nhầm: Solar car là xe năng lượng mặt trời.","Hay nhầm: Eco car không phải thuật ngữ trong bài.","Hay nhầm: Are không đi với động từ fly như vậy."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Unit 12. English-speaking countries (Các quốc gia nói tiếng Anh)","req":["Dùng đúng mạo từ a, an, the và biết khi nào không dùng mạo từ.","Nói về các nước nói tiếng Anh và nét văn hoá của họ.","Viết được một bưu thiếp ngắn."],"sum":["a / an: nhắc lần đầu. the: đã biết, duy nhất, so sánh nhất, sông biển, nước số nhiều / có Kingdom, States. Không mạo từ: tên người, hầu hết tên nước và thành phố, ngôn ngữ, bữa ăn.","A / an: Dùng với danh từ đếm được số ít khi nhắc đến lần đầu hoặc nói chung. A trước âm phụ âm, an trước âm nguyên âm.","The: Dùng khi cả người nói và người nghe đều biết đang nói đến cái gì.","Không dùng mạo từ (zero article): Với tên người, tên hầu hết các nước và thành phố, ngôn ngữ, bữa ăn, danh từ số nhiều hoặc không đếm được nói chung.","Hay nhầm"],"e":["Sai: I live in the Canada. → Đúng: I live in Canada. (Hầu hết tên nước không có the.)","Hay nhầm: Thủ đô của một nước là duy nhất, không dùng a.","Hay nhầm: Capital bắt đầu bằng phụ âm và là danh từ xác định.","Hay nhầm: Nhắc lần đầu, chưa xác định, không dùng the.","Hay nhầm: Danh từ đếm được số ít cần mạo từ.","Hay nhầm: Không dùng the với Australia và English."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}}]}]}]},{"id":"lichsu","name":"Lịch sử","b":[{"t":"Lịch sử 7","c":[{"t":"Chương 1. Tây Âu từ thế kỉ V đến nửa đầu thế kỉ XVI","l":[{"t":"Bài 1. Quá trình hình thành và phát triển của chế độ phong kiến ở Tây Âu","req":["Kể lại được những sự kiện chủ yếu về quá trình hình thành xã hội phong kiến ở Tây Âu.","Trình bày được đặc điểm của lãnh địa phong kiến và quan hệ xã hội của chế độ phong kiến Tây Âu.","Mô tả sơ lược sự ra đời của Thiên Chúa giáo; phân tích vai trò của thành thị trung đại."],"sum":["Cuối thế kỉ V, Đế quốc Tây La Mã khủng hoảng và bị các tộc người Giéc-man tràn xuống xâm chiếm.","Khái niệm: Cuối thế kỉ V, Đế quốc Tây La Mã khủng hoảng và bị các tộc người Giéc-man tràn xuống xâm chiếm.","Từ khoá cần ghi nhớ: Chế độ phong kiến;","Mốc sự kiện cần nhớ: Cuối thế kỉ V: Đế quốc Tây La Mã khủng hoảng, bị người Giéc-man xâm chiếm","Quý tộc Giéc-man chiếm ruộng đất của…: Quý tộc Giéc-man chiếm ruộng đất của chủ nô La Mã, được phong tước vị và trở thành lãnh chúa phong kiến; quý tộc La Mã quy thuận cũng được giữ ruộng…","Sau khi Sác-lơ-ma-nhơ mất, Vương quốc Phơ-răng…: Sau khi Sác-lơ-ma-nhơ mất, Vương quốc Phơ-răng bị chia thành ba nước, về sau trở thành Pháp, Đức, I-ta-li-a."],"e":["Hay nhầm: Họ bị mất ruộng đất và trở thành nông nô, không phải lãnh chúa.","Hay nhầm: Họ trở thành nông nô chứ không nắm ruộng đất như lãnh chúa.","Hay nhầm: Họ là thị dân ở thành thị, xuất hiện muộn hơn.","Hay nhầm: Quý tộc Giéc-man trở thành lãnh chúa.","Hay nhầm: Thương nhân thuộc tầng lớp thị dân ở thành thị.","Hay nhầm: Giáo sĩ không phải là nguồn gốc của nông nô."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":4,"Vận dụng":1}}},{"t":"Bài 2. Các cuộc phát kiến địa lí và sự hình thành quan hệ sản xuất tư bản chủ nghĩa ở Tây Âu","req":["Giới thiệu được hành trình của một số cuộc phát kiến địa lí lớn.","Nêu được hệ quả của các cuộc phát kiến địa lí.","Trình bày được sự nảy sinh chủ nghĩa tư bản và những biến đổi chính trong xã hội Tây Âu."],"sum":["Cuối thế kỉ XV – đầu thế kỉ XVI, người châu Âu thực hiện nhiều chuyến đi biển dài ngày để tìm đường sang phương Đông và tìm vàng bạc, hương liệu.","Khái niệm: Cuối thế kỉ XV – đầu thế kỉ XVI, người châu Âu thực hiện nhiều chuyến đi biển dài ngày để tìm đường sang phương Đông và tìm vàng bạc, hương liệu.","Từ khoá cần ghi nhớ: Phát kiến địa lí; hệ quả; thương mại thế giới; buôn bán nô lệ; tích luỹ tư bản.","Mốc sự kiện cần nhớ: Cuối thế kỉ XV – đầu thế kỉ XVI: các cuộc phát kiến địa lí","Hệ quả: Tìm ra những vùng đất, con đường biển mới; thúc đẩy thương mại thế giới; nhưng cũng làm nảy sinh nạn cướp bóc thuộc địa và buôn bán nô lệ da đen.","Giai cấp tư sản tích luỹ vốn…: Giai cấp tư sản tích luỹ vốn bằng cướp bóc của cải, tài nguyên ở thuộc địa; tước đoạt ruộng đất của nông dân (\"rào đất cướp ruộng\"); buôn bán nô lệ…"],"e":["Hay nhầm: Cô-lôm-bô tìm ra châu Mỹ năm 1492.","Hay nhầm: Ga-ma cập bến Ca-li-cút năm 1497.","Hay nhầm: Đoàn của Ma-gien-lăng đi vòng quanh thế giới giai đoạn 1519 – 1522.","Hay nhầm: Năm 1487 là Đi-a-xơ đến mũi Hảo Vọng.","Hay nhầm: Năm 1497 là Ga-ma đến Ấn Độ.","Hay nhầm: Năm 1519 là Ma-gien-lăng bắt đầu chuyến vòng quanh thế giới."],"q":{"n":7,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":1}}},{"t":"Bài 3. Phong trào Văn hoá Phục hưng và Cải cách tôn giáo","req":["Giới thiệu được biến đổi kinh tế – xã hội Tây Âu từ thế kỉ XII đến thế kỉ XVI.","Trình bày được thành tựu tiêu biểu, ý nghĩa của Văn hoá Phục hưng.","Nêu được nguyên nhân, nội dung cơ bản và tác động của Cải cách tôn giáo."],"sum":["Kinh tế tư bản chủ nghĩa nảy sinh, giai cấp tư sản có thế lực kinh tế nhưng chưa có địa vị xã hội tương xứng.","Khái niệm: Kinh tế tư bản chủ nghĩa nảy sinh, giai cấp tư sản có thế lực kinh tế nhưng chưa có địa vị xã hội tương xứng.","Từ khoá cần ghi nhớ: Văn hoá Phục hưng; cải cách tôn giáo; nhân văn; tư sản;","Mốc sự kiện cần nhớ: Phục hưng đề cao con người, tự do cá nhân và khoa học – kĩ thuật","Thành tựu Văn hoá Phục hưng: Văn học có Xéc-van-tét (Đôn Ki-hô-tê), Sếch-xpia (Rô-mê-ô và Giu-li-ét, Hăm-lét); hội hoạ, điêu khắc có Lê-ô-na đơ Vanh-xi (Bữa tiệc cuối cùng, Nàng…","Ý nghĩa: Lên án Giáo hội và trật tự phong kiến lỗi thời;"],"e":["Hay nhầm: Sếch-xpia là nhà viết kịch người Anh.","Hay nhầm: Ông là hoạ sĩ, nhà khoa học người I-ta-li-a.","Hay nhầm: Ông là hoạ sĩ, nhà điêu khắc người I-ta-li-a.","Hay nhầm: Ông là nhà văn Tây Ban Nha.","Hay nhầm: Ông là nhà thiên văn học người Ba Lan.","Hay nhầm: Bru-nô bảo vệ và truyền bá quan điểm khoa học tiến bộ."],"q":{"n":7,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":1}}}]},{"t":"Chương 2. Trung Quốc và Ấn Độ thời trung đại","l":[{"t":"Bài 4. Trung Quốc từ thế kỉ VII đến giữa thế kỉ XIX","req":["Trình bày được sơ lược sự thay đổi các triều đại phong kiến Trung Quốc.","Nêu được những thành tựu tiêu biểu về chính trị, kinh tế, văn hoá, khoa học – kĩ thuật."],"sum":["Chế độ phong kiến Trung Quốc kéo dài hơn hai nghìn năm, trải qua nhiều triều đại.","Khái niệm: Chế độ phong kiến Trung Quốc kéo dài hơn hai nghìn năm, trải qua nhiều triều đại.","Từ khoá cần ghi nhớ: Nhà Đường; nhà Tống; nhà Nguyên; nhà Minh; kinh tế hàng hoá; thơ Đường.","Mốc sự kiện cần nhớ: Nhà Đường 618–907; nhà Tống 960–1279; nhà Nguyên bị đánh đổ năm 1368; nhà Minh 1368–1644","Dưới thời Đường (618 – 907), Trung Quốc cường thịnh: Kinh tế phát triển, văn hoá rực rỡ (thơ Đường), mở rộng lãnh thổ.","Thành tựu nổi bật: Bốn phát minh lớn về kĩ thuật là giấy, kĩ thuật in, la bàn, thuốc súng; thơ Đường; các công trình như Vạn Lí Trường Thành, Cố Cung; các bộ tiểu…"],"e":["Hay nhầm: Nhà Minh kết thúc năm 1644.","Hay nhầm: Nhà Nguyên bị lật đổ năm 1368.","Hay nhầm: Nhà Tống kết thúc năm 1279.","Hay nhầm: Nhà Đường do người Hán lập.","Hay nhầm: Nhà Minh khôi phục quyền của người Hán.","Hay nhầm: Nhà Tống do người Hán lập."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":1}}},{"t":"Bài 5. Ấn Độ từ thế kỉ IV đến giữa thế kỉ XIX","req":["Trình bày được sơ lược các vương triều lớn ở Ấn Độ thời phong kiến.","Nêu được những thành tựu văn hoá tiêu biểu và ảnh hưởng của Ấn Độ."],"sum":["Đầu thế kỉ IV, vương triều Gúp-ta thống nhất miền Bắc Ấn Độ, kinh tế, văn hoá phát triển rực rỡ (thời hoàng kim).","Khái niệm: Đầu thế kỉ IV, vương triều Gúp-ta thống nhất miền Bắc Ấn Độ, kinh tế, văn hoá phát triển rực rỡ (thời hoàng kim).","Từ khoá cần ghi nhớ: Gúp-ta;","Mốc sự kiện cần nhớ: Đầu thế kỉ IV: Gúp-ta thống nhất miền Bắc; năm 1206: vương triều Đê-li;","Thành tựu văn hoá: Chữ Phạn, các bộ sử thi, hệ thống chữ số (chữ số Ấn Độ), toán học (số 0), thiên văn, y học; kiến trúc Phật giáo, Hin-đu giáo và Hồi giáo (Taj Mahal).","Ấn Độ là cái nôi của Phật…: Ấn Độ là cái nôi của Phật giáo và Hin-đu giáo; văn hoá Ấn Độ có ảnh hưởng sâu rộng đến Đông Nam Á."],"e":["Hay nhầm: Đê-li là vương triều Hồi giáo thành lập năm 1206.","Hay nhầm: Mô-gôn thành lập vào đầu thế kỉ XVI.","Hay nhầm: Đây không phải vương triều được nhắc trong bài.","Hay nhầm: Đây là mốc ra đời của Mô-gôn theo cách tính thông dụng.","Hay nhầm: Đây không phải thời điểm lập vương triều Đê-li.","Hay nhầm: Đây là thời kì cuối, khi Anh xâm chiếm."],"q":{"n":5,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":1}}}]},{"t":"Chương 3. Đông Nam Á từ nửa sau thế kỉ X đến nửa đầu thế kỉ XVI","l":[{"t":"Bài 6. Các vương quốc phong kiến Đông Nam Á từ nửa sau thế kỉ X đến nửa đầu thế kỉ XVI","req":["Mô tả được quá trình hình thành, phát triển ban đầu của các quốc gia Đông Nam Á từ nửa sau thế kỉ X đến nửa đầu thế kỉ XVI.","Giới thiệu và nhận xét được thành tựu văn hoá tiêu biểu của Đông Nam Á thời kì này."],"sum":["Từ nửa sau thế kỉ X đến thế kỉ XII, các vương quốc phong kiến Đông Nam Á bước vào giai đoạn phát triển trên cơ sở các vương quốc đã hình thành từ thế kỉ VII – X.","Khái niệm: Từ nửa sau thế kỉ X đến thế kỉ XII, các vương quốc phong kiến Đông Nam Á bước vào giai đoạn phát triển trên cơ sở các vương quốc đã hình thành từ…","Từ khoá cần ghi nhớ: Vương quốc phong kiến Đông Nam Á;","Mốc sự kiện cần nhớ: Thế kỉ XIII: quân Mông – Nguyên xâm lược Đông Nam Á; nhu cầu chống ngoại xâm dẫn đến thống nhất các vương quốc lớn","Thế kỉ XIII, quân Mông – Nguyên xâm lược xuống Đông Nam Á: Nhu cầu liên kết chống ngoại xâm đã dẫn đến sự thống nhất của một số vương quốc lớn hơn, như Vương triều Mô-giô-pa-hít (đảo Gia-va, In-đô-nê-xi-a).","Văn hoá: Phật giáo được truyền bá rộng ở Lan Xang, Cam-pu-chia...;"],"e":["Hay nhầm: Đây là lưu vực của Vương quốc Ha-ri-pun-giay-a.","Hay nhầm: Đây không phải là sông gắn với Pa-gan.","Hay nhầm: Gia-va là nơi phát triển Vương triều Mô-giô-pa-hít.","Hay nhầm: Đây không phải đảo của Sri Vi-giay-a.","Hay nhầm: Đây không phải đảo của Sri Vi-giay-a.","Hay nhầm: Pháp xâm lược muộn hơn rất nhiều."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":1}}},{"t":"Bài 7. Vương quốc Lào","req":["Mô tả được quá trình hình thành và phát triển của Vương quốc Lào.","Nhận biết sự phát triển của Vương quốc Lào thời Lan Xang và nét tiêu biểu về văn hoá."],"sum":["Chủ nhân đầu tiên của đất Lào là người Lào Thơng. Đến thế kỉ XIII, một nhóm nói tiếng Thái (Lào Lùm) di cư đến và sống hoà hợp, hợp thành người Lào.","Chủ nhân đầu tiên của đất Lào là người Lào Thơng: Đến thế kỉ XIII, một nhóm nói tiếng Thái (Lào Lùm) di cư đến và sống hoà hợp, hợp thành người Lào.","Từ khoá cần ghi nhớ: Lào Thơng;","Mốc sự kiện cần nhớ: Năm 1353: Pha Ngừm thống nhất các mường, lập nước Lan Xang","Năm 1353, Pha Ngừm thống nhất các…: Năm 1353, Pha Ngừm thống nhất các mường, lên ngôi vua, đặt tên nước là Lan Xang (Triệu Voi).","Bộ máy: Chia 7 mường;"],"e":["Hay nhầm: Đây là mốc của Cam-pu-chia.","Hay nhầm: Đây là sự kiện của Việt Nam.","Hay nhầm: Đây là sự kiện của Đại Việt.","Hay nhầm: Đây không phải nghĩa của Lan Xang.","Hay nhầm: Đây là hiệu của Đinh Bộ Lĩnh.","Hay nhầm: Đây không phải nghĩa đúng."],"q":{"n":5,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":1}}},{"t":"Bài 8. Vương quốc Cam-pu-chia","req":["Mô tả được quá trình hình thành và phát triển của Vương quốc Cam-pu-chia.","Nhận biết sự phát triển thời Ăng-co và một số nét tiêu biểu về văn hoá."],"sum":["Năm 802, vua Giay-a-vác-man II thống nhất lãnh thổ, đặt tên nước là Cam-pu-chia. Từ thế kỉ IX đến thế kỉ XV là thời kì Ăng-co, rực rỡ nhất.","Khái niệm: Năm 802, vua Giay-a-vác-man II thống nhất lãnh thổ, đặt tên nước là Cam-pu-chia.","Từ khoá cần ghi nhớ: Cam-pu-chia;","Mốc sự kiện cần nhớ: Năm 802: vua Giay-a-vác-man II đặt tên nước Cam-pu-chia; thế kỉ IX–XV: thời kì Ăng-co","Đến thế kỉ XV, do tranh giành…: Đến thế kỉ XV, do tranh giành quyền lực và sự tấn công của người Thái, Cam-pu-chia suy yếu; người Khơ-me chuyển kinh đô về phía nam Biển Hồ (Phnôm…","Thời Ăng-co: Đất nước thống nhất, ổn định; nông nghiệp phát triển nhờ thuỷ lợi (các hồ Ba-ray Tây, Ba-ray Đông); mở rộng quyền lực sang hạ lưu sông Chao Phray-a,…"],"e":["Hay nhầm: Pha Ngừm lập Lan Xang năm 1353.","Hay nhầm: Ngô Quyền là vua Việt Nam.","Hay nhầm: Đây là vương quốc ở Xu-ma-tra.","Hay nhầm: Đây là vương quốc của Mi-an-ma.","Hay nhầm: Đây không phải nguyên nhân.","Hay nhầm: Đây là sự kiện thế kỉ XIII và không phải nguyên nhân chính."],"q":{"n":5,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":1}}}]},{"t":"Chương 4. Đất nước dưới thời các vương triều Ngô – Đinh – Tiền Lê (939 – 1009)","l":[{"t":"Bài 9. Đất nước buổi đầu độc lập (939 – 967)","req":["Nêu được những nét chính về tổ chức chính quyền, đời sống xã hội và văn hoá thời Ngô Quyền.","Trình bày được công cuộc thống nhất đất nước của Đinh Bộ Lĩnh và sự thành lập nhà Đinh."],"sum":["Năm 939, sau chiến thắng Bạch Đằng, Ngô Quyền bỏ chức tiết độ sứ, xưng vương, đóng đô ở Cổ Loa.","Khái niệm: Năm 939, sau chiến thắng Bạch Đằng, Ngô Quyền bỏ chức tiết độ sứ, xưng vương, đóng đô ở Cổ Loa.","Từ khoá cần ghi nhớ: Ngô Quyền;","Mốc sự kiện cần nhớ: Năm 939: Ngô Quyền xưng vương; năm 944: Ngô Quyền mất, đất nước rơi vào cát cứ 12 sứ quân","Năm 944, Ngô Quyền mất, chính quyền…: Năm 944, Ngô Quyền mất, chính quyền suy yếu, các thế lực hào trưởng nổi lên, đất nước rơi vào cát cứ 12 sứ quân.","Tại Hoa Lư (Ninh Bình), Đinh Bộ…: Tại Hoa Lư (Ninh Bình), Đinh Bộ Lĩnh (được tôn là Vạn Thắng Vương) trong các năm 966 – 967 dẹp yên các sứ quân, thống nhất đất nước, sau đó lập ra…"],"e":["Hay nhầm: Hoa Lư là kinh đô thời Đinh – Tiền Lê.","Hay nhầm: Thăng Long là kinh đô từ thời Lý (1010).","Hay nhầm: Đây không phải tình trạng được nêu.","Hay nhầm: Lê Hoàn chỉ huy kháng chiến chống Tống năm 981.","Hay nhầm: Cổ Loa là kinh đô của Ngô Quyền.","Hay nhầm: Lam Sơn là quê hương Lê Lợi."],"q":{"n":5,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":1}}},{"t":"Bài 10. Đại Cồ Việt thời Đinh và Tiền Lê (968 – 1009)","req":["Giới thiệu những nét chính về tổ chức chính quyền thời Đinh – Tiền Lê.","Mô tả được cuộc kháng chiến chống Tống năm 981 của Lê Hoàn.","Nhận biết được đời sống xã hội, văn hoá thời Đinh – Tiền Lê."],"sum":["Sau khi thống nhất đất nước, Đinh Bộ Lĩnh lên ngôi Hoàng đế (Đinh Tiên Hoàng), đặt tên nước là Đại Cồ Việt, niên hiệu Thái Bình, đóng đô ở Hoa Lư.","Khái niệm: Sau khi thống nhất đất nước, Đinh Bộ Lĩnh lên ngôi Hoàng đế (Đinh Tiên Hoàng), đặt tên nước là Đại Cồ Việt, niên hiệu Thái Bình, đóng đô ở Hoa Lư.","Từ khoá cần ghi nhớ: Đinh Bộ Lĩnh;","Mốc sự kiện cần nhớ: Năm 968: Đinh Bộ Lĩnh lập nước Đại Cồ Việt; cuối năm 979: Đinh Tiên Hoàng bị ám sát","Cuối năm 979, Đinh Tiên Hoàng và con trưởng bị ám sát: Đinh Toàn mới 6 tuổi nối ngôi.","Đầu năm 981, quân Tống tiến đánh: Lê Hoàn trực tiếp lãnh đạo, quân Tống đại bại."],"e":["Hay nhầm: Tên này dùng từ thời Lý (1054).","Hay nhầm: Đây là tên nước của Lý Nam Đế.","Hay nhầm: Đây là kinh đô từ năm 1010.","Hay nhầm: Đây là kinh đô thời Nguyễn.","Hay nhầm: Đây là năm chiến thắng Bạch Đằng của Ngô Quyền.","Hay nhầm: Đây là năm kết thúc kháng chiến chống Tống thời Lý."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":1}}}]},{"t":"Chương 5. Đại Việt thời Lý – Trần – Hồ (1009 – 1407)","l":[{"t":"Bài 11. Nhà Lý xây dựng và phát triển đất nước (1009 – 1225)","req":["Trình bày những nét chính về sự thành lập nhà Lý và ý nghĩa việc dời đô ra Đại La.","Mô tả những nét chính về chính trị, kinh tế, xã hội, văn hoá, giáo dục thời Lý."],"sum":["Cuối năm 1009, Lê Long Đĩnh mất; sư sãi và đại thần tôn Lý Công Uẩn lên ngôi, nhà Lý thành lập.","Khái niệm: Cuối năm 1009, Lê Long Đĩnh mất; sư sãi và đại thần tôn Lý Công Uẩn lên ngôi, nhà Lý thành lập.","Từ khoá cần ghi nhớ: Nhà Lý;","Mốc sự kiện cần nhớ: Năm 1010: dời đô về Thăng Long; năm 1054: đổi tên nước là Đại Việt","Nhà Lý ban hành Hình thư, bộ…: Nhà Lý ban hành Hình thư, bộ luật thành văn đầu tiên của nước ta; quân đội có cấm quân và quân địa phương, thi hành chính sách \"ngụ binh ư nông\".","Kinh tế: Khuyến khích nông nghiệp (cày tịch điền, bảo vệ trâu bò, đào kênh mương); thủ công nghiệp nhà nước và nhân dân; thương nghiệp phát triển, cảng Vân…"],"e":["Hay nhầm: Đây là năm nhà Lý thành lập.","Hay nhầm: Đây là năm đổi tên nước thành Đại Việt.","Hay nhầm: Đây là năm lập Quốc Tử Giám.","Hay nhầm: Đây là tên nước thời Đinh – Tiền Lê.","Hay nhầm: Đây là tên nước thời Lý Nam Đế.","Hay nhầm: Bộ luật này được ban hành sau thời Lý."],"q":{"n":7,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":1}}},{"t":"Bài 12. Cuộc kháng chiến chống quân xâm lược Tống (1075 – 1077)","req":["Đánh giá những nét độc đáo của cuộc kháng chiến chống Tống (1075 – 1077).","Đánh giá vai trò của Lý Thường Kiệt."],"sum":["Giữa thế kỉ XI, nhà Tống âm mưu xâm lược Đại Việt. Vua Lý cử Lý Thường Kiệt làm Tổng chỉ huy.","Giữa thế kỉ XI, nhà Tống âm mưu xâm lược Đại Việt: Vua Lý cử Lý Thường Kiệt làm Tổng chỉ huy.","Từ khoá cần ghi nhớ: Lý Thường Kiệt; nhà Tống; tiến công trước để tự vệ;","Mốc sự kiện cần nhớ: Tháng 10/1075: quân Đại Việt vào đất Tống; kháng chiến kết thúc năm 1077","Tháng 10 – 1075, hơn 10 vạn…: Tháng 10 – 1075, hơn 10 vạn quân thuỷ bộ vào đất Tống, chủ trương \"tiến công trước để tự vệ\"; sau 42 ngày hạ thành Ung Châu, huỷ kho lương, rồi chủ…","Năm 1077, quân Tống do Quách Quỳ…: Năm 1077, quân Tống do Quách Quỳ chỉ huy tiến vào, bị chặn trước phòng tuyến sông Như Nguyệt; thuỷ binh Tống bị chặn ở ven biển."],"e":["Hay nhầm: Ông chỉ huy kháng chiến thời Trần.","Hay nhầm: Ông chỉ huy kháng chiến năm 981.","Hay nhầm: Ông thắng quân Nam Hán năm 938.","Hay nhầm: Ông chủ trương chủ động đánh.","Hay nhầm: Đây không phải chủ trương năm 1075.","Hay nhầm: Đây là sông có phòng tuyến năm 1077."],"q":{"n":5,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":1}}},{"t":"Bài 13. Đại Việt thời Trần (1226 – 1400)","req":["Mô tả sự thành lập nhà Trần.","Trình bày những nét chính về chính trị, kinh tế, xã hội, văn hoá thời Trần."],"sum":["Cuối thế kỉ XII, nhà Lý suy yếu, họ Trần dần thâu tóm quyền hành. Tháng 1 – 1226, Lý Chiêu Hoàng nhường ngôi cho chồng là Trần Cảnh, nhà Trần thành lập.","Khái niệm: Cuối thế kỉ XII, nhà Lý suy yếu, họ Trần dần thâu tóm quyền hành.","Từ khoá cần ghi nhớ: Nhà Trần;","Mốc sự kiện cần nhớ: Tháng 1/1226: Trần Cảnh lên ngôi, nhà Trần thành lập","Chính trị: Tiếp tục củng cố quân chủ tập quyền, bộ máy hoàn thiện hơn thời Lý; tôn thất họ Trần nắm giữ vị trí trọng yếu, được lập thái ấp; quân đội gồm quân…","Kinh tế: Khai hoang, đắp đê, làm thuỷ lợi; thủ công nghiệp có làng nghề, phường nghề; buôn bán sôi động, cảng Vân Đồn, Hội Thống tấp nập."],"e":["Hay nhầm: Đây là năm nhà Lý thành lập.","Hay nhầm: Đây là năm nhà Hồ thành lập.","Hay nhầm: Đây là năm nhà Lê sơ thành lập.","Hay nhầm: Ông là vua thời kì thịnh trị.","Hay nhầm: Ông là vua đầu tiên nhà Trần.","Hay nhầm: Đây là hiệu của Lê Hữu Trác."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":1}}},{"t":"Bài 14. Ba lần kháng chiến chống quân xâm lược Mông – Nguyên","req":["Lập được sơ đồ diễn biến chính của ba lần kháng chiến chống Mông – Nguyên.","Phân tích nguyên nhân thắng lợi, ý nghĩa; đánh giá vai trò Trần Thủ Độ, Trần Quốc Tuấn, Trần Nhân Tông."],"sum":["Năm 1258: 3 vạn quân Mông Cổ vào Đại Việt. Nhà Trần dùng kế \"vườn không nhà trống\", rồi phản công ở Đông Bộ Đầu, đánh tan giặc sau chưa đầy một tháng.","Năm 1258: 3 vạn quân Mông Cổ vào Đại Việt.","Từ khoá cần ghi nhớ: Mông – Nguyên; vườn không nhà trống;","Mốc sự kiện cần nhớ: 1258: kháng chiến lần 1;","Năm 1285: Hơn 50 vạn quân Nguyên do Thoát Hoan chỉ huy.","Năm 1287 – 1288: Thoát Hoan đem 50 vạn quân tấn công lần ba."],"e":["Hay nhầm: Quân Trần rút lui chiến lược khi giặc mạnh.","Hay nhầm: Đây không phải kế sách chính.","Hay nhầm: Ông lãnh đạo giai đoạn đầu nhà Trần.","Hay nhầm: Ông chỉ huy trận Vân Đồn.","Hay nhầm: Đây là hội nghị các vương hầu.","Hay nhầm: Đây là sự kiện của khởi nghĩa Lam Sơn."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":1}}},{"t":"Bài 15. Nước Đại Ngu thời Hồ (1400 – 1407)","req":["Trình bày sự ra đời của nhà Hồ.","Giới thiệu nội dung chủ yếu và tác động của cải cách Hồ Quý Ly.","Mô tả kháng chiến chống Minh của nhà Hồ và giải thích nguyên nhân thất bại."],"sum":["Nửa sau thế kỉ XIV nhà Trần suy yếu, khởi nghĩa nông dân nổ ra nhiều nơi. Năm 1400, Hồ Quý Ly buộc vua Trần nhường ngôi, lập ra nhà Hồ, đặt tên nước là Đại Ngu.","Khái niệm: Nửa sau thế kỉ XIV nhà Trần suy yếu, khởi nghĩa nông dân nổ ra nhiều nơi.","Từ khoá cần ghi nhớ: Hồ Quý Ly;","Mốc sự kiện cần nhớ: Năm 1400: nhà Hồ thành lập, đặt tên nước Đại Ngu; năm 1406: nhà Minh xâm lược","Tác động: Tiến bộ, củng cố quyền lực trung ương, hạn chế thế lực quý tộc, phát triển kinh tế và văn hoá dân tộc; hạn chế: chưa triệt để, kết quả thực tế còn…","Năm 1406, nhà Minh lấy cớ Hồ…: Năm 1406, nhà Minh lấy cớ Hồ Quý Ly cướp ngôi, đem quân xâm lược."],"e":["Hay nhầm: Mục tiêu là hạn chế quý tộc.","Hay nhầm: Đây là tiền giấy thời Tống.","Hay nhầm: Đây là tiền giấy thời Tống.","Hay nhầm: Đây không phải tên tiền giấy nhà Hồ.","Hay nhầm: Quân Minh huy động lực lượng lớn.","Hay nhầm: Nhà Hồ chưa dựa vào chiến tranh nhân dân."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":1}}}]},{"t":"Chương 6. Khởi nghĩa Lam Sơn và Đại Việt thời Lê sơ (1418 – 1527)","l":[{"t":"Bài 16. Khởi nghĩa Lam Sơn (1418 – 1427)","req":["Trình bày một số sự kiện tiêu biểu của khởi nghĩa Lam Sơn.","Giải thích nguyên nhân thắng lợi; nêu ý nghĩa; đánh giá vai trò Lê Lợi, Nguyễn Trãi, Nguyễn Chích."],"sum":["Nhà Minh đặt Đại Ngu thành quận Giao Chỉ, áp bức, bóc lột nặng nề, huỷ diệt văn hoá. Nhiều cuộc khởi nghĩa (Trần Ngỗi, Trần Quý Khoáng) lần lượt thất bại.","Khái niệm: Nhà Minh đặt Đại Ngu thành quận Giao Chỉ, áp bức, bóc lột nặng nề, huỷ diệt văn hoá.","Từ khoá cần ghi nhớ: Lam Sơn;","Mốc sự kiện cần nhớ: Năm 1416: hội thề Lũng Nhai;","Năm 1416, Hội thề Lũng Nhai (Lê Lợi cùng 18 hào kiệt): Đầu năm 1418, Lê Lợi xưng Bình Định Vương, truyền hịch.","Năm 1424, theo kế của Nguyễn Chích…: Năm 1424, theo kế của Nguyễn Chích, nghĩa quân vào Nghệ An, giải phóng từ Thanh Hoá đến đèo Hải Vân."],"e":["Hay nhầm: Đây là năm Lê Lợi xưng Bình Định Vương.","Hay nhầm: Đây là năm giải phóng Nghệ An.","Hay nhầm: Đây là năm khởi nghĩa toàn thắng.","Hay nhầm: Đây là danh hiệu Đinh Bộ Lĩnh.","Hay nhầm: Ông lên ngôi hoàng đế sau năm 1428.","Hay nhầm: Đây là chức của Trần Hưng Đạo."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":1}}},{"t":"Bài 17. Đại Việt thời Lê sơ (1428 – 1527)","req":["Mô tả sự thành lập nhà Lê sơ.","Trình bày chính trị, kinh tế, xã hội, văn hoá; thành tựu thời Lê Thánh Tông; việc giữ vững chủ quyền lãnh thổ."],"sum":["Năm 1428, Lê Lợi lên ngôi hoàng đế, khôi phục tên nước Đại Việt, mở đầu nhà Lê sơ. Thời Lê Thánh Tông (1460 – 1497) là thời kì đỉnh cao.","Khái niệm: Năm 1428, Lê Lợi lên ngôi hoàng đế, khôi phục tên nước Đại Việt, mở đầu nhà Lê sơ.","Từ khoá cần ghi nhớ: Nhà Lê sơ;","Mốc sự kiện cần nhớ: Năm 1428: Lê Lợi lên ngôi, mở đầu nhà Lê sơ; năm 1484: bắt đầu dựng bia Tiến sĩ ở Văn Miếu","Luật pháp: Ban hành Quốc triều hình luật (Luật Hồng Đức).","Văn hoá: Nhiều tác phẩm giá trị như \"Dư địa chí\" (Nguyễn Trãi), \"Hồng Đức bản đồ\"."],"e":["Hay nhầm: Đây là năm khởi nghĩa Lam Sơn bắt đầu.","Hay nhầm: Đây là năm khởi nghĩa thắng lợi.","Hay nhầm: Đây là năm Lê Thánh Tông lên ngôi.","Hay nhầm: Ông là vua sau Lê Thánh Tông.","Hay nhầm: Đây là bộ luật thời Nguyễn.","Hay nhầm: Không phải bộ luật của Lê sơ."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":1}}}]},{"t":"Chương 7. Vùng đất phía nam Việt Nam từ đầu thế kỉ X đến đầu thế kỉ XVI","l":[{"t":"Bài 18. Vương quốc Chăm-pa và vùng đất Nam Bộ từ đầu thế kỉ X đến đầu thế kỉ XVI","req":["Trình bày sự phát triển của Vương quốc Chăm-pa.","Nêu những nét chính về vùng đất Nam Bộ thời kì này."],"sum":["Chăm-pa nằm ở vùng duyên hải miền Trung và Tây Nguyên ngày nay. Năm 988, Vương triều Vi-giay-a được thành lập, kinh đô đặt ở Vi-giay-a (Bình Định).","Khái niệm: Chăm-pa nằm ở vùng duyên hải miền Trung và Tây Nguyên ngày nay.","Từ khoá cần ghi nhớ: Chăm-pa;","Mốc sự kiện cần nhớ: Năm 988: thành lập Vương triều Vi-giay-a; năm 1069: vua Chăm cắt ba châu cho Đại Việt; năm 1471: Vi-giay-a suy sụp","Văn hoá Chăm-pa rực rỡ: Tháp Chăm, đền Mỹ Sơn, điêu khắc, chữ viết, lễ hội; có quan hệ giao lưu mật thiết với Đại Việt.","Vùng đất Nam Bộ thời kì này…: Vùng đất Nam Bộ thời kì này thuộc Vương quốc Chân Lạp (Cam-pu-chia) quản lí, vẫn còn thưa dân; cư dân Việt dần đến khai phá từ những thế kỉ sau."],"e":["Hay nhầm: Đây là năm cắt ba châu cho Đại Việt.","Hay nhầm: Đây là năm Vi-giay-a suy sụp.","Hay nhầm: Đây là năm Ngô Quyền xưng vương.","Hay nhầm: Đây không phải ba châu được nêu.","Hay nhầm: Đây không phải ba châu được nêu.","Hay nhầm: Đây không phải ba châu được nêu."],"q":{"n":5,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":1}}}]},{"t":"Chủ đề chung","l":[{"t":"Chủ đề chung 1. Các cuộc đại phát kiến địa lí","req":["Giải thích được nguyên nhân và các yếu tố tác động đến các cuộc đại phát kiến địa lí.","Mô tả được các cuộc đại phát kiến: Cô-lôm-bô tìm ra châu Mỹ, Ma-gien-lăng vòng quanh Trái Đất.","Phân tích được tác động của các cuộc đại phát kiến đối với tiến trình lịch sử."],"sum":["Nguyên nhân: nhu cầu tìm vàng bạc, hương liệu và con đường thương mại mới sang phương Đông, khi con đường bộ qua Tây Á bị người Thổ Nhĩ Kì kiểm soát.","Nguyên nhân: Nhu cầu tìm vàng bạc, hương liệu và con đường thương mại mới sang phương Đông, khi con đường bộ qua Tây Á bị người Thổ Nhĩ Kì kiểm soát.","Từ khoá cần ghi nhớ: Phát kiến địa lí; la bàn; kinh tế hàng hoá;","Mốc sự kiện cần nhớ: 1492: Cô-lôm-bô vượt Đại Tây Dương tìm ra châu Mỹ;","Cô-lôm-bô (1492) vượt Đại Tây Dương, tìm…: Cô-lôm-bô (1492) vượt Đại Tây Dương, tìm ra châu Mỹ (ông hiểu nhầm là Ấn Độ).","Tác động: Mở rộng hiểu biết về thế giới; thúc đẩy thương mại, giao lưu; tạo điều kiện cho chủ nghĩa tư bản ra đời; nhưng cũng gây nạn cướp bóc thuộc địa, buôn…"],"e":["Hay nhầm: Đây không phải nguyên nhân.","Hay nhầm: Đây không phải nguyên nhân ở châu Âu.","Hay nhầm: Đây không phải thiết bị hàng hải.","Hay nhầm: Thực tế nạn này tăng lên.","Hay nhầm: Giai cấp tư sản mạnh lên.","Hay nhầm: Đây không phải tác động chủ yếu."],"q":{"n":5,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":1}}},{"t":"Chủ đề chung 2. Đô thị: lịch sử và hiện tại","req":["Phân tích điều kiện địa lí và lịch sử góp phần hình thành đô thị cổ đại và trung đại.","Trình bày mối quan hệ giữa đô thị với các nền văn minh cổ đại; vai trò của thương nhân với đô thị châu Âu trung đại."],"sum":["Đô thị cổ đại thường hình thành ở nơi có điều kiện thuận lợi: gần sông lớn, đất đai màu mỡ, giao thông thuận tiện, là trung tâm chính trị, tôn giáo hoặc buôn bán.","Đô thị cổ đại thường hình thành ở nơi có điều kiện thuận lợi: Gần sông lớn, đất đai màu mỡ, giao thông thuận tiện, là trung tâm chính trị, tôn giáo hoặc buôn bán.","Từ khoá cần ghi nhớ: Đô thị cổ đại;","Mốc sự kiện cần nhớ: Đô thị trung đại châu Âu hình thành từ thủ công nghiệp và thương mại phát triển","Đô thị châu Âu thời trung đại…: Đô thị châu Âu thời trung đại hình thành từ thủ công nghiệp và thương mại phát triển.","Ngày nay đô thị vẫn là trung…: Ngày nay đô thị vẫn là trung tâm kinh tế, chính trị, văn hoá của mỗi quốc gia, nhưng cũng đặt ra vấn đề về dân cư, môi trường và giao thông cần giải…"],"e":["Hay nhầm: Không thuận lợi cho sản xuất.","Hay nhầm: Không phải điều kiện thuận lợi.","Hay nhầm: Thành thị làm suy yếu lãnh chúa."],"q":{"n":4,"lv":{"Biết":2,"Hiểu":1,"Vận dụng":1}}}]},{"t":"Bổ sung. Chủ quyền biển đảo Việt Nam (ngoài sách giáo khoa)","l":[{"t":"Bổ sung 1. Hoàng Sa, Trường Sa – bằng chứng lịch sử về chủ quyền của Việt Nam","req":["Khẳng định được Hoàng Sa, Trường Sa là một phần lãnh thổ không thể tách rời của Việt Nam.","Nêu được các bằng chứng lịch sử: đội Hoàng Sa, các thư tịch, châu bản và việc xác lập, thực thi chủ quyền của các triều đại."],"sum":["Lưu ý: nội dung này là bài bổ sung ngoài sách giáo khoa, được biên soạn để học sinh hiểu rõ chủ quyền biển đảo của Việt Nam.","Lưu ý: Nội dung này là bài bổ sung ngoài sách giáo khoa, được biên soạn để học sinh hiểu rõ chủ quyền biển đảo của Việt Nam.","Từ khoá cần ghi nhớ: Hoàng Sa;","Mốc sự kiện cần nhớ: Từ thế kỉ XVII, chúa Nguyễn lập đội Hoàng Sa, kiêm quản đội Bắc Hải","Hoàng Sa và Trường Sa là hai…: Hoàng Sa và Trường Sa là hai quần đảo của Việt Nam trên Biển Đông.","Từ thế kỉ XVII, chúa Nguyễn lập…: Từ thế kỉ XVII, chúa Nguyễn lập đội Hoàng Sa (kiêm quản đội Bắc Hải) gồm những người dân giỏi nghề đi biển, hằng năm ra các đảo khai thác hải sản,…"],"e":["Hay nhầm: Việt Nam đã xác lập và thực thi chủ quyền liên tục.","Hay nhầm: Điều này không đúng với lịch sử và luật pháp.","Hay nhầm: Đội này có từ trước đó rất lâu.","Hay nhầm: Ông viết Lịch triều hiến chương loại chí."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":1}}},{"t":"Bổ sung 2. Bảo vệ chủ quyền biển đảo: từ lịch sử đến hiện tại","req":["Nêu được một số mốc bảo vệ chủ quyền biển đảo của Việt Nam trong thế kỉ XX – XXI.","Hiểu được lập trường nhất quán của Việt Nam: giải quyết tranh chấp bằng biện pháp hoà bình, theo luật pháp quốc tế.","Biết trách nhiệm của học sinh trong việc giữ gìn chủ quyền biển đảo."],"sum":["Lưu ý: đây là bài bổ sung ngoài sách giáo khoa.","Lưu ý: Đây là bài bổ sung ngoài sách giáo khoa.","Từ khoá cần ghi nhớ: Bảo vệ chủ quyền;","Mốc sự kiện cần nhớ: 19–20/1/1974: Trung Quốc đánh chiếm nhóm đảo phía tây Hoàng Sa;","Trong lịch sử, nhiều chiến sĩ, ngư…: Trong lịch sử, nhiều chiến sĩ, ngư dân Việt Nam đã đổ máu để giữ biển đảo.","Việt Nam khẳng định: Chủ quyền đối với Hoàng Sa, Trường Sa là không thể tranh cãi; mọi hành động chiếm đóng bằng vũ lực đều là bất hợp pháp."],"e":["Hay nhầm: Việt Nam chủ trương hoà bình.","Hay nhầm: Việt Nam kiên quyết bảo vệ chủ quyền.","Hay nhầm: Trường Sa mới thuộc tỉnh này.","Hay nhầm: Đây là thái độ thiếu trách nhiệm.","Hay nhầm: Việt Nam chủ trương hoà bình."],"q":{"n":5,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":1}}}]}]}]},{"id":"diali","name":"Địa lí","b":[{"t":"Địa lí 7","c":[{"t":"Chương 1. Châu Âu","l":[{"t":"Bài 1. Vị trí địa lí, đặc điểm tự nhiên châu Âu","req":["Trình bày được vị trí địa lí, hình dạng và kích thước châu Âu.","Phân tích được đặc điểm địa hình, khí hậu; xác định được các sông lớn (Rai-nơ, Đa-nuýp, Vôn-ga)."],"sum":["Châu Âu nằm ở phía tây lục địa Á – Âu, ngăn cách với châu Á bởi dãy U-ran. Phần lớn lãnh thổ nằm giữa vĩ tuyến 36°B và 71°B, chủ yếu thuộc đới ôn hoà của bán cầu Bắc.","Khái niệm: Châu Âu nằm ở phía tây lục địa Á – Âu, ngăn cách với châu Á bởi dãy U-ran.","Từ khoá cần ghi nhớ: Vị trí; dãy U-ran;","Điểm nhấn ghi nhớ: Châu Âu ngăn với châu Á bởi dãy U-ran;","Hình dạng: Đường bờ biển bị cắt xẻ mạnh, tạo nhiều bán đảo, biển, vũng vịnh.","Địa hình gồm đồng bằng (chiếm 2/3 diện tích) và miền núi: Núi già ở phía bắc và trung tâm (Xcan-đi-na-vi, U-ran); núi trẻ ở phía nam (An-pơ, Các-pát, Ban-căng)."],"e":["Hay nhầm: Dãy này nằm trong châu Âu.","Hay nhầm: Dãy này ở phía bắc châu Âu.","Hay nhầm: Chỉ phần nhỏ phía bắc thuộc đới lạnh.","Hay nhầm: Đây là cận nhiệt địa trung hải.","Hay nhầm: Đây là khí hậu cực và cận cực.","Hay nhầm: Đây không phải núi châu Âu."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":1}}},{"t":"Bài 2. Đặc điểm dân cư, xã hội châu Âu","req":["Trình bày được đặc điểm cơ cấu dân cư, di cư và đô thị hoá ở châu Âu.","Phân tích được bảng số liệu về dân cư."],"sum":["Năm 2020, dân số châu Âu khoảng 747 triệu người (kể cả Liên bang Nga), đứng thứ tư thế giới.","Khái niệm: Năm 2020, dân số châu Âu khoảng 747 triệu người (kể cả Liên bang Nga), đứng thứ tư thế giới.","Từ khoá cần ghi nhớ: Dân số già; học vấn cao;","Điểm nhấn ghi nhớ: Năm 2020 dân số khoảng 747 triệu người, đứng thứ tư thế giới; khoảng 75% dân sống ở thành thị","Dân cư châu Âu có trình độ học vấn cao: Số năm đi học bình quân của người trên 25 tuổi là 11,8 năm (2020), thuộc hàng cao nhất thế giới.","Đô thị hoá: Có lịch sử lâu đời, gắn với công nghiệp hoá từ thế kỉ XIX; mức độ cao (75% dân cư sống ở thành thị)."],"e":["Hay nhầm: Đây là đặc điểm của châu Phi.","Hay nhầm: Số liệu cho thấy nhóm người cao tuổi tăng.","Hay nhầm: Chưa nằm trong nhóm được nêu.","Hay nhầm: Chưa nằm trong nhóm được nêu.","Hay nhầm: Chưa nằm trong nhóm được nêu."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":1}}},{"t":"Bài 3. Khai thác, sử dụng và bảo vệ thiên nhiên ở châu Âu","req":["Trình bày được một vấn đề bảo vệ môi trường ở châu Âu.","Biết khai thác thông tin qua hình ảnh."],"sum":["Bảo vệ môi trường không khí: kiểm soát khí thải; đánh thuế các-bon; phát triển công nghệ xanh, năng lượng tái tạo;","Bảo vệ môi trường không khí: Kiểm soát khí thải;","Từ khoá cần ghi nhớ: Bảo vệ môi trường không khí; bảo vệ nước;","Điểm nhấn ghi nhớ: Ở thành phố ưu tiên giao thông công cộng, xe đạp và đi bộ;","Bảo vệ môi trường nước: Kiểm soát chất thải nông nghiệp, xử lí nước thải sinh hoạt và công nghiệp, kiểm soát ô nhiễm từ kinh tế biển, nâng cao ý thức người dân.","Bảo vệ đa dạng sinh học: Ban hành chính sách bảo vệ và phát triển rừng bền vững, giảm ô nhiễm nước và đất."],"e":["Hay nhầm: Không phải hiện tượng được nêu.","Hay nhầm: Không phải hiện tượng được nêu.","Hay nhầm: Không phải hiện tượng được nêu."],"q":{"n":5,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":1}}},{"t":"Bài 4. Liên minh châu Âu","req":["Nêu được dẫn chứng về EU là một trong bốn trung tâm kinh tế lớn trên thế giới.","Phân tích được bảng số liệu về các trung tâm kinh tế lớn."],"sum":["Liên minh châu Âu (EU) hiện có 27 quốc gia thành viên. EU đã thiết lập một thị trường kinh tế duy nhất ở châu Âu, bao gồm lãnh thổ của tất cả các nước thành viên.","Liên minh châu Âu (EU) hiện có 27 quốc gia thành viên: EU đã thiết lập một thị trường kinh tế duy nhất ở châu Âu, bao gồm lãnh thổ của tất cả các nước thành viên.","Từ khoá cần ghi nhớ: Liên minh châu Âu (EU);","Điểm nhấn ghi nhớ: EU có 27 thành viên;","EU là một trong bốn trung tâm kinh tế lớn của thế giới: Có 3/7 nước công nghiệp hàng đầu thế giới; chiếm trên 31% giá trị xuất khẩu thế giới (2020);","Cách tính tỉ lệ GDP của EU: 15 192,6 / 84 705,4 × 100% ≈ 17,9%."],"e":["Hay nhầm: Đây là số nước ban đầu thời kì trước."],"q":{"n":5,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":1}}}]},{"t":"Chương 2. Châu Á","l":[{"t":"Bài 5. Vị trí địa lí, đặc điểm tự nhiên châu Á","req":["Trình bày được vị trí địa lí, hình dạng và kích thước châu Á.","Trình bày được đặc điểm địa hình, khoáng sản, khí hậu và ý nghĩa đối với sử dụng, bảo vệ tự nhiên."],"sum":["Châu Á tiếp giáp hai châu lục (châu Âu, châu Phi) và ba đại dương (Bắc Băng Dương, Thái Bình Dương, Ấn Độ Dương).","Khái niệm: Châu Á tiếp giáp hai châu lục (châu Âu, châu Phi) và ba đại dương (Bắc Băng Dương, Thái Bình Dương, Ấn Độ Dương).","Từ khoá cần ghi nhớ: Châu Á; diện tích 44,4 triệu km²; vùng núi cao; khoáng sản; khí hậu phân hoá; ba đại dương.","Điểm nhấn ghi nhớ: Châu Á là châu lục rộng nhất thế giới; trung tâm là vùng núi cao, đồ sộ và hiểm trở nhất","Địa hình: Trung tâm là vùng núi cao, đồ sộ, hiểm trở nhất thế giới; phía bắc là đồng bằng, cao nguyên thấp; phía đông thấp dần về biển; phía nam và tây nam có…","Khí hậu phân hoá đa dạng: Phía bắc ôn đới lục địa; phía đông và đông nam có khí hậu cận nhiệt gió mùa; sâu trong lục địa khô hạn;"],"e":["Hay nhầm: Châu Á không giáp Đại Tây Dương.","Hay nhầm: Còn giáp thêm hai đại dương nữa.","Hay nhầm: Đây là diện tích châu Phi.","Hay nhầm: Đây là diện tích châu Âu.","Hay nhầm: Đây là diện tích Ô-xtrây-li-a.","Hay nhầm: Phía bắc là đồng bằng, cao nguyên thấp."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":1}}},{"t":"Bài 6. Đặc điểm dân cư, xã hội châu Á","req":["Trình bày được đặc điểm dân cư, tôn giáo; sự phân bố dân cư và các đô thị lớn ở châu Á.","Rèn luyện kĩ năng phân tích số liệu."],"sum":["Châu Á có số dân đông nhất: 4 641,1 triệu người (2020), hơn một nửa dân số thế giới (59,5%).","Châu Á có số dân đông nhất: 4 641,1 triệu người (2020), hơn một nửa dân số thế giới (59,5%).","Từ khoá cần ghi nhớ: Dân số đông nhất; bốn tôn giáo lớn;","Điểm nhấn ghi nhớ: Năm 2020 có 4 641,1 triệu người, hơn một nửa dân số thế giới; bốn tôn giáo lớn ra đời ở châu Á","Dân số tăng nhanh nửa cuối thế…: Dân số tăng nhanh nửa cuối thế kỉ XX; nay mức tăng đã giảm (2015 – 2020: 0,95%, thấp hơn mức trung bình thế giới 1,09%).","Châu Á là nơi ra đời của bốn tôn giáo lớn: Ấn Độ giáo và Phật giáo (Ấn Độ), Ki-tô giáo (Pa-le-xtin), Hồi giáo (A-rập Xê-út)."],"e":["Hay nhầm: Không phải một trong bốn tôn giáo lớn nêu trong bài."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":1}}},{"t":"Bài 7. Bản đồ chính trị châu Á, các khu vực của châu Á","req":["Xác định được trên bản đồ các khu vực của châu Á.","Trình bày được đặc điểm tự nhiên của một số khu vực."],"sum":["Bắc Á gồm toàn bộ vùng Xi-bia của Nga; khí hậu lạnh giá, mang tính lục địa sâu sắc; khoáng sản phong phú; sông nhiều thuỷ năng (Ô-bi, I-ê-nít-xây, Lê-na); rừng lá kim rộng.","Khái niệm: Bắc Á gồm toàn bộ vùng Xi-bia của Nga; khí hậu lạnh giá, mang tính lục địa sâu sắc; khoáng sản phong phú; sông nhiều thuỷ năng (Ô-bi, I-ê-nít-xây,…","Từ khoá cần ghi nhớ: Bắc Á;","Điểm nhấn ghi nhớ: Trung Á là khu vực duy nhất của châu Á không tiếp giáp đại dương;","Trung Á là khu vực duy nhất…: Trung Á là khu vực duy nhất của châu Á không tiếp giáp đại dương, diện tích trên 4 triệu km²; khí hậu ôn đới lục địa khô, mưa 300 – 400 mm/năm; hai…","Tây Á gồm bán đảo A-ráp, Tiểu…: Tây Á gồm bán đảo A-ráp, Tiểu Á, đồng bằng Lưỡng Hà; chiếm hơn một nửa trữ lượng dầu mỏ thế giới; khí hậu khô hạn nóng; sông ngòi kém phát triển;…"],"e":["Hay nhầm: Giáp nhiều biển và đại dương.","Hay nhầm: Có dầu mỏ nhưng không bằng.","Hay nhầm: Số cũ trước khi Timor-Leste độc lập."],"q":{"n":5,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":1}}},{"t":"Bài 8. Thực hành: Tìm hiểu về các nền kinh tế lớn và kinh tế mới nổi của châu Á","req":["Biết sưu tầm tư liệu và trình bày về một nền kinh tế lớn hoặc mới nổi của châu Á: Trung Quốc, Nhật Bản, Hàn Quốc, Xin-ga-po.","Rèn luyện kĩ năng thu thập, xử lí thông tin và viết báo cáo."],"sum":["Bài thực hành gồm ba bước: chuẩn bị (chọn quốc gia, sưu tầm số liệu, bản đồ, hình ảnh); viết báo cáo; trình bày báo cáo trước lớp.","Bài thực hành gồm ba bước: Chuẩn bị (chọn quốc gia, sưu tầm số liệu, bản đồ, hình ảnh); viết báo cáo; trình bày báo cáo trước lớp.","Từ khoá cần ghi nhớ: Kinh tế lớn; kinh tế mới nổi; báo cáo; nguồn thông tin đáng tin cậy; ghi rõ nguồn.","Điểm nhấn ghi nhớ: Ba bước thực hành: chuẩn bị, viết báo cáo, trình bày trước lớp","Nội dung báo cáo gợi ý: Vị trí địa lí, dân cư; các ngành kinh tế chủ lực; thành tựu và vai trò của nền kinh tế đó ở châu Á và thế giới.","Nguồn thông tin cần đáng tin cậy…: Nguồn thông tin cần đáng tin cậy (niên giám thống kê, trang web cơ quan nhà nước, tổ chức quốc tế); khi trích dẫn cần ghi rõ nguồn."],"e":["Hay nhầm: Không nằm trong bốn lựa chọn của bài."],"q":{"n":4,"lv":{"Biết":2,"Hiểu":1,"Vận dụng":1}}}]},{"t":"Chương 3. Châu Phi","l":[{"t":"Bài 9. Vị trí địa lí, đặc điểm tự nhiên châu Phi","req":["Trình bày được vị trí địa lí, hình dạng và kích thước châu Phi.","Phân tích được đặc điểm tự nhiên và một số vấn đề môi trường trong sử dụng thiên nhiên."],"sum":["Châu Phi phía bắc giáp Địa Trung Hải, đông bắc giáp châu Á ở eo đất Xuy-ê (đã cắt bởi kênh đào Xuy-ê) và Biển Đỏ; phía đông, nam, tây giáp Ấn Độ Dương và Đại Tây Dương.","Khái niệm: Châu Phi phía bắc giáp Địa Trung Hải, đông bắc giáp châu Á ở eo đất Xuy-ê (đã cắt bởi kênh đào Xuy-ê) và Biển Đỏ; phía đông, nam, tây giáp Ấn Độ…","Từ khoá cần ghi nhớ: Eo đất Xuy-ê; khối cao nguyên; khoáng sản; bờ biển ít bị chia cắt; diện tích 30,3 triệu km².","Điểm nhấn ghi nhớ: Diện tích 30,3 triệu km², lớn thứ ba thế giới; gần như cả châu lục là cao nguyên, độ cao trung bình khoảng 750 m","Địa hình: Gần như cả châu lục là khối cao nguyên khổng lồ, độ cao trung bình khoảng 750 m; có rất ít núi cao và đồng bằng thấp.","Khí hậu khô nóng bậc nhất thế…: Khí hậu khô nóng bậc nhất thế giới (nhiệt độ trung bình năm trên 20°C)."],"e":["Hay nhầm: Đây là diện tích châu Âu.","Hay nhầm: Đây là diện tích Ô-xtrây-li-a.","Hay nhầm: Dầu mỏ tập trung ở Bắc Phi.","Hay nhầm: Đây là vấn đề ở vùng cực."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":1}}},{"t":"Bài 10. Đặc điểm dân cư, xã hội châu Phi","req":["Trình bày được các vấn đề dân cư, xã hội nổi cộm: tăng dân số cao, nạn đói, xung đột quân sự.","Biết một số di sản lịch sử nổi tiếng của châu Phi."],"sum":["Năm 2020, dân số châu Phi khoảng 1 340 triệu người, chiếm khoảng 17% dân số thế giới. Dân số tăng rất nhanh từ những năm 50 của thế kỉ XX, do đời sống được cải thiện, tỉ lệ tử giảm nhanh trong khi…","Khái niệm: Năm 2020, dân số châu Phi khoảng 1 340 triệu người, chiếm khoảng 17% dân số thế giới.","Từ khoá cần ghi nhớ: Dân số tăng nhanh;","Điểm nhấn ghi nhớ: Năm 2020 khoảng 1 340 triệu người, chiếm khoảng 17% dân số thế giới","Nạn đói: Mỗi năm hàng chục triệu người bị đe doạ, nặng nề nhất ở vùng nam hoang mạc Xa-ha-ra do hạn hán, bất ổn chính trị.","Xung đột quân sự: Do mâu thuẫn bộ tộc, tranh giành tài nguyên (đặc biệt là nước); hậu quả: thương vong, nạn đói, bệnh tật, di dân, bất ổn."],"e":["Hay nhầm: Không phải nguyên nhân chính.","Hay nhầm: Không phải nơi nặng nhất.","Hay nhầm: Không phải nơi nặng nhất."],"q":{"n":5,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":1}}},{"t":"Bài 11. Phương thức con người khai thác, sử dụng và bảo vệ thiên nhiên ở châu Phi","req":["Trình bày được cách con người khai thác, sử dụng và bảo vệ thiên nhiên ở các môi trường xích đạo, nhiệt đới, hoang mạc."],"sum":["Môi trường xích đạo (nóng ẩm quanh năm): trồng gối vụ, xen canh; lập các vùng chuyên canh cây công nghiệp (cọ dầu, ca cao...) để xuất khẩu; bảo vệ, trồng rừng để giữ tầng mùn khỏi bị rửa trôi.","Môi trường xích đạo (nóng ẩm quanh năm): Trồng gối vụ, xen canh; lập các vùng chuyên canh cây công nghiệp (cọ dầu, ca cao...) để xuất khẩu; bảo vệ, trồng rừng để giữ tầng mùn khỏi bị rửa…","Từ khoá cần ghi nhớ: Môi trường xích đạo; xavan; hoang mạc;","Điểm nhấn ghi nhớ: Môi trường xích đạo trồng cây công nghiệp để xuất khẩu; hoang mạc khai thác nước ở ốc đảo","Môi trường nhiệt đới: Vùng xavan khô hạn làm nương rẫy (lạc, bông, kê), chăn thả dê, cừu; vùng nhiệt đới ẩm trồng cây ăn quả, cây công nghiệp (mía, chè, cà phê...); khai…","Môi trường hoang mạc: Khai thác nước, trồng cây trong ốc đảo, chăn nuôi du mục, du lịch và khoáng sản; cần sử dụng tiết kiệm nước, chống hoang mạc hoá."],"e":["Hay nhầm: Phù hợp hơn với vùng khô hạn.","Hay nhầm: Là cây của môi trường xích đạo.","Hay nhầm: Phù hợp vùng nhiệt đới ẩm."],"q":{"n":5,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":1}}},{"t":"Bài 12. Thực hành: Tìm hiểu khái quát Cộng hoà Nam Phi","req":["Biết sưu tầm tư liệu về Cộng hoà Nam Phi; trình bày được một số sự kiện lịch sử trong mấy thập niên gần đây.","Rèn luyện kĩ năng phân tích tư liệu và viết, trình bày báo cáo."],"sum":["Các bước thực hành: chuẩn bị (chọn nội dung, sưu tầm thông tin); viết báo cáo; trình bày báo cáo trước lớp.","Các bước thực hành: Chuẩn bị (chọn nội dung, sưu tầm thông tin); viết báo cáo; trình bày báo cáo trước lớp.","Từ khoá cần ghi nhớ: Nam Phi; khoáng sản; phân biệt chủng tộc; báo cáo thực hành; nguồn tin.","Điểm nhấn ghi nhớ: Nam Phi giàu vàng, kim cương, đồng; lịch sử gần đây gắn với cuộc đấu tranh xoá bỏ phân biệt chủng tộc","Nam Phi là quốc gia có nhiều…: Nam Phi là quốc gia có nhiều khoáng sản (vàng, kim cương, đồng...), nằm ở cực nam châu Phi; lịch sử gần đây gắn với cuộc đấu tranh xoá bỏ chế độ…","Khi viết báo cáo, cần chọn lọc…: Khi viết báo cáo, cần chọn lọc thông tin chính xác, ghi rõ nguồn, trình bày rõ ràng, có hình ảnh, số liệu minh hoạ."],"e":["Hay nhầm: Dầu mỏ tập trung ở Bắc Phi."],"q":{"n":3,"lv":{"Biết":2,"Vận dụng":1}}}]},{"t":"Chương 4. Châu Mỹ","l":[{"t":"Bài 13. Vị trí địa lí, phạm vi châu Mỹ. Sự phát kiến ra châu Mỹ","req":["Trình bày được khái quát về vị trí địa lí, phạm vi châu Mỹ.","Phân tích được hệ quả địa lí – lịch sử của việc Cô-lôm-bô phát kiến ra châu Mỹ (1492 – 1502)."],"sum":["Châu Mỹ tiếp giáp Bắc Băng Dương (bắc), Đại Tây Dương (đông), Thái Bình Dương (tây). Châu Mỹ nằm hoàn toàn ở bán cầu Tây; phần đất liền trải từ khoảng 72°B đến 54°N (khoảng 126 vĩ độ).","Khái niệm: Châu Mỹ tiếp giáp Bắc Băng Dương (bắc), Đại Tây Dương (đông), Thái Bình Dương (tây).","Từ khoá cần ghi nhớ: Phát kiến; bán cầu Tây;","Điểm nhấn ghi nhớ: Châu Mỹ nằm hoàn toàn ở bán cầu Tây; mốc phát kiến ra châu Mỹ năm 1492","Hệ quả của phát kiến ra châu Mỹ: Tìm ra một châu lục mới; mở ra thời kì khám phá và chinh phục thế giới; người châu Âu sang xâm chiếm, khai thác nguyên liệu, khoáng sản và đưa văn…"],"e":["Hay nhầm: Không đúng, vì châu Mỹ trải cả hai bán cầu Bắc – Nam.","Hay nhầm: Là năm Đi-a-xơ đến mũi Hảo Vọng.","Hay nhầm: Là năm Ma-gien-lăng hoàn thành chuyến vòng quanh thế giới."],"q":{"n":5,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":1}}},{"t":"Bài 14. Đặc điểm tự nhiên Bắc Mỹ","req":["Trình bày được đặc điểm địa hình, khí hậu, sông, hồ và các đới thiên nhiên của Bắc Mỹ."],"sum":["Địa hình gồm ba khu vực: miền núi Coóc-đi-e ở phía tây (cao trung bình 3 000 – 4 000 m, dài 9 000 km), miền đồng bằng ở giữa (cao 200 – 500 m, thấp dần từ bắc xuống nam), dãy A-pa-lát ở phía đông…","Địa hình gồm ba khu vực: Miền núi Coóc-đi-e ở phía tây (cao trung bình 3 000 – 4 000 m, dài 9 000 km), miền đồng bằng ở giữa (cao 200 – 500 m, thấp dần từ bắc xuống nam),…","Từ khoá cần ghi nhớ: Coóc-đi-e;","Điểm nhấn ghi nhớ: Ba khu địa hình: Coóc-đi-e phía tây, đồng bằng ở giữa, A-pa-lát phía đông","Khí hậu phân hoá từ bắc xuống…: Khí hậu phân hoá từ bắc xuống nam (cực và cận cực, ôn đới, cận nhiệt, nhiệt đới), trong đó ôn đới có diện tích lớn nhất; ven biển điều hoà, càng vào…","Sông ngòi dày đặc (Mít-xu-ri – Mi-xi-xi-pi…: Sông ngòi dày đặc (Mít-xu-ri – Mi-xi-xi-pi, Mác-ken-di, Cô-lô-ra-đô)."],"q":{"n":5,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":1}}},{"t":"Bài 15. Đặc điểm dân cư, xã hội, phương thức khai thác tự nhiên bền vững ở Bắc Mỹ","req":["Trình bày được vấn đề nhập cư, chủng tộc và đô thị hoá ở Bắc Mỹ.","Xác định được một số trung tâm kinh tế quan trọng."],"sum":["Người Anh-điêng, E-xki-mô (chủng tộc Môn-gô-lô-it) di cư từ châu Á sang cách đây khoảng 20 – 30 nghìn năm.","Khái niệm: Người Anh-điêng, E-xki-mô (chủng tộc Môn-gô-lô-it) di cư từ châu Á sang cách đây khoảng 20 – 30 nghìn năm.","Từ khoá cần ghi nhớ: Người Anh-điêng; dân di cư;","Điểm nhấn ghi nhớ: Tỉ lệ dân đô thị ở Bắc Mỹ là 82,6% (2020); các đô thị lớn tạo thành hai dải siêu đô thị","Công nghiệp phát triển thúc đẩy đô thị hoá: Bắc Mỹ có tỉ lệ dân đô thị 82,6% (2020).","Một số trung tâm kinh tế: Van-cu-vơ, Xan Phran-xi-xcô, Lốt An-giơ-lét, Hau-xtơn, Si-ca-gô, Oa-sinh-tơn, Niu Oóc, Tô-rôn-tô, Môn-trê-an..."],"q":{"n":5,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":1}}},{"t":"Bài 16. Đặc điểm tự nhiên Trung và Nam Mỹ","req":["Trình bày được sự phân hoá tự nhiên theo chiều bắc – nam, đông – tây và theo độ cao ở Trung và Nam Mỹ."],"sum":["Theo chiều bắc – nam: đới khí hậu xích đạo (rừng mưa nhiệt đới), cận xích đạo (rừng thưa nhiệt đới), nhiệt đới, cận nhiệt, ôn đới.","Theo chiều bắc – nam: Đới khí hậu xích đạo (rừng mưa nhiệt đới), cận xích đạo (rừng thưa nhiệt đới), nhiệt đới, cận nhiệt, ôn đới.","Từ khoá cần ghi nhớ: Rừng mưa nhiệt đới; sơn nguyên;","Điểm nhấn ghi nhớ: Dãy An-đét cao trung bình 3 000–5 000 m; sườn đông có các đai thực vật theo độ cao","Theo chiều đông – tây ở Nam Mỹ: Phía đông là các sơn nguyên (Guy-a-na, Bra-xin);","Theo chiều cao ở sườn đông dãy…: Theo chiều cao ở sườn đông dãy An-đét có các đai thực vật nối tiếp từ chân núi lên đỉnh."],"e":["Hay nhầm: Mưa ít hơn, chủ yếu thảo nguyên.","Hay nhầm: Không phải đồng bằng rừng rậm nổi tiếng nhất."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":1}}},{"t":"Bài 17. Đặc điểm dân cư, xã hội Trung và Nam Mỹ, khai thác, sử dụng và bảo vệ rừng A-ma-dôn","req":["Trình bày được nguồn gốc dân cư, đô thị hoá và văn hoá Mỹ La-tinh.","Phân tích được vấn đề khai thác, sử dụng và bảo vệ rừng A-ma-dôn."],"sum":["Dân cư Trung và Nam Mỹ gồm người Anh-điêng (Môn-gô-lô-it cổ), người gốc châu Âu (Tây Ban Nha, Bồ Đào Nha), người gốc Phi và người lai.","Khái niệm: Dân cư Trung và Nam Mỹ gồm người Anh-điêng (Môn-gô-lô-it cổ), người gốc châu Âu (Tây Ban Nha, Bồ Đào Nha), người gốc Phi và người lai.","Từ khoá cần ghi nhớ: Người Anh-điêng; người lai;","Điểm nhấn ghi nhớ: Tỉ lệ dân đô thị khoảng 80% (2020); rừng A-ma-dôn rộng trên 5 triệu km², là rừng nhiệt đới rộng nhất thế giới","Văn hoá Mỹ La-tinh gồm các nền…: Văn hoá Mỹ La-tinh gồm các nền văn hoá cổ (May-a, In-ca, A-dơ-tếch), lễ hội (Ca-na-van...), điệu nhảy La-tinh; ngôn ngữ chính là tiếng Tây Ban Nha,…","Rừng A-ma-dôn có diện tích trên 5…: Rừng A-ma-dôn có diện tích trên 5 triệu km², là rừng nhiệt đới rộng nhất thế giới; khí hậu nóng ẩm, sinh vật phong phú, rừng nhiều tầng."],"e":["Hay nhầm: Là ngôn ngữ chính ở Bắc Mỹ."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":1}}}]},{"t":"Chương 5. Châu Đại Dương và châu Nam Cực","l":[{"t":"Bài 18. Châu Đại Dương","req":["Trình bày được đặc điểm vị trí địa lí, địa hình, khí hậu, dân cư của lục địa Ô-xtrây-li-a.","Phân tích được phương thức khai thác, sử dụng và bảo vệ thiên nhiên."],"sum":["Lục địa Ô-xtrây-li-a nằm cách biệt các châu lục khác, ở tây nam Thái Bình Dương, thuộc bán cầu Nam.","Khái niệm: Lục địa Ô-xtrây-li-a nằm cách biệt các châu lục khác, ở tây nam Thái Bình Dương, thuộc bán cầu Nam.","Từ khoá cần ghi nhớ: Ô-xtrây-li-a; châu Đại Dương; sơn nguyên Tây;","Điểm nhấn ghi nhớ: Lục địa Ô-xtrây-li-a diện tích 7,7 triệu km², nằm ở bán cầu Nam","Địa hình ba khu vực: Sơn nguyên Tây Ô-xtrây-li-a (nhiều hoang mạc), đồng bằng Trung Tâm (độ cao dưới 200 m), dãy Trường Sơn Ô-xtrây-li-a (cao 800 – 1 000 m).","Phần lớn lãnh thổ thuộc đới nóng…: Phần lớn lãnh thổ thuộc đới nóng; khí hậu thay đổi từ bắc xuống nam và từ đông sang tây."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":1}}},{"t":"Bài 19. Châu Nam Cực","req":["Trình bày được lịch sử khám phá, vị trí địa lí, đặc điểm tự nhiên và tài nguyên của châu Nam Cực.","Hiểu được thiên nhiên Nam Cực có thể thay đổi khi biến đổi khí hậu toàn cầu."],"sum":["Mốc khám phá: 1820 Bê-linh-hao-den và La-da-rép phát hiện lục địa Nam Cực; 14 – 12 – 1911 A-mun-sen tới điểm cực Nam của Trái Đất; từ 1957 việc nghiên cứu được xúc tiến mạnh mẽ.","Mốc khám phá: 1820 Bê-linh-hao-den và La-da-rép phát hiện lục địa Nam Cực;","Từ khoá cần ghi nhớ: Nam Cực; cao nguyên băng;","Điểm nhấn ghi nhớ: Mốc: 1820 phát hiện lục địa;","Vị trí: Nằm trong phạm vi phía nam vòng cực Nam, đại dương bao quanh, cách xa các châu lục khác, gần như hoàn toàn trong đới lạnh.","Địa hình là cao nguyên băng khổng…: Địa hình là cao nguyên băng khổng lồ; khí hậu lạnh và khô nhất thế giới; gió bão nhiều nhất; sinh vật nghèo nàn (rêu, địa y, chim cánh cụt, hải cẩu,…"],"q":{"n":6,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":1}}}]},{"t":"Bổ sung. Biển Đông, Hoàng Sa, Trường Sa (ngoài sách giáo khoa)","l":[{"t":"Bổ sung. Biển Đông và hai quần đảo Hoàng Sa, Trường Sa của Việt Nam","req":["Xác định được vị trí Biển Đông và hai quần đảo Hoàng Sa, Trường Sa trên bản đồ.","Nêu được vai trò của Biển Đông và khẳng định Hoàng Sa, Trường Sa là của Việt Nam."],"sum":["Lưu ý: đây là bài bổ sung ngoài sách giáo khoa.","Lưu ý: Đây là bài bổ sung ngoài sách giáo khoa.","Từ khoá cần ghi nhớ: Biển Đông;","Điểm nhấn ghi nhớ: Hoàng Sa thuộc Đà Nẵng, Trường Sa thuộc Khánh Hoà;","Biển Đông là biển lớn ở phía…: Biển Đông là biển lớn ở phía đông Việt Nam, thuộc Thái Bình Dương, bao quanh bởi nhiều nước.","Quần đảo Hoàng Sa nằm khoảng 15°45′B…: Quần đảo Hoàng Sa nằm khoảng 15°45′B – 17°15′B, 111°Đ – 113°Đ, ngoài khơi miền Trung."],"e":["Hay nhầm: Việt Nam đã xác lập và thực thi chủ quyền.","Hay nhầm: Việt Nam có đủ bằng chứng lịch sử và pháp lí.","Hay nhầm: Việt Nam chủ trương hoà bình.","Hay nhầm: Việt Nam kiên quyết bảo vệ chủ quyền."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":1}}}]}]}]}]};
